INSERT INTO `ai_prep_question_bank`
    (`category`, `subject`, `concept`, `difficulty_level`, `scope`, `time_limit_seconds`, `question_text`, `ground_truth`, `is_active`)
VALUES
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'MEDIUM', 'SPECIFIC', 180, 'What characteristics define an AI agent, and how do its core components (tools, memory, planning, control) interact during execution?', '{"required_evidence": ["Explains that an AI agent is a system that uses a model or decision mechanism to select and execute actions toward a goal within an environment.", "Explains the control loop (perception-deliberation-action) that coordinates planning (decomposing goals into sub-tasks), memory retrieval, and tool invocation.", "Details how execution results and observations from tools are fed back into memory and the control loop to iteratively adjust subsequent planning and actions."], "supporting_evidence": ["References cognitive architectures (e.g., OODA loop, ReAct framework) as formal foundations for agent execution loops.", "Distinguishes between stateless model execution and stateful agent systems maintained via persistent state graphs.", "May mention specific implementation examples such as: short-term conversation state and long-term vector/episodic memory"], "negative_evidence": ["Conflates a standard one-shot prompt-response LLM completion or basic RAG pipeline with an autonomous agent.", "Claims agents operate without the need for memory or iterative feedback loops."], "partial_credit": ["Identifies the core components (tools, memory, planning, control) but fails to explain the cyclic feedback loop between tool observations and replanning."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'SPECIFIC', 180, 'What is the difference between LangChain and LangGraph? What are their strengths and limitations, and when would you choose each?', '{"required_evidence": ["Defines LangChain as primarily suited for linear chains and DAG workflows (LCEL pipelines), while LangGraph is designed for cyclic graphs, complex state machines, and multi-agent coordination.", "Highlights LangGraph''s core strengths: explicit state schemas, cyclic loops (reflection, retries), fine-grained checkpointing/time-travel, and native human-in-the-loop support.", "Highlights LangChain''s strengths and limitations (cumbersome for non-linear stateful logic, rigid abstractions)."], "supporting_evidence": ["Explains when to choose LangChain (simple document QA, straightforward RAG pipelines) vs LangGraph (autonomous agent loops, code generation with validation loops, multi-agent systems).", "Mentions LangGraph''s persistence backends (MemorySaver, PostgresSaver) enabling paused graph execution and resumption.", "May mention specific implementation examples such as: rapid prototyping, extensive library of pre-built integrations"], "negative_evidence": ["Claims LangChain and LangGraph are mutually exclusive frameworks that cannot share message schemas or integrations.", "States that LangChain handles loops and complex branching just as easily as LangGraph without workarounds."], "partial_credit": ["Explains that LangGraph uses graphs and LangChain uses chains, but cannot articulate cyclic execution or state persistence differences."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Tool Calling & Execution', 'MEDIUM', 'SPECIFIC', 180, 'What type of object does a successful tool call return (string, list, dict, message object), and how would you confirm from the response that the call actually succeeded?', '{"required_evidence": ["Return Type: In LLM protocol specifications, the tool execution output sent back to the model typically returns a string, or content blocks in frameworks like Anthropic.", "Confirmation of Success: Structural status indicators in the returned payload ; verifying HTTP 200/database commit confirmations before returning the string to the model.", "Model Receipt: Confirming the model acknowledges the tool output in subsequent turns (finish_reason: ''stop'' without further tool calls or emitting final synthesized text referencing the result)."], "supporting_evidence": ["Notes that sending excessive raw JSON payloads can overflow context; outputs should be summarized or projected to essential fields.", "Mentions LangChain''s ToolMessage object format containing content, tool_call_id, and artifact fields.", "May mention specific implementation examples such as: OpenAI, Anthropic, typically stringified JSON, plain text, or encapsulated in a ToolMessage/ChatMessage object with role: ''tool'', e.g., {''status'': ''success'', ''data'': {...}} vs {''status'': ''error'', ''message'': ''...''}"], "negative_evidence": ["Believes you can pass raw native Python objects (like open socket connections or raw unpickled classes) directly into the LLM context without string serialization."], "partial_credit": ["States that tools return JSON or text, but does not detail how success is verified programmatically or how the tool message is structured for the model."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'What considerations apply to AI in healthcare or manufacturing, and how do you build a pilot MVP in a regulated domain?', '{"required_evidence": ["Domain-specific regulatory and safety standards: healthcare mandates, manufacturing mandates, requiring risk management and validation.", "Data integrity, quality, and privacy: handling noisy sensor telemetry or protected health information (PHI), ensuring de-identification, robust calibration against sensor drift, and comprehensive data lineage tracking.", "Pilot MVP strategy: scoping down to a low-risk, assistive decision-support use case with strict human-in-the-loop review and comprehensive audit logs."], "supporting_evidence": ["Discusses shadow/parallel deployment in the pilot phase (running the AI alongside human operators to benchmark precision/recall against historical ground truth without live operational risk).", "Mentions edge deployment constraints in manufacturing (industrial gateways, low-latency inferencing without cloud reliance).", "May mention specific implementation examples such as: HIPAA, FDA SaMD - Software as a Medical Device, IEC 62304, ISO 9001, OSHA, functional safety IEC 61508, e.g., documentation drafting or predictive maintenance advisory rather than autonomous clinical diagnosis or robotic machine control"], "negative_evidence": ["Proposes deploying an unvalidated, black-box generative AI directly into active clinical treatment or automated machinery control without human verification.", "Assumes regulatory compliance can be completely bypassed by labeling the product a ''pilot MVP''."], "partial_credit": ["Mentions that healthcare has HIPAA and manufacturing has safety rules, and recommends keeping humans in the loop for the MVP, but lacks specific regulatory framework references (SaMD/ISO) or risk-tiered deployment strategies."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 180, 'How do you deploy agent systems, and what matters for production readiness?', '{"required_evidence": ["Describes deployment architectures: containerized microservices, serverless/asynchronous event-driven task workers, and state persistence stores.", "Details key production readiness pillars: observability & tracing (distributed traces, tool execution telemetry, token usage, latency), security & sandboxing, and reliability (circuit breakers, timeouts, retries).", "Explains evaluation and safety gates: regression testing against golden benchmark datasets, rate limiting, and human-in-the-loop escalation paths for destructive actions."], "supporting_evidence": ["Discusses cost management (token budgets, model routing between small and large LLMs, semantic caching).", "Covers blue/green or canary deployment patterns for updating prompts, agent graphs, and tool schemas without downtime.", "May mention specific implementation examples such as: Docker/Kubernetes, Temporal, Celery, AWS ECS/Lambda, Redis, Postgres"], "negative_evidence": ["Believes deploying an agent is just running a local Streamlit or FastAPI script with an OpenAI API key in a plain .env file.", "Ignores the non-deterministic nature of agents, lacking timeouts, recursion limits, or sandboxing for external tool actions."], "partial_credit": ["Mentions containerizing the app with Docker and deploying to the cloud with logging, but misses state persistence, sandboxing, or evaluation gates."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'MEDIUM', 'SPECIFIC', 180, 'When should you use agents versus traditional deterministic or rule-based systems, and when should you avoid agents?', '{"required_evidence": ["When to use: Unstructured inputs (natural language, ambiguous requests), open-ended multi-step problem solving, dynamic tool selection across heterogeneous APIs, or tasks requiring adaptive reasoning where permutations are too vast for hardcoded rules.", "When to avoid: Strict deterministic compliance/financial calculations, low-latency mission-critical systems, safety-critical controls without human oversight, or tasks with fixed, well-defined state machines where traditional code is 100% reliable, faster, and cheaper.", "Emphasizes the trade-offs: Non-determinism, latency overhead, inference cost, and hallucination risk vs flexibility and language understanding."], "supporting_evidence": ["Advocates for a hybrid approach: deterministic code for orchestrating known sub-flows and agents only for semantic judgment or fuzzy translation.", "May mention specific implementation examples such as: sub-50ms"], "negative_evidence": ["Claims agents should replace all traditional backend code, ETL pipelines, or deterministic CRUD logic."], "partial_credit": ["Identifies that agents are good for natural language and bad for math, but does not provide robust engineering criteria based on determinism, latency, and cost."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'Where do you draw the boundary between prompt-based policy, tool-use rules and code-based enforcement (rate limits, allow lists, state machines)?', '{"required_evidence": ["Prompt-based policy: Used for soft guidance, tone, style, contextual domain interpretation, and intent disambiguation; explicitly recognized as untrusted and vulnerable to jailbreaks or drift.", "Tool-use rules: Expressed in JSON schemas, tool descriptions, and pre-invocation argument validation to constrain parameter types, ranges, and required fields.", "Code-based enforcement: Hard, deterministic security boundaries in the execution runtime (authorization checks, role-based access control, allow/deny lists, strict rate limits, deterministic state machine transitions, human approval gates).", "Explicit architectural rule: Security, safety, and business-critical invariants must NEVER rely solely on prompt instructions; they must be enforced deterministically in application code."], "supporting_evidence": ["Discusses defense-in-depth architecture combining input guardrails (NeMo Guardrails, Llama Guard) with zero-trust backend API execution.", "Explains sandbox isolation for tool execution (e.g., e2b or Docker containers).", "May mention specific implementation examples such as: Pydantic models"], "negative_evidence": ["Believes system prompts are sufficient to prevent unauthorized tool execution, data leakage, or malicious parameter injection."], "partial_credit": ["Explains what each component does but fails to establish code-based enforcement as the non-negotiable security boundary."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'HARD', 'SPECIFIC', 240, 'How do you translate a business workflow into an agentic design and break a large automation problem into smaller agent tasks?', '{"required_evidence": ["Analyzes the business process to identify distinct functional boundaries, inputs/outputs, dependencies, decision points, and failure modes.", "Decomposes monolithic problems into specialized, single-responsibility sub-tasks.", "Defines structured communication schemas and state transitions between tasks, selecting appropriate coordination patterns."], "supporting_evidence": ["Discusses identifying human-in-the-loop checkpoints for high-risk decisions within the workflow.", "Mentions establishing task-level SLAs, metrics, and isolated regression tests for each decomposed unit.", "May mention specific implementation examples such as: e.g., ingestion/extraction -> validation -> domain reasoning -> execution/action -> audit, Pydantic contracts, hierarchical supervisor, sequential pipeline, or router"], "negative_evidence": ["Attempts to dump the entire business logic into a single monolithic agent prompt with dozens of heterogeneous tools."], "partial_credit": ["Describes breaking tasks down into steps but lacks formal state representation, interface definitions, or orchestration architecture."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'MEDIUM', 'SPECIFIC', 180, 'What design patterns are common in agentic solutions (router, orchestrator/supervisor, graph-based)?', '{"required_evidence": ["Router: A classifier (LLM or rule-based) that inspects an incoming request and directs it to a single dedicated specialized agent or pipeline.", "Orchestrator / Supervisor: A central agent that receives the goal, dynamically breaks it into subtasks, delegates them to specialized worker agents, monitors progress, and synthesizes the final response.", "Graph-based (State Graph): A structured workflow modeled as a directed graph where nodes are compute steps/agents and edges represent deterministic or conditional transitions, supporting nodes, transitions, conditional routing, and cycles."], "supporting_evidence": ["Mentions additional patterns such as Hierarchical Multi-Agent, Map-Reduce/Parallel fan-out, and Reflection/Critic-Actor patterns.", "Compares trade-offs in debugging complexity and latency between router (fast, low cost) and supervisor/graph (dynamic, complex)."], "negative_evidence": ["Treats router and supervisor as identical, or confuses graph-based agents with knowledge graphs."], "partial_credit": ["Names the three patterns but fails to explain the architectural differences and data flow mechanics among them."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Concurrency & Parallelism', 'HARD', 'SPECIFIC', 240, 'What is a race condition, and how do locks prevent it? What are the trade-offs of a single lock versus multiple locks?', '{"required_evidence": ["Defines a race condition as concurrent access to shared state causing unpredictable results.", "Explains how mutexes/locks serialize access.", "Contrasts coarse-grained lock bottlenecks with fine-grained deadlock risks."], "supporting_evidence": ["May discuss specific lock implementations in Python (threading.Lock)."], "negative_evidence": ["Confuses race conditions with general asynchronous execution overhead."], "partial_credit": ["Defines race conditions but struggles with the trade-offs of multiple locks."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Concurrency & Parallelism', 'HARD', 'SPECIFIC', 240, 'How would you design fine-grained locking or sharding for a highly concurrent system?', '{"required_evidence": ["Explains strategies for partitioning data to minimize lock contention.", "Discusses distributing requests across independent buckets or shards."], "supporting_evidence": ["May discuss hash functions for key distribution or atomic operations."], "negative_evidence": ["Proposes a single global lock for a highly concurrent partitioned system."], "partial_credit": ["Understands sharding conceptually but cannot explain how it reduces lock contention."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'When do you choose prompt engineering, RAG, fine-tuning or pre-training? Why do many enterprises avoid fine-tuning?', '{"required_evidence": ["Articulates selection criteria: Prompt Engineering for fast POCs, general knowledge, and formatting; RAG for dynamic/frequently updated proprietary knowledge and verifiable source citations; Fine-tuning for specialized style, tone, domain vocabulary, or complex task adaptation ; Pre-training for entirely novel domains/languages with massive unlabelled corpora.", "Explains why enterprises avoid fine-tuning: immense data engineering overhead (curating, cleaning, labeling thousands of high-quality examples); risk of catastrophic forgetting and hallucinations; high compute and GPU operational costs; maintenance burden (re-tuning when base models upgrade); and inability to easily update knowledge compared to RAG indexing.", "Compares RAG vs Fine-tuning for knowledge injection: highlights that fine-tuning is poor at memorizing factual information and lacks citations, whereas RAG dynamically accesses real-time data with strict access control."], "supporting_evidence": ["Mentions hybrid architectures (RAG combined with a fine-tuned SLM) to get the benefits of both domain syntax and dynamic external knowledge.", "Discusses enterprise security and data privacy: RAG can enforce document-level ACLs, which fine-tuning model weights cannot do.", "May mention specific implementation examples such as: e.g. SQL dialect, structured output compliance, 100B+ tokens"], "negative_evidence": ["Recommends fine-tuning as the primary method to inject rapidly changing real-time enterprise facts.", "Assumes pre-training from scratch is a routine, low-cost choice for typical business use cases."], "partial_credit": ["Defines the four approaches correctly, but fails to explain enterprise hurdles regarding fine-tuning (catastrophic forgetting, ACLs, data curation cost)."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'HARD', 'SPECIFIC', 240, 'Describe an end-to-end multi-agent architecture: the agents, their roles, the supervisor pattern, and how many tools each agent has.', '{"required_evidence": ["Outlines a clear concrete multi-agent system specifying distinct agent roles.", "Explains the Supervisor pattern: The supervisor receives the user objective, maintains global state, decides which specialized worker to invoke next, passes scoped sub-contexts, and aggregates worker outputs.", "Addresses tool allocation principle: Tools should be tightly scoped and minimized per worker agent to reduce tool hallucination and cognitive load, while the supervisor often has no execution tools other than delegation/handoff tools."], "supporting_evidence": ["Discusses shared state versus private agent state, preventing cross-agent context pollution.", "Mentions termination conditions and fallback escalation paths when a worker fails.", "May mention specific implementation examples such as: e.g., Customer Support, Research & Report Generation, or Incident Triage, e.g., Planner/Supervisor, Specialized Worker Agents, Validator/Guardrail Agent, typically 1-4 highly focused domain tools per agent"], "negative_evidence": ["Assigns every tool to every agent or gives the supervisor dozens of operational execution tools, defeating modularization."], "partial_credit": ["Lists several agents and tools but lacks an end-to-end flow description or gives unrealistic tool distributions."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'MEDIUM', 'SPECIFIC', 180, 'What are the purpose, benefits and trade-offs of multi-agent versus single-agent architectures?', '{"required_evidence": ["Purpose & Benefits: Separation of concerns, specialized system prompts with reduced context clutter, modular testing/evaluation, isolated tool scopes per agent, and potential for parallel task execution.", "Trade-offs & Costs: Higher latency (multiple sequential LLM calls), multiplied token costs, compounding error propagation (errors in upstream agents derail downstream agents), and significantly increased debugging/observability complexity.", "Guideline: Start with a single agent with well-defined tools; split into multi-agent only when prompt complexity, tool confusion, or independent domain boundaries strictly necessitate it."], "supporting_evidence": ["Discusses context window degradation when a single agent has small, focused set of tools (typically under 10-15) vs multi-agent routing.", "Mentions state synchronization overhead and distributed tracing challenges."], "negative_evidence": ["Assumes multi-agent is inherently superior for all applications regardless of complexity or cost."], "partial_credit": ["Lists benefits like modularity but fails to articulate key trade-offs such as compounded latency, token costs, and debugging friction."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'MEDIUM', 'SPECIFIC', 180, 'How does an orchestrator or supervisor plan, delegate, sequence tasks, handle dependencies, run agents in parallel, terminate workflows and aggregate responses?', '{"required_evidence": ["Planning & Delegation: Breaks the prompt into a task graph (DAG), mapping tasks to specialized worker agents using structured function calls or routing tables.", "Sequencing & Dependencies: Analyzes task prerequisites; independent tasks run concurrently while dependent tasks wait for upstream outputs in the state graph.", "Parallel Execution & Aggregation: Concurrently dispatches worker calls, awaits resolution, merges partial outputs into a consolidated state, and feeds aggregated facts to a synthesizer agent or prompt.", "Termination: Monitors stop criteria (goal achieved, max iterations reached, validation passed, or unrecoverable error) and prevents infinite execution loops."], "supporting_evidence": ["Explains map-reduce and fan-out/fan-in patterns within agent frameworks like LangGraph or Autogen.", "Discusses handling partial worker failures using circuit breakers or fallback branches.", "May mention specific implementation examples such as: e.g. via async gather/fan-out"], "negative_evidence": ["Claims parallel LLM calls automatically synchronize state without an underlying state manager or coordination engine."], "partial_credit": ["Explains high-level planning and sequential calls but skips dependency resolution, concurrency mechanics, or termination conditions."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'HARD', 'SPECIFIC', 240, 'How do you design intent detection and routing (system prompt components, few-shot classification prompts, model-based versus rule-based classification), and how do you improve routing accuracy?', '{"required_evidence": ["Prompt Architecture: System prompt defining clear, mutually exclusive intent categories with exact boundaries, edge-case explanations, and negative guidelines (what not to route).", "Few-Shot Examples: Curating balanced, high-variance few-shot examples representing boundary cases, ambiguous queries, and colloquial phrasing.", "Model-based vs Rule-based: Combining deterministic rules (keywords, regex, auth state) for unambiguous cases with fast SLMs/embeddings for semantic classification.", "Improving Accuracy: Generating synthetic test queries, maintaining golden evaluation sets, analyzing confusion matrices, adding confidence scoring with fallback clarification loops, and structured output schemas (Enums)."], "supporting_evidence": ["Mentions fine-tuning a small classifier (e.g. SetFit, DeBERTa, or fine-tuned Llama) to achieve sub-20ms latency and high accuracy.", "Discusses routing calibration: prompting the model to output a confidence score or using logprobs."], "negative_evidence": ["Relies on open-ended text generation without constrained Pydantic enums for intent classification output."], "partial_credit": ["Mentions system prompts and few-shot examples but lacks evaluation methodologies (confusion matrices, golden datasets) or confidence-based escalation."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'MEDIUM', 'SPECIFIC', 180, 'How do you handle incomplete or ambiguous user queries in orchestration?', '{"required_evidence": ["Detection: The orchestrator or input guardrail checks required parameters against the target task/tool schema and identifies missing or ambiguous slots.", "Clarification Loop: Instead of guessing or hallucinating missing parameters, the agent transitions to a conversational clarification state to prompt the user directly for specific missing details.", "Contextual Disambiguation: Leverages historical conversation memory, user profile metadata, or session context to resolve ambiguities before asking the user."], "supporting_evidence": ["Mentions slot-filling patterns and Pydantic schema validation failures triggering conversational recovery.", "Discusses presenting candidate interpretations to the user as quick-reply options rather than open-ended queries."], "negative_evidence": ["Recommends guessing user parameters blindly or executing irreversible actions with default/made-up values."], "partial_credit": ["States that the agent should ask the user for clarification, but does not explain how ambiguity is detected against schema requirements or state management."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'MEDIUM', 'SPECIFIC', 180, 'How do you decide agent roles and manage communication between agents? Do agents talk directly or through central coordination? What protocols and data formats are used?', '{"required_evidence": ["Role Definition: Follows the Single Responsibility Principle; decomposes roles by domain expertise, tool ownership, or security boundaries.", "Communication Topologies: Central coordination simplifies state, auditing, and debugging; peer-to-peer (decentralized / choreographic) allows direct agent handoffs but risks loops, deadlocks, and difficult tracing.", "Protocols & Data Formats: Uses strongly typed structured messages with standardized metadata (sender, recipient, task_id, trace_id, state payload) over gRPC, HTTP REST, or internal state dictionaries."], "supporting_evidence": ["References established agent communication frameworks such as AutoGen, LangGraph StateGraph, or CrewAI.", "Discusses using event brokers (Kafka, RabbitMQ, Redis Pub/Sub) for asynchronous multi-agent distributed systems.", "May mention specific implementation examples such as: e.g., Billing Agent vs Technical Agent, hub-and-spoke / supervisor, JSON, Pydantic schemas, or Protocol Buffers"], "negative_evidence": ["Advocates for free-form unconstrained natural language chat between agents without structured schemas or trace IDs."], "partial_credit": ["Describes supervisor vs direct communication but lacks specificity regarding data contracts, message schemas, or protocol selection."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'What role do guardrail agents play in protecting sensitive data, and what guardrail and security challenges arise in banking?', '{"required_evidence": ["Guardrail Agent Role: Acts as an inline security layer that evaluates input prompts and model responses to enforce compliance, detect prompt injection/jailbreaks, and redact sensitive data.", "Banking Security Challenges: Strict regulatory compliance, prevention of PII/financial data exfiltration (account numbers, SSNs, balances), and avoiding unauthorized financial advice or transactions.", "Mitigation Strategies: Pre-inference PII tokenization/masking, strict RBAC tied to authenticated banking sessions, deterministic business rule enforcement over LLM reasoning, and immutable audit logs."], "supporting_evidence": ["Discusses latency overhead introduced by sequential LLM guardrail calls and how lightweight classifiers/regex mitigate it.", "Mentions adversarial red-teaming against financial phishing and prompt injection attacks.", "May mention specific implementation examples such as: e.g., GLBA, PCI-DSS, GDPR, e.g., Presidio"], "negative_evidence": ["Claims general-purpose public LLMs can be trusted directly with raw unmasked customer banking data.", "Believes financial advice disclaimers in system prompts are legally and technically sufficient guardrails."], "partial_credit": ["Identifies PII masking and preventing financial fraud, but lacks technical details on guardrail architectures, tokenization, or regulatory compliance."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'MEDIUM', 'SPECIFIC', 180, 'How do planner, validator, fallback, policy, reasoning, memory and guardrail agents collaborate?', '{"required_evidence": ["Defines distinct responsibilities: Planner decomposes user goal into steps; Reasoning executes domain-specific problem solving; Guardrail/Policy checks input/output safety; Validator checks tool output correctness; Fallback handles degraded paths; Memory maintains cross-turn context.", "Traces collaborative flow: Input -> Guardrail checks safety -> Planner breaks down problem with Memory retrieval -> Reasoning agent calls tools -> Validator evaluates results against expectations -> If invalid, Fallback recovers or Planner replans -> Policy verifies final output before delivery.", "Architectural implementation: Structured state machine or directed acyclic graph (DAG) routing payloads conditionally based on validation status."], "supporting_evidence": ["Discusses Actor-Critic and Self-Reflective architectures (e.g., Reflexion).", "Addresses cost/latency implications of having multiple specialized agents in a single user query pipeline."], "negative_evidence": ["Suggests all these agents should converse in an unstructured chat room without deterministic state transitions."], "partial_credit": ["Defines most agent roles correctly but fails to provide a cohesive sequential or graph-based collaboration architecture."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'MEDIUM', 'SPECIFIC', 180, 'How do you decompose complex queries in a reasoning agent and coordinate execution?', '{"required_evidence": ["Query Decomposition Techniques: Utilizing Plan-and-Solve, Least-to-Most prompting, or Sub-Question Query Engines to break an ambiguous/multi-part question into atomic, logically ordered sub-queries.", "Dependency Graph Construction: Identifying independent sub-tasks (eligible for parallel execution) versus sequentially dependent sub-tasks where Step N requires Step N-1''s output.", "Coordinated Execution & Synthesis: Executing sub-queries via targeted tools/retrievers, storing partial answers in an execution scratchpad, and synthesizing the final answer using an aggregator prompt."], "supporting_evidence": ["Mentions dynamic replanning when intermediate sub-queries return unexpected or null results.", "Discusses Tree-of-Thoughts (ToT) or Graph-of-Thoughts (GoT) search algorithms over reasoning paths."], "negative_evidence": ["Feeds complex multi-hop queries directly to a single tool call without step-by-step breakdown or intermediate verification."], "partial_credit": ["Mentions breaking down the problem into smaller questions, but does not address dependency ordering, parallelization, or dynamic replanning."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you implement human-in-the-loop, and when is it triggered?', '{"required_evidence": ["Explains risk classification and triggers for human escalation.", "Explains graph interruption and suspension mechanisms."], "supporting_evidence": ["May discuss persisting execution state or human review interfaces."], "negative_evidence": ["Suggests blocking an active synchronous thread indefinitely."], "partial_credit": ["Mentions human approval but fails to describe suspension mechanisms."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How does a conversation manager handle intents such as cancel, wait or modify during a paused workflow?', '{"required_evidence": ["Explains how a paused workflow intercepts user commands.", "Explains specific state transitions for cancel, wait, and modify intents."], "supporting_evidence": ["May discuss asynchronous event-driven conversation managers."], "negative_evidence": ["Assumes the agent automatically understands intent without a structured transition loop."], "partial_credit": ["Explains one intent but misses the broader state management."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How does a companion agent decide whether to resolve something automatically or escalate to a human?', '{"required_evidence": ["Confidence & Ambiguity Scoring: Evaluating model output confidence (logprobs, self-evaluation check, or entropy) against predefined threshold minimums.", "Action Risk & Policy Matrix: Categorizing actions into risk tiers (Tier 1: read-only/FAQ -> auto; Tier 2: minor state change -> auto with confirmation; Tier 3: financial/auth/PII -> mandatory human escalation).", "User Sentiment & Sentiment Friction: Monitoring user frustration, sentiment degradation, repeated loop detections, or explicit triggers (''speak to an agent'')."], "supporting_evidence": ["Explains warm handoff protocols: packaging session summary, intent, sentiment, and attempted tools for the human operator.", "Discusses auditing false negatives (automated actions that should have escalated).", "May mention specific implementation examples such as: e.g. user rephrasing 3 times"], "negative_evidence": ["Relies solely on the agent ''feeling confident'' without explicit programmatic risk categorization or sentiment/loop breakers."], "partial_credit": ["Mentions sentiment and high-risk actions, but does not provide an architectural framework or confidence thresholds."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How did your system move from POC to production, and what challenges remain for production readiness?', '{"required_evidence": ["POC to Production Transition: Replacing naive prototype scripts with structured state graphs, implementing deterministic guardrails, hardening tool schemas with Pydantic validation, adding persistent session storage, and building automated CI/CD evaluation pipelines.", "Production Readiness Challenges: Non-deterministic latency/SLA management, hallucination & tool invocation failures, cost scaling at high QPS, secure credential/secret isolation during tool calls, and maintaining comprehensive observability (distributed tracing).", "Continuous Evaluation & Monitoring: Implementing golden dataset regression suites, real-time drift detection, and user feedback loops (thumbs up/down with trace correlation)."], "supporting_evidence": ["Discusses rate limiting, multi-region fallback for LLM provider outages, and sandbox execution for code/tool execution.", "Mentions production toolsets like LangSmith, Langfuse, or Datadog LLM Observability."], "negative_evidence": ["Believes moving to production simply means pointing the prototype script to an enterprise OpenAI API key."], "partial_credit": ["Lists general software production steps (unit tests, Docker) but glosses over LLM-specific operational challenges (evals, non-determinism, tracing)."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agent Architectures & Orchestration', 'MEDIUM', 'SPECIFIC', 180, 'Walk through a real-world scenario where multiple agents collaborate on a complex task and how responsibilities are divided.', '{"required_evidence": ["Concrete Scenario: Articulates a specific, realistic domain.", "Division of Responsibilities: Distinctly specifies roles, such as: Ingestion/Triage Agent (parses logs/documents), Research/Query Agent, Reasoning/Synthesis Agent (evaluates risk/root cause), and Action/Remediation Agent.", "Coordination & Handoff: Details the exact handoff mechanism, shared state representation, and validation gates between the agents from trigger to final resolution."], "supporting_evidence": ["Discusses human-in-the-loop checkpoint before final high-impact action execution.", "Addresses how errors or missing data at one step are escalated or retried.", "May mention specific implementation examples such as: e.g. Automated IT Incident Response, Mortgage Loan Underwriting, or Cross-Service Data Reconciliation, queries monitoring APIs or credit databases, generates PR, restarts pod, or drafts loan approval"], "negative_evidence": ["Presents a vague, generic scenario without distinct agent responsibilities, data contracts, or practical real-world tools."], "partial_credit": ["Describes a scenario with multiple agents, but the division of labor is muddy or all agents perform largely the same tasks."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'RAG & Information Retrieval', 'MEDIUM', 'SPECIFIC', 180, 'How do you ensure the context an agent retrieves is the right context? Would you add a validation agent on top of the other agents?', '{"required_evidence": ["Context Quality Assurance: Implementing hybrid search, reciprocal rank fusion, cross-encoder reranking, and metadata filtering to ensure high relevance.", "Validation Agent / Critic Node: Utilizing an evaluation step that scores retrieved documents for relevance, completeness, and factual grounding before passing to generation.", "Actionable Fallback: If context fails validation, trigger corrective actions: query expansion/rewriting, fallback web search, or clarifying with the user rather than proceeding with flawed context."], "supporting_evidence": ["Discusses evaluation metrics: Context Precision, Context Recall, and Faithfulness (using RAGAS or TruLens).", "Analyzes latency trade-offs of an additional validation LLM call versus deterministic rerankers.", "May mention specific implementation examples such as: dense semantic vectors + sparse BM25, RRF, e.g. Cohere Rerank"], "negative_evidence": ["Assumes top-k vector search cosine similarity alone guarantees 100% accurate, hallucination-free context."], "partial_credit": ["Mentions reranking or asking the LLM if context is good, but lacks an end-to-end corrective strategy (query rewriting, fallback)."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Tool Calling & Execution', 'MEDIUM', 'SPECIFIC', 180, 'How do agents acquire the ability to use tools, and how does tool-calling execution work (how the model generates and handles tool call requests)?', '{"required_evidence": ["Tool Acquisition: Tools are registered by providing the LLM with JSON Schema specifications (name, description, parameter names, types, descriptions, and required fields) injected into the system prompt or passed via native API parameters.", "Generation: The fine-tuned model identifies the need for a tool, halts standard text generation, and outputs a structured tool call payload with a special stop token.", "Handling & Execution: The client runtime intercepts the tool call, executes the corresponding Python/code function locally with the supplied arguments, and sends a new message with role tool containing the stringified result back to the model for final synthesis."], "supporting_evidence": ["Distinguishes model generation (which does NOT run code) from client-side execution (which actually executes the API/code).", "Mentions constrained decoding / grammar-guided generation ensuring valid JSON output.", "May mention specific implementation examples such as: e.g. OpenAI tools array, JSON containing name and arguments, e.g. finish_reason: ''tool_calls''"], "negative_evidence": ["Believes the LLM itself directly connects to databases, runs SQL, or makes HTTP requests internally over the internet."], "partial_credit": ["Explains that the LLM sends a JSON object with function arguments, but fails to clearly delineate the runtime''s responsibility to execute and return the output."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'SPECIFIC', 180, 'Coding exercise: build a single agent (LangChain or LangGraph) that queries a database through a tool, including imports, LLM definition, tool call, graph nodes and graph invocation.', '{"required_evidence": ["Includes necessary imports.", "Defines a typed State and a database query ''@tool'' with type annotations and docstring.", "Binds tools to the LLM (''llm.bind_tools([db_tool])'') and implements graph nodes: an agent node that calls the model and a tool execution node (''ToolNode'' or custom function).", "Constructs the graph with conditional edges (checking ''tool_calls''), compiles it, and invokes it with a user query."], "supporting_evidence": ["Demonstrates proper error handling or read-only database tool implementation.", "Uses ''tools_condition'' helper or explicit routing logic based on ''AIMessage.tool_calls''.", "May mention specific implementation examples such as: e.g., ''langgraph.graph'', ''StateGraph'', ''END'', ''ChatOpenAI'' or similar, ''tool'' decorator, ''Annotated'', ''add_messages'', e.g., ''messages: Annotated[list, add_messages]''"], "negative_evidence": ["Fails to define a tool or fails to wire the tool node back to the agent node in the graph, resulting in an unexecutable cycle.", "Omits state management entirely or uses invalid syntax that violates graph compilation."], "partial_credit": ["Writes a valid tool and LLM call, but writes a linear script rather than a working LangGraph/LangChain agent with graph nodes and invocation."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'HARD', 'SPECIFIC', 240, 'How do you design fault tolerance (checkpoints, retries, fallbacks) and handle agent dead ends?', '{"required_evidence": ["Checkpoints & State Recovery: Persists state snapshots at every graph step; on unrecoverable tool or node failure, rolls back state to the nearest valid checkpoint.", "Configurable Retries: Implements exponential backoff and jitter for transient API/network errors, combined with prompt-rephrasing retries for formatting/parsing errors.", "Dead-End Handling: Detects when an agent cannot find required tools or exhausts reasoning paths; triggers fallback nodes."], "supporting_evidence": ["Mentions compensating transactions (sagas) to undo partial side-effects executed before the failure occurred.", "Explains reflection loops where the agent is fed the tool error traceback to self-correct its query parameters.", "May mention specific implementation examples such as: e.g., simpler deterministic script, alternative model, or routing to human support"], "negative_evidence": ["Suggests infinite retries without backoff or step limits.", "Assumes dead ends can be solved by simply re-sending the exact same prompt repeatedly."], "partial_credit": ["Describes retry with exponential backoff and fallbacks, but does not address checkpoint rollback or handling dead-end reasoning states."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Evaluation & Testing', 'MEDIUM', 'SPECIFIC', 180, 'How do you evaluate tool-calling accuracy, including correctness and sequence of calls?', '{"required_evidence": ["Dataset Curation: Golden test suites containing user prompts paired with expected tool call trajectories (tool name, exact argument match / semantic equivalence, and call sequence).", "Metrics for Correctness: Tool Selection Accuracy/Precision/Recall (did it pick the right tool?), Argument Accuracy (exact match on enums/IDs, fuzzy/semantic evaluation on free-text args), and Final Output Faithfulness.", "Sequence & Trajectory Evaluation: Graph trajectory comparison (Levenshtein distance over tool sequences, DAG match) to verify correct ordering of sequential dependencies without redundant or dead-end calls."], "supporting_evidence": ["Mentions deterministic mock tool environments / synthetic sandbox replay to test trajectories without hitting production APIs.", "Discusses LLM-as-a-judge vs deterministic assertion testing for tool arguments."], "negative_evidence": ["Relying solely on final text output quality without verifying which tools were called, with what arguments, or in what order."], "partial_credit": ["Mentions testing if the tool returned the right result, but misses metrics for argument validation, tool choice precision, or sequence evaluation."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Enterprise Integration & RPA', 'MEDIUM', 'SPECIFIC', 180, 'How would you integrate an AI assistant into call center or ticketing workflows without disrupting legacy systems?', '{"required_evidence": ["Proposes non-invasive integration patterns: ''Agent-Assist'' sidecar or copilot UI that listens to customer conversations (speech-to-text) or ticket text and suggests responses/KB articles to human agents without altering core workflows.", "Leverages webhook listeners, message brokers, or database CDC (Change Data Capture) to ingest tickets asynchronously without modifying legacy backend code.", "Implements a phased rollout: passive shadow mode (logging suggestions and measuring accuracy) -> human-in-the-loop assisted mode -> autonomous auto-triage/tagging -> direct deflection for low-risk intents."], "supporting_evidence": ["Mentions RPA (Robotic Process Automation) or headless browser automation as a fallback adapter for legacy ticketing tools that lack REST/GraphQL APIs.", "Discusses real-time streaming STT (e.g., Deepgram, Whisper streaming) and latency budgets (<500ms for agent suggestions).", "May mention specific implementation examples such as: e.g., Kafka, SQS"], "negative_evidence": ["Proposes immediately replacing existing telephony/ticketing systems with a completely autonomous AI bot without fallback mechanisms or human supervision.", "Assumes legacy enterprise systems can easily expose modern real-time WebSockets or support massive schema rewrites."], "partial_credit": ["Suggests building an AI chatbot for tickets but doesn''t address the legacy integration mechanism (APIs vs webhooks vs RPA) or the phased human-in-the-loop transition."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Model Context Protocol (MCP)', 'MEDIUM', 'SPECIFIC', 180, 'How does MCP differ from direct tool calling or direct API integration? Why choose MCP over a plain Python function or tools defined in the same graph?', '{"required_evidence": ["Distinguishes MCP from an in-process tool integration by explaining that MCP introduces a standardized client/server boundary.", "Explains at least one practical benefit of that boundary, such as interoperability, deployment isolation, or reuse.", "Identifies at least one trade-off, such as serialization, network/RPC overhead, or operational complexity."], "supporting_evidence": ["Acknowledges trade-offs: Direct functions have lower latency, zero serialization overhead, and simpler single-repo debugging; MCP introduces RPC latency, serialization overhead, and process management.", "Mentions security sandboxing: running untrusted third-party tools in isolated MCP processes.", "May mention specific implementation examples such as: e.g., Python function in LangChain/LangGraph memory space, Claude Desktop, Cursor, LangGraph, custom agent"], "negative_evidence": ["Claims MCP has faster execution latency than an in-memory direct Python function call."], "partial_credit": ["Explains that MCP runs separately and can be reused, but does not articulate language decoupling, process isolation, or RPC overhead trade-offs."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Model Context Protocol (MCP)', 'MEDIUM', 'SPECIFIC', 180, 'How would you implement an MCP server and client, and what is the end-to-end flow from user query to database response?', '{"required_evidence": ["Server Implementation: Use MCP SDK (Python or TypeScript) to instantiate a Server instance, register database query tools with schemas ), define transport (stdio or SSE), and implement the database execution handler.", "Client Implementation: Instantiate an MCP Client, establish transport connection to server, call list_tools() during initialization to discover schemas, and format them into LLM tool definitions.", "End-to-End Flow: User asks query -> Client feeds query and discovered tools to LLM -> LLM returns tool_call for database query -> Client extracts call and sends tools/call request to MCP server -> MCP server executes query on DB and returns JSON-RPC result to Client -> Client passes result back to LLM -> LLM synthesizes natural language response for User."], "supporting_evidence": ["Highlights connection initialization: initialize handshake, version negotiation, and capability exchange.", "Discusses security considerations such as connection pooling, query timeouts, and read-only database credentials in the MCP server.", "May mention specific implementation examples such as: e.g. @mcp.tool"], "negative_evidence": ["Has the LLM communicating directly to the MCP server without the client acting as the orchestrating intermediary."], "partial_credit": ["Walks through the flow from user to LLM to tool, but skips the technical details of MCP SDK client-server setup or JSON-RPC handshake."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Model Context Protocol (MCP)', 'MEDIUM', 'SPECIFIC', 180, 'How can the MCP client be implemented as a node in LangGraph?', '{"required_evidence": ["Initialization / Setup: In the graph initialization or lifecycle hook, connect the MCP client to the MCP server, retrieve active tool definitions via list_tools(), and bind them to the LLM node.", "Node Implementation: Create a tool execution node that inspects the latest message in state for tool_calls; for each call matching an MCP tool, delegates execution asynchronously to mcp_client.call_tool(name, args).", "State Integration: Wrap the MCP server''s response in a LangChain ToolMessage (with corresponding tool_call_id) and return a state update dictionary updating messages, routing conditionally back to the agent node."], "supporting_evidence": ["Discusses async session management: maintaining persistent client sessions across graph invocations or managing connection lifecycles within LangGraph checkpointers.", "Mentions using LangChain''s built-in MCP adapters or community toolkits."], "negative_evidence": ["Re-instantiates and reconnects the MCP client process inside the node on every single token generation turn."], "partial_credit": ["Explains calling call_tool inside a LangGraph node, but neglects how schemas are bound to the LLM or how results are packaged as ToolMessages."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'What are the security and observability risks of exposing internal systems or PII through MCP, and how do you mitigate them (auth, access control, masking)?', '{"required_evidence": ["Identifies critical risks including prompt injection leading to unauthorized tool invocation, data exfiltration of internal secrets/PII, and excessive privileges granted to LLM clients.", "Explains authentication and authorization strategies such as mTLS, bearer tokens/OAuth2 between client and server, and enforcing strict Role-Based Access Control (RBAC) at the tool execution boundary.", "Describes data masking and redaction techniques applied before tool outputs enter the model context and audit logging/tracing of all JSON-RPC tool calls."], "supporting_evidence": ["Mentions implementing human-in-the-loop (HITL) approval gates for write or destructive actions triggered through MCP tools.", "Discusses distributed tracing (e.g., OpenTelemetry span propagation across MCP transports) to monitor latency, error rates, and sensitive payload handling.", "May mention specific implementation examples such as: e.g., Presidio, regex/NER pipelines"], "negative_evidence": ["Claims that LLM system prompts alone are sufficient to enforce access control and prevent PII exposure.", "Assumes MCP servers are inherently isolated and do not require external authentication or transport-layer encryption."], "partial_credit": ["Mentions using API keys and regex redaction but fails to address authorization boundaries or prompt injection and exfiltration vectors."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'HARD', 'SPECIFIC', 240, 'Compare system design with and without MCP in terms of scalability, interoperability and integration effort.', '{"required_evidence": ["Scalability: Compares monolithic tightly-coupled tool integrations with MCP''s distributed microservice model where MCP servers scale independently behind load balancers.", "Interoperability: Explains that MCP provides an open standard allowing any client (Claude, IDE, custom agent) to connect to any tool server without rewriting bespoke SDK integrations (eliminating M\\u00d7N adapter complexity to M+N).", "Integration effort: Acknowledges higher upfront setup for MCP servers and protocol compliance, but significantly lower marginal integration cost for adding new tools or clients."], "supporting_evidence": ["Notes that without MCP, custom bespoke tool wrappers require maintaining disparate schemas, authentication, and execution loops across different agent frameworks.", "Discusses transport trade-offs (stdio for low-latency local tooling vs SSE/HTTP for distributed enterprise scale).", "May mention specific implementation examples such as: JSON-RPC"], "negative_evidence": ["Asserts that MCP improves runtime raw execution speed compared to direct in-memory Python function calls.", "Claims MCP removes the need for input validation or schema definition entirely."], "partial_credit": ["States that MCP makes integrations more standardized like an API standard, but cannot compare scalability or architectural trade-offs."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 240, 'How would you design an ingestion agent for multiple document formats that writes to a database without manual SQL?', '{"required_evidence": ["Details document parsing and normalization pipelines for diverse formats (PDF, DOCX, CSV, scanned images) using specialized extractors.", "Explains using structured output generation to extract standardized domain entities from unstructured content.", "Describes database abstraction layers that eliminate manual raw SQL generation while enforcing type safety."], "supporting_evidence": ["Discusses validation and sanitization steps (data validation against database constraints, foreign key checks, idempotency keys).", "Covers asynchronous batch processing with message queues (e.g., Celery, SQS) to handle large document ingestion volumes.", "May mention specific implementation examples such as: e.g., Unstructured, PyMuPDF, OCR/vision models, Pydantic models, JSON schema constraints, or function calling, e.g., ORM models like SQLAlchemy/Prisma, automated upsert APIs, or schema-mapped CRUD tools"], "negative_evidence": ["Suggests having an LLM write raw INSERT SQL statements directly to the database without schema validation, ORM abstraction, or sanitization.", "Assumes standard text splitters can parse complex layouts like multi-column tables, scanned receipts, and PDFs without dedicated layout-aware parsers."], "partial_credit": ["Mentions parsing files with Python libraries and using an LLM to produce JSON for an ORM, but lacks ingestion architecture, error validation, or multi-format handling details."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'Who should own MCP servers (the agent team or platform teams), and how many tools should one server expose?', '{"required_evidence": ["Ownership: Recommends domain/platform teams own the MCP servers for their respective underlying services, while agent teams consume them via standard contracts and client configuration.", "Tool granularity: Advocates for domain-specific, bounded-context MCP servers exposing 5-15 cohesive tools rather than a massive monolithic server, preventing context window bloat and tool selection confusion."], "supporting_evidence": ["Explains that overwhelming an LLM with dozens/hundreds of tool definitions degrades tool-calling accuracy and inflates token cost.", "Discusses dynamic tool retrieval or registry patterns when an organization has hundreds of available enterprise tools.", "May mention specific implementation examples such as: API ownership principle"], "negative_evidence": ["Advocates putting hundreds of unrelated enterprise tools into a single global MCP server and dumping all schemas into the LLM prompt.", "Claims agent developers should directly manage and deploy the backend infrastructure of existing enterprise services."], "partial_credit": ["Suggests platform teams should own backend services and tool servers should be small, without explaining tool retrieval limits or cognitive load on LLMs."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic Workflows & LangGraph', 'MEDIUM', 'SPECIFIC', 180, 'Explain state management (in LangGraph): how do multiple nodes update shared state, and how do append and overwrite differ?', '{"required_evidence": ["Explains LangGraph''s shared state schema: state is defined using a typed structure that is passed to every node as an argument, and nodes return dictionaries representing state updates.", "Explains state reducer functions: how updates are applied depends on annotated reducer functions defined on the state keys.", "Contrasts append vs overwrite: overwrite (default behavior) completely replaces the existing key''s value with the node''s returned value, whereas append (using reducers like `operator.add` or message reducers) appends new items/messages to an existing list without wiping prior history."], "supporting_evidence": ["Discusses concurrent/parallel branch execution: how reducer functions resolve state updates from multiple parallel nodes executing concurrently without race condition data loss.", "Mentions built-in message state helpers like `add_messages` which handles deduplication and ID-based updates.", "May mention specific implementation examples such as: e.g., TypedDict, Pydantic model, e.g., `Annotated[list, add]` vs default assignment"], "negative_evidence": ["Claims nodes directly mutate a global variable in-place rather than returning partial dictionary updates processed by reducers.", "States that append is the default behavior for all keys in LangGraph."], "partial_credit": ["Explains that overwrite replaces the value and append adds to a list, but fails to explain typed schemas, reducer annotations, or how nodes return updates."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'EASY', 'SPECIFIC', 180, 'What are the LangChain message types (System, Human, AI, Tool), and how are they used in agent interactions?', '{"required_evidence": ["Identifies and explains each message type: SystemMessage (sets agent persona, instructions, constraints, and tool usage rules), HumanMessage (user input/prompts), AIMessage (model responses, which may include tool call requests ''tool_calls''), and ToolMessage (contains the output/result of a tool execution linked by ''tool_call_id'').", "Explains the agent loop sequence: System + Human -> AI (generates tool call) -> Tool (executes and returns ToolMessage) -> AI (generates final response or next action)."], "supporting_evidence": ["Mentions ''tool_call_id'' matching between AIMessage and ToolMessage to satisfy API requirements for OpenAI and Anthropic.", "Mentions ChatPromptTemplate and message placeholders (''MessagesPlaceholder'') for dynamic message injection."], "negative_evidence": ["Claims ToolMessage is sent by the user to ask the LLM to use a tool.", "Believes AIMessage only contains final plain text and cannot represent tool calling requests."], "partial_credit": ["Correctly identifies System, Human, and AI messages, but is vague or incorrect regarding how ToolMessage functions in the interaction loop."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'SPECIFIC', 180, 'Why choose LangGraph over CrewAI, Google ADK or other frameworks? Compare memory handling between LangGraph and ADK.', '{"required_evidence": ["Compares framework philosophies: CrewAI uses high-level role-playing agent abstractions with opinionated autonomous collaboration; LangGraph provides low-level, deterministic, graph-based control with explicit state machines, making it better for complex enterprise production logic.", "Compares memory handling: LangGraph utilizes explicit schema-driven state with persistent checkpointing and fine-grained reducers, enabling human-in-the-loop time travel; ADK / agent kits often rely on session-based contextual stores or managed platform memory with less developer control over state transitions.", "Highlights trade-offs: LangGraph has a steeper learning curve but offers complete determinism and control, whereas CrewAI allows faster prototyping of collaborative teams at the expense of predictable control flow."], "supporting_evidence": ["Mentions thread-level isolation and fault recovery across server restarts in LangGraph checkpointers.", "Discusses multi-agent coordination patterns (LangGraph''s hierarchical supervisor vs CrewAI''s sequential/hierarchical processes).", "May mention specific implementation examples such as: pluggable SQLite/Postgres/Redis"], "negative_evidence": ["Claims CrewAI is strictly superior for enterprise production because it requires less code, ignoring control and reliability needs.", "Asserts that LangGraph does not support multi-agent workflows."], "partial_credit": ["Provides a high-level comparison of LangGraph and CrewAI but fails to analyze memory handling or compare with ADK."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 180, 'When would you use Pydantic in agent architectures or data pipelines?', '{"required_evidence": ["Structured LLM Outputs: Enforcing JSON schema constraints on LLM responses via tool/function calling or output parsers '').", "Data Pipeline Validation: Validating incoming raw data, API payloads, and inter-service messages with runtime type checking, schema coercion, and custom field validators.", "Agent State Definition: Structuring agent state schemas and configuration objects."], "supporting_evidence": ["Mentions Pydantic V2''s performance improvements written in Rust (''pydantic-core'').", "Explains generating JSON schemas dynamically via ''model.model_json_schema()'' to feed into MCP or OpenAI function definitions.", "May mention specific implementation examples such as: e.g., ''model.with_structured_output(PydanticModel, e.g., ''BaseModel'' or ''BaseSettings'' for environment variables and secrets"], "negative_evidence": ["Believes Pydantic performs validation only at compile time like static typing (MyPy).", "Claims Pydantic is an ORM for database migrations."], "partial_credit": ["Mentions using Pydantic for data validation and API request models, but does not detail structured LLM output generation or agent state."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'HARD', 'SPECIFIC', 240, 'How do you orchestrate multiple LLM providers (OpenAI, Anthropic, Bedrock) in one system?', '{"required_evidence": ["Designs a unified gateway/abstraction layer standardizing API schemas, request/response formats, and tool definitions across providers.", "Implements intelligent model routing based on task complexity, token cost, latency SLA, and context window requirements.", "Implements robust resilience patterns: automated fallbacks/circuit breakers on rate limits (HTTP 429) or provider outages, retry with exponential backoff, and load balancing across keys/regions."], "supporting_evidence": ["Discusses centralized telemetry, cost tracking, token budgeting, and unified logging (e.g., OpenLIT, Portkey).", "Mentions handling provider-specific differences in tool calling formats and JSON schema strictness.", "May mention specific implementation examples such as: e.g., LiteLLM, custom adapter pattern, e.g., small fast models for routing, frontier models for complex reasoning"], "negative_evidence": ["Suggests hardcoding multiple disparate SDK calls directly inside agent business logic without an abstraction layer.", "Assumes all providers have identical prompt sensitivities and tool call specifications without needing normalization."], "partial_credit": ["Mentions using LiteLLM or an API wrapper to switch models when one fails, but omits dynamic routing, cost optimization, or schema normalization."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'How do you structure prompts for clarity, domain specificity and consistent output format? What roles do system and user prompts play?', '{"required_evidence": ["Structures prompts modularly: explicit persona/role definition, clear task instructions, domain context/terminology, negative constraints/guardrails, few-shot exemplars, and unambiguous output format specifications.", "Delineates System Prompt vs User Prompt: System prompt sets persistent behavioral rules, safety boundaries, persona, and tool definitions across an entire session; User prompt supplies dynamic task input, user-specific data, and query parameters.", "Ensures output consistency: enforcing structured outputs, using explicit delimiters (<context>, <input>), and specifying negative constraints (''Do not include conversational preambles or markdown code fences'')."], "supporting_evidence": ["Discusses LLM attention steerability: placing critical constraints at both the beginning and end of the prompt to mitigate recency and primacy degradation.", "Mentions grammar-based sampling (e.g., Outlines, GBNF) as deterministic guarantees for output schemas.", "May mention specific implementation examples such as: e.g. JSON schema, XML tags, JSON Mode, Pydantic schemas"], "negative_evidence": ["Assumes system prompts and user prompts behave identically with no architectural or steerability differences in instruction-tuned APIs.", "Relies solely on informal conversational phrasing without explicit delimiter structure or schema definitions."], "partial_credit": ["Explains the difference between system and user prompts, but provides generic advice on clarity without detailing modular structuring or formatting techniques."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 180, 'How do coding agents decide which files to include in the context window?', '{"required_evidence": ["Explains multi-stage context selection: starting from active editor file/cursor position, git status (staged/modified files), and user mentions.", "Describes semantic and structural search: using Abstract Syntax Trees (AST) to extract imports, function signatures, and call hierarchies.", "Explains dense retrieval: vector embeddings over codebase chunks combined with lexical search and reranking to fit within token budgets."], "supporting_evidence": ["Mentions repository map generation (e.g., Aider''s graph-based repo map ranking files by PageRank over dependencies).", "Discusses token budgeting strategies: including summaries or interfaces for secondary files while reserving full contents for target files.", "May mention specific implementation examples such as: e.g., ''@filename'', e.g., ctags, LSP symbols, BM25 / ripgrep"], "negative_evidence": ["Claims coding agents dump the entire codebase into the prompt for every query.", "Assumes file selection is purely random or based only on file names."], "partial_credit": ["Mentions embeddings and grep search over files, but omits LSP/AST symbol resolution, git diffs, or repo mapping."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'EASY', 'SPECIFIC', 180, 'How do you use coding-agent tools (Cursor, Claude Code, Copilot) in your workflow, and how much code do you let agents write?', '{"required_evidence": ["Articulates workflow usage: using agents for boilerplate, unit tests, refactoring, documentation, and exploratory prototyping, while humans retain architectural design and system boundaries.", "Defines governance and autonomy limits: establishing strict verification practices (code review, static analysis, running test suites) and restricting agents from autonomously committing to production or modifying security-critical code.", "Discusses iterative prompt refinement: providing explicit context, files, and architectural guidelines rather than open-ended monolithic instructions."], "supporting_evidence": ["Mentions using ''.cursor/rules'' or system prompt guidelines to enforce team coding standards and conventions.", "Discusses the trade-off of verification cost: large AI-generated diffs can increase review fatigue and introduce subtle hallucinations."], "negative_evidence": ["Advocates blindly merging large agent-generated codebases directly into production without review or automated testing.", "Claims AI coding agents are completely useless or writes 100% of production code autonomously without oversight."], "partial_credit": ["Describes using Copilot for autocomplete and tests, but does not discuss code governance, verification, or autonomy limits."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 180, 'How are key entities (e.g. claim numbers) captured and reused in agent memory?', '{"required_evidence": ["Entity Extraction: Uses structured outputs or NER tools during the initial interaction to accurately identify and parse target entities.", "State / Memory Storage: Persists extracted entities into a dedicated structured state dictionary or session metadata store rather than leaving them buried in unstructured conversation text.", "Context Reuse: Injects the extracted entities deterministically into downstream system prompts, tool call parameters, or SQL queries across multi-turn interactions."], "supporting_evidence": ["Discusses entity reconciliation: handling corrections when a user updates or clarifies a previously stated entity.", "Mentions using Knowledge Graphs or key-value entity tables for cross-session entity persistence.", "May mention specific implementation examples such as: Pydantic schemas, e.g., regex/schema validation for claim numbers, e.g., Redis, graph state"], "negative_evidence": ["Relies entirely on the LLM to remember numbers in raw text over long conversations without structured state persistence.", "Claims entities cannot be tracked across turns in stateless agent systems."], "partial_credit": ["Mentions extracting entities with prompts and saving them to a variable, but fails to discuss structured schemas, state injection, or multi-turn persistence."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 180, 'How did prompt caching fix performance bottlenecks, and how do you implement LLM caching (what to store)?', '{"required_evidence": ["Explains that provider prompt caching (KV cache reuse) avoids recomputing attention over repetitive input tokens, significantly reducing Time-To-First-Token (TTFT) and input token costs.", "Explains the architectural requirements for provider cache hits: deterministic prefix matching, placing invariant content (system prompts, tool definitions, static context) at the start of the prompt.", "Describes exact match caching vs semantic caching: storing query hashes vs vector embeddings in Redis/Key-Value stores mapped to generated responses."], "supporting_evidence": ["Discusses cache invalidation strategies (TTL, cache warming, handling dynamic state injections like current timestamps).", "Explains the trade-offs of semantic caching (risk of false positive semantic matches returning stale or inaccurate responses for slight nuances)."], "negative_evidence": ["Assumes prompt caching caches the LLM''s generated output rather than intermediate KV cache representations on the input tokens.", "Inserts dynamic data (like current timestamp or random UUIDs) at the very top of the system prompt, breaking prefix caching."], "partial_credit": ["Explains basic Redis output caching for identical queries, but does not explain provider-level KV prompt caching or prefix ordering."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 180, 'How do you manage conversation history and short- and long-term memory? How do you incorporate history into LLM calls, and why might a system skip memory in favor of prompt caching?', '{"required_evidence": ["Short- vs long-term memory architecture: Short-term memory tracks immediate session turns maintained in an ephemeral sliding window buffer or Redis cache; Long-term memory persists user facts, preferences, and historical entities across sessions stored in vector databases or knowledge graphs and retrieved via semantic search.", "Incorporating history into LLM calls: formats previous turns as structured role-based messages (user, assistant), dynamically pruning or summarizing older messages when approaching token thresholds.", "Skipping dynamic memory for Prompt Caching: prompt caching requires identical token prefixes to achieve up to 90% cost savings and 80% latency reductions; dynamically prepending variable conversational history or personalized user memory into the prompt header breaks prefix cache hits, making it advantageous to isolate static prompts or use deterministic caching structures."], "supporting_evidence": ["Explains structuring prompts with static system instructions and documentation at the top (cacheable prefix) and appending dynamic session history at the very end.", "Discusses memory extraction agents that asynchronously extract profile facts from chat history into a relational/vector user profile.", "May mention specific implementation examples such as: e.g. conversational summary buffer, e.g. Anthropic / OpenAI prefix caching"], "negative_evidence": ["Confuses LLM weight fine-tuning with conversational context memory.", "Believes prompt caching functions effectively even when arbitrary tokens are inserted at the beginning of the prompt."], "partial_credit": ["Explains sliding window context and saving conversations in a database, but does not understand prompt caching mechanics or why prefix consistency matters."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 180, 'How do you keep large contexts relevant and prevent quality degradation? How do you reduce irrelevant context before it reaches the LLM?', '{"required_evidence": ["Explains context compression and filtering techniques such as cross-encoder reranking to score and filter retrieved chunks before prompt assembly.", "Discusses LLM ''lost in the middle'' phenomena and architectural mitigations.", "Describes contextual chunking, extractive summarization, or semantic similarity thresholding to prune noise and redundant tokens."], "supporting_evidence": ["Mentions token pruning libraries (e.g., LLMLingua) or selective context pruning via attention mask inspection.", "Mentions hybrid search (BM25 + dense vectors) combined with reciprocal rank fusion (RRF) to ensure high-precision candidate retrieval before filtering.", "May mention specific implementation examples such as: e.g., Cohere, BGE, e.g., placing critical instructions and key context at the very beginning or end of the prompt"], "negative_evidence": ["Believes simply passing a 1M token context window directly to the LLM avoids quality degradation without any filtering.", "Assumes vector similarity scores alone (without reranking or thresholding) guarantee context relevance."], "partial_credit": ["Mentions basic vector search top-k filtering or basic summarization without mentioning reranking, lost-in-the-middle degradation, or prompt structuring."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you prevent and detect infinite loops or uncontrolled iterations?', '{"required_evidence": ["Hard Limits: Enforces strict maximum recursion depth (''max_iterations'' / ''recursion_limit''), total execution timeouts, and cumulative token/cost budgets per request.", "Loop Detection Heuristics: Monitors agent action history to detect repetitive tool calls with identical arguments, cyclic state transitions, or semantic repetition in thoughts/outputs.", "Graceful Escalation: When a potential loop is detected, terminates the loop, routes to an emergency fallback node, prompts the user for clarification, or escalates to a human operator."], "supporting_evidence": ["Mentions calculating semantic similarity between consecutive reasoning steps using embeddings to catch non-verbatim loops.", "Discusses circuit breaker patterns applied to external tool executions."], "negative_evidence": ["Assumes LLMs will naturally detect their own infinite loops and terminate without programmatic constraints.", "Relies solely on waiting for the user to manually cancel the request."], "partial_credit": ["Mentions setting a maximum iteration count (e.g., 10 loops) but does not discuss argument-matching heuristics, token budgets, or fallback escalation."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you control agent autonomy and prevent unsafe or undesired outputs?', '{"required_evidence": ["Least-Privilege Tool Scoping: Restricts tool capabilities to read-only actions by default; enforces strict input validation and parameter whitelisting using Pydantic schemas.", "Human-in-the-Loop (HITL) Gates: Requires explicit human review and authorization for high-stakes, irreversible, or destructive operations.", "Input and Output Guardrails: Implements deterministic and semantic guardrails to intercept prompt injections on input and filter toxic, hallucinated, or out-of-policy text on output."], "supporting_evidence": ["Discusses execution sandboxing (e.g., Docker, gVisor, WebAssembly) for dynamic code execution tools.", "Mentions dual-model Maker-Checker (critic) architecture to cross-validate reasoning plans before execution.", "May mention specific implementation examples such as: e.g., financial transactions, database writes, external emails, e.g., NeMo Guardrails, Llama Guard, Guardrails AI"], "negative_evidence": ["Relies exclusively on system prompt instructions like ''Do not do anything bad'' to ensure safety.", "Grants agents unrestricted shell execution or write access to production databases."], "partial_credit": ["Mentions guardrails and asking users for confirmation before running tools, but lacks technical depth on least-privilege scoping, input validation, or sandboxing."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you diagnose silent failures where output quality degrades without errors?', '{"required_evidence": ["Observability & Trajectory Tracing: Inspects full agent execution traces to identify where intermediate context was diluted, hallucinated, or dropped.", "Continuous Evaluation & LLM-as-a-Judge: Runs automated semantic evaluation metrics on production samples.", "Telemetry & Statistical Drift: Monitors statistical signals such as output token length anomalies, cosine similarity shifts against historical embeddings, tool selection distribution shifts, and drops in user acceptance rates."], "supporting_evidence": ["Conducts regular evaluations against a versioned Golden Dataset to catch regressions across prompt or model updates.", "Mentions shadow deployments where a new pipeline runs in parallel with production traffic to compare output distributions.", "May mention specific implementation examples such as: e.g., via LangSmith, Phoenix, e.g., Ragas faithfulness, answer relevance, hallucination detection"], "negative_evidence": ["Claims silent failures can only be detected when users manually submit bug reports.", "Assumes that as long as HTTP status is 200 OK, the model output is correct and optimal."], "partial_credit": ["Mentions using LLM-as-a-judge and checking logs, but misses trace inspection, semantic drift metrics, and user feedback correlation."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you A/B test prompt templates, and monitor and iterate on prompt performance in production?', '{"required_evidence": ["Implements traffic splitting and routing: using feature flags or API gateways to deterministically split user traffic between Prompt Template A and B based on user ID / session hashing.", "Tracks quantitative and business metrics: offline evaluation scores (LLM-as-a-judge, task accuracy, schema validation error rates) combined with online production metrics (user acceptance rate, thumbs up/down, latency, token cost, session completion rate).", "Production observability and tracing: logging prompt inputs, full completions, metadata, and token usage into observability platforms to detect prompt drift, regression, or edge-case failures."], "supporting_evidence": ["Explains statistical significance testing (sample size calculation, p-values) before rolling out winning prompt templates.", "Discusses canary deployments and automated rollback triggers if error rates or latency spike.", "May mention specific implementation examples such as: e.g., LaunchDarkly, Statsig, custom proxy, e.g., LangSmith, Arize Phoenix, OpenTelemetry"], "negative_evidence": ["Advocates deploying prompt changes directly to all production users without canary testing, feature flags, or baseline tracking.", "Relies solely on subjective developer impressions rather than quantitative metrics or telemetry."], "partial_credit": ["Describes splitting traffic and checking if users like the responses, but lacks specifics on metrics, observability platforms, or statistical rigor."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 240, 'How do you design feedback loops, success conditions, escalation mechanisms, tool restrictions and memory limits?', '{"required_evidence": ["Feedback Loops & Success Conditions: Establishes programmatic validators that verify whether outputs meet explicit acceptance criteria before concluding execution.", "Escalation Mechanisms & Restrictions: Restricts tools via least-privilege scopes and rate limits; automatically triggers human escalation when confidence drops below threshold or max retries are exceeded.", "Memory Limits: Enforces sliding context windows, token thresholds, and automated summarization to bound memory growth and prevent context window exhaustion."], "supporting_evidence": ["Mentions capturing implicit user feedback (e.g., copy-paste, edits) to continuously update evaluation benchmarks.", "Discusses dead-letter queues (DLQs) for failed agent jobs requiring human intervention.", "May mention specific implementation examples such as: e.g., schema checkers, unit tests, critic agents"], "negative_evidence": ["Believes success conditions should be determined by asking the agent ''Did you succeed?'' in the same prompt.", "Leaves tool usage unrestricted with infinite memory buffers."], "partial_credit": ["Mentions setting memory limits and escalating to humans when errors occur, but lacks systematic architectural design across all five components."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you ensure an LLM uses only internal enterprise data and not pre-trained knowledge?', '{"required_evidence": ["Describes strict system prompt constraints instructing the model to rely solely on the provided context and explicitly reply with an out-of-domain/insufficient context refusal when data is absent.", "Explains grounding verification mechanisms.", "Details architectural separation: using zero temperature / low temperature and setting up secondary critic/evaluator models or guardrail filters to reject ungrounded responses."], "supporting_evidence": ["Mentions fine-tuning models on domain-specific refusal datasets (teaching the model to answer ''I do not know based on the provided documents'').", "Discusses constraining output formats to structured citations with sentence-level context matching.", "May mention specific implementation examples such as: e.g., RAG triad faithfulness checks, citation enforcement where claims must reference context spans, e.g., NeMo Guardrails, DeepEval faithfulness"], "negative_evidence": ["Assumes setting temperature = 0 guarantees the model will never use its pre-trained parametric weights.", "Believes vector retrieval alone prevents parametric knowledge leakage without prompt constraints and verification."], "partial_credit": ["Suggests writing ''answer only from the provided text'' in the prompt, but does not describe evaluation metrics, guardrail pipelines, or citation validation."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'Which query types are unsuitable for automation, and how do you escalate to humans?', '{"required_evidence": ["Unsuitable Queries: High-risk financial/legal/medical decisions, emotionally charged or hostile interactions, queries with severe ambiguity, and operations requiring irreversible authority or physical verification.", "Detection Mechanisms: Implements intent classification, keyword/sentiment triggers, and confidence score thresholds to identify escalation criteria early.", "Technical Handoff: Seamlessly transfers full conversational context, summarized intent, and historical agent actions into human agent software without forcing the user to repeat themselves."], "supporting_evidence": ["Discusses human-in-the-loop copilot mode: drafting automated suggestions for the human agent to review and approve.", "Maintains SLA tracking on escalation queues to prevent customer churn.", "May mention specific implementation examples such as: e.g., Zendesk, Salesforce"], "negative_evidence": ["Advocates automating 100% of customer interactions including emergency or legal threats without human oversight.", "Implements escalation by abruptly dropping the chat session and telling the user to call a phone number without context transfer."], "partial_credit": ["Identifies medical or financial queries as unsuitable and suggests sending an email to support, but lacks automated detection or context handoff architectures."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How do you balance scalability and maintainability with many dependencies?', '{"required_evidence": ["Decoupled Architecture: Implements domain-driven microservices or modular tool servers behind standard API contracts, preventing dependency tangles.", "Dependency Management & Isolation: Isolates third-party libraries and tool executors inside containerized environments, using pinned dependencies and lockfiles.", "Resilience & Circuit Breaking: Implements asynchronous messaging (queues/brokers), rate limiters, and circuit breakers so that failure or latency in one third-party dependency does not cascade to the whole system."], "supporting_evidence": ["Mentions automated dependency scanning (e.g., Dependabot, Snyk) for security vulnerabilities.", "Discusses API versioning and backward compatibility strategies across agent tool contracts.", "May mention specific implementation examples such as: e.g., MCP, Docker/Kubernetes"], "negative_evidence": ["Packages dozens of incompatible third-party libraries into a single monolithic script without virtual environments or container boundaries.", "Assumes dependencies will never experience breaking updates, rate limits, or downtime."], "partial_credit": ["Mentions using Docker and microservices to organize code, but lacks depth on cascading failures, circuit breaking, or API contracts."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'Which metrics and tools do you use for evaluating AI applications (recall@K, precision@K, judge, human evaluation)?', '{"required_evidence": ["Differentiates retrieval metrics from generation metrics: retrieval uses Recall@K, Precision@K, and MRR/NDCG to measure chunk retrieval quality; generation uses Faithfulness, Answer Relevance, and ROUGE/BERTScore.", "Explains LLM-as-a-judge for automated semantic scoring against rubrics and human evaluation for high-stakes qualitative validation and calibration.", "Identifies relevant evaluation tooling and frameworks."], "supporting_evidence": ["Discusses the RAG Triad: Context Relevance, Groundedness/Faithfulness, and Answer Relevance.", "Details calculating correlation between automated judge scores and human expert scores to validate the evaluation pipeline.", "May mention specific implementation examples such as: e.g., Ragas, DeepEval, TruLens, LangSmith, Phoenix Arize"], "negative_evidence": ["Conflates retrieval metrics with generation metrics (e.g., claiming Recall@K measures whether the LLM generated a polite response)."], "partial_credit": ["Mentions Recall@K and LLM-as-a-judge, but does not clearly separate retrieval vs. generation evaluation or name concrete tooling."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'MLOps & Cloud AI Architecture', 'MEDIUM', 'SPECIFIC', 180, 'How do you combine AWS services with ML frameworks to build scalable AI solutions?', '{"required_evidence": ["Pipeline orchestration: coordinates end-to-end stages (data prep, distributed training, evaluation, deployment) using SageMaker Pipelines or AWS Step Functions, integrated with ML frameworks (PyTorch, TensorFlow, Hugging Face).", "Data ingestion & storage: aggregates high-throughput training/inference data via S3 (data lake) and Amazon FSx for Lustre for fast POSIX GPU data loading; tracks metadata and features using SageMaker Feature Store.", "Distributed training and compute: leverages SageMaker Training Jobs / SageMaker HyperPod with multi-GPU instances, using framework tools (PyTorch FSDP, DeepSpeed) with AWS EFA (Elastic Fabric Adapter) for high-bandwidth inter-node communication.", "Deployment, serving, and monitoring: packages models into Triton or vLLM container images hosted on SageMaker Real-Time/Async Endpoints, monitored by SageMaker Model Monitor (data drift, concept drift) and CloudWatch."], "supporting_evidence": ["Mentions Spot Instances with checkpointing to S3 for 70%+ cost savings during heavy training runs.", "Explains integration with Bedrock for foundational models combined with custom fine-tuned adapters running on SageMaker.", "May mention specific implementation examples such as: e.g., p4d/p5 instances"], "negative_evidence": ["Suggests manually SSHing into standalone EC2 instances and running ad-hoc Python scripts as a scalable enterprise AI architecture.", "Ignores GPU networking bottlenecks (EFA) or distributed checkpointing requirements for large model training."], "partial_credit": ["Names SageMaker and PyTorch and mentions deploying to an endpoint, but lacks depth on data pipelines, distributed training networking, or monitoring."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'What golden dataset do you use for evaluation, and is it shared across agents or agent-specific?', '{"required_evidence": ["Golden Dataset Composition: Curated, version-controlled repository of representative production queries, complex edge cases, adversarial inputs, and verified ground-truth trajectories (expected tool calls and expected outputs).", "Tiered Architecture (Shared vs Agent-Specific): Maintains a shared end-to-end system dataset to evaluate holistic performance and regression across all agents, alongside agent-specific datasets tailored to evaluate individual node capabilities.", "Continuous Dataset Curation: Continuously enriches the dataset by curating sanitized production edge cases, user-flagged errors, and expert-annotated samples."], "supporting_evidence": ["Stores datasets in formats compatible with evaluation platforms (e.g., Hugging Face Datasets, LangSmith datasets, JSONL).", "Discusses synthetic data generation with human-in-the-loop review to bootstrap test cases for sparse scenarios.", "May mention specific implementation examples such as: e.g., specific SQL generation, document parsing"], "negative_evidence": ["Claims a static 10-prompt text file created during initial prototyping is sufficient as a production golden dataset.", "Assumes agent-specific datasets are identical to system-level datasets."], "partial_credit": ["Explains what a golden dataset is and agrees that some tests are shared while others are agent-specific, but lacks details on schema, curation, or maintenance."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you capture agent traces and turn them into evaluation metrics and improvements?', '{"required_evidence": ["Trace Instrumentation: Injects OpenTelemetry spans or uses dedicated LLM observability tools to record every user input, reasoning step, tool call, latency, and token count.", "Metric Extraction: Aggregates trace spans to compute quantitative metrics such as tool failure rate, step-to-completion ratio, latency bottlenecks per node, and prompt token efficiency.", "Feedback Loop for Improvement: Isolates failing or suboptimal traces, clusters error modes, and feeds them into prompt refinements, few-shot example updates, and golden test suites."], "supporting_evidence": ["Mentions automated alerting on trace anomaly spikes (e.g., sudden increase in tool retry loops).", "Discusses anonymizing and sanitizing PII in traces before using them for evaluation or fine-tuning pipelines.", "May mention specific implementation examples such as: LangSmith, Arize Phoenix, Helicone, e.g., repetitive tool failures"], "negative_evidence": ["Treats traces as plain log files dumped into syslog without structured span parsing or metric extraction.", "Claims tracing is only useful during local development and should be turned off completely in production."], "partial_credit": ["Mentions logging traces to LangSmith and viewing where errors happen, but lacks concrete methods for transforming traces into systemic evaluation metrics."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you implement observability and tracing for tool usage and decision flows?', '{"required_evidence": ["Distributed Tracing Architecture: Instruments tracing using OpenTelemetry or LLM SDK callbacks, propagating trace and span IDs across agent decisions, LLM calls, and tool invocations.", "Tool Usage Telemetry: Captures tool name, input arguments, execution duration, response payloads, HTTP status codes, and error exceptions within dedicated child spans.", "Decision Flow Visualization: Correlates agent thoughts, routing branch decisions (conditional edges), and state mutations to visualize the full Directed Acyclic Graph (DAG) or cyclic execution tree."], "supporting_evidence": ["Implements structured logging with correlation IDs linking frontend user sessions to backend tool executions.", "Discusses masking sensitive tool parameters (e.g., API keys, passwords, PII) in observability dashboards."], "negative_evidence": ["Relies solely on basic ''print()'' statements scattered in Python functions without correlation IDs or structured spans.", "Assumes third-party tool execution logs cannot be tied to LLM reasoning spans."], "partial_credit": ["Mentions using tools like Datadog or LangSmith to see which tools were called, but lacks details on span propagation, parameter capture, or decision flow trees."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you debug incorrect outputs, tool usage and response formatting in multi-agent systems?', '{"required_evidence": ["Isolated Step Tracing: Traverses execution traces to identify the exact agent, prompt turn, or tool where hallucination or formatting drift originated.", "Tool Definition & Schema Refinement: Diagnoses ambiguity in tool docstrings or JSON schemas; tightens parameter descriptions, adds strict Pydantic models, or provides few-shot examples of valid tool invocations.", "Prompt & Formatting Enforcement: Employs constrained decoding, JSON mode, or output parsers with automatic retry loops (''OutputFixingParser'') to guarantee valid response structure."], "supporting_evidence": ["Uses deterministic replay / time-travel debugging (e.g., from LangGraph checkpoints) to reproduce and test fixes in isolation.", "Analyzes whether context window pollution from previous tool responses confused the downstream agent."], "negative_evidence": ["Attempts to fix multi-agent bugs by randomly altering global prompts without inspecting intermediate traces.", "Assumes malformed JSON responses can only be solved by switching to a different LLM provider."], "partial_credit": ["Suggests checking logs to see what went wrong and updating the prompt, but lacks structured debugging methodologies (trace traversal, schema validation, replay)."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you capture user feedback (accepted or rejected suggestions) to improve the system?', '{"required_evidence": ["Telemetry Capture Mechanisms: Implements UI instrumentation to capture explicit feedback (thumbs up/down, star ratings, text comments) and implicit feedback (accept/copy/edit events, session dwell time, rejection/undo actions) linked to specific ''trace_id'' / ''session_id''.", "Feedback Storage & Attribution: Stores feedback events in an analytics database alongside the exact prompt, agent execution trajectory, tool calls, and model response.", "Iterative Continuous Improvement: Uses high-confidence negative feedback to identify edge cases for golden datasets, prompt adjustments, and tool schema fixes, while positive examples are curated for few-shot prompting or DPO/RLHF fine-tuning."], "supporting_evidence": ["Computes real-time user acceptance rate (UAR) dashboards as a core business KPI for agent performance.", "Implements human review workflows to triage user-reported bugs before incorporating them into evaluation suites."], "negative_evidence": ["Captures feedback as disconnected aggregate numbers without linking to the specific prompt and execution trace.", "Assumes negative user feedback should immediately trigger automated unreviewed model weight updates."], "partial_credit": ["Mentions adding thumbs up/down buttons on the frontend and saving them in a database, but does not detail trace attribution or how feedback feeds into evaluation and model improvement."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you improve an agent with evaluation, feedback loops and iteration, especially when initial results show limited impact?', '{"required_evidence": ["Describes establishing an offline evaluation benchmark or golden test set with quantifiable metrics.", "Explains implementing continuous feedback loops such as capturing human-in-the-loop corrections, explicit/implicit user feedback (thumbs up/down, edit diffs), and execution trajectory tracing.", "Details an iterative error-analysis process: diagnosing failure modes and applying targeted fixes (prompt refactoring, dynamic few-shot examples, fine-tuning, or architectural adjustments)."], "supporting_evidence": ["Mentions automated evaluation techniques such as LLM-as-a-judge with calibrated rubrics, synthetic evaluation datasets, or A/B testing in staging/canary deployments.", "Discusses error taxonomy categorization (perception vs reasoning vs action errors) and tracking metric drift over time.", "May mention specific implementation examples such as: e.g., task success rate, tool-calling precision, trajectory accuracy, e.g., retrieval failure, planning breakdown, malformed tool arguments"], "negative_evidence": ["Suggests endlessly tweaking prompts in production ad-hoc without baseline evaluation metrics or regression test suites.", "Claims simply switching to a larger foundation model automatically resolves systemic agent orchestration and planning flaws."], "partial_credit": ["Mentions gathering user feedback and updating prompts, but lacks concrete evaluation frameworks, metrics, or systematic trajectory failure analysis."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 180, 'How do you ensure LLM-generated SQL is correct against systems like Salesforce?', '{"required_evidence": ["Recognizes Salesforce-specific constraints such as SOQL/SOSL dialect limitations.", "Explains dynamic metadata extraction using Salesforce Describe APIs / Tooling API to fetch exact object schemas, custom fields, relationships, and picklist definitions.", "Describes multi-layered validation: pre-execution SOQL parsing/linting, query dry-runs/explain plans, and strict permission enforcement via Salesforce Profile/Permission Set contexts."], "supporting_evidence": ["Mentions handling polymorphic fields (e.g., WhatId/WhoId in Task/Event objects) and pagination with SOQL query cursors/queryMore.", "Discusses fallback strategies when SOQL limitations prevent complex relational queries, such as post-processing data in memory or leveraging Salesforce Reports/Analytics APIs.", "May mention specific implementation examples such as: e.g., no ''SELECT *'', restrictive JOIN semantics, relationship query notation like Account.Name or custom __r/__c suffixes, and governor limits"], "negative_evidence": ["Treats Salesforce as a standard relational SQL database (e.g., generating standard SQL joins or SQL-92 functions that fail in SOQL).", "Ignores Salesforce API governor limits and object-level/field-level security (FLS) permissions."], "partial_credit": ["Mentions checking custom field suffixes (__c) and running queries through Salesforce APIs, but misses SOQL architectural limitations, governor limits, or schema introspection."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 180, 'How do you support both informational Q&A and action-oriented requests, and map queries to data sources?', '{"required_evidence": ["Explains intent classification and query routing: distinguishing between read-only informational requests (RAG / vector search) and transactional actions using LLM function calling, semantic routers, or classifier models.", "Details mapping queries to heterogeneous data sources: semantic retrieval for unstructured documents, text-to-SQL or text-to-API schemas for structured databases, and tool registries for external services.", "Discusses safety and confirmation barriers: requiring explicit user confirmation / dry-runs before executing destructive or irreversible action-oriented requests."], "supporting_evidence": ["Mentions dual-agent or supervisor-worker patterns (router agent dispatches to a RAG specialist or an Action execution specialist).", "Explains hybrid retrieval techniques combining dense semantic vector search with BM25 keyword search for informational queries.", "May mention specific implementation examples such as: API calls / state mutations"], "negative_evidence": ["Allows the model to directly execute write operations or update databases without intent validation, schema sanitization, or permission checks.", "Uses RAG document retrieval for transactional requests like ''transfer money'' or ''cancel my subscription''."], "partial_credit": ["Describes using prompt classification to decide whether to fetch docs or call an API, but omits query-to-data-source mapping mechanisms and confirmation safeguards."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How does an agent consolidate data across multiple databases to complete a single task?', '{"required_evidence": ["Describes an agentic workflow or planner that decomposes the task into a dependency graph of sub-queries across distinct database systems.", "Explains entity resolution and key mapping to reconcile different identifier formats and schemas across heterogeneous data stores.", "Details intermediate state management and in-memory data consolidation before synthesizing the final output."], "supporting_evidence": ["Discusses handling partial failures, network timeouts, and eventual consistency issues across distributed databases with circuit breakers or retry policies.", "Addresses security and compliance boundaries such as cross-database RBAC and data minimization during federation.", "May mention specific implementation examples such as: e.g., SQL, NoSQL, Vector DB, e.g., mapping CRM customer_id to billing account_uuid, e.g., using DataFrames, DuckDB, or SQLite in a scratchpad"], "negative_evidence": ["Assumes different disparate databases share the same primary keys and schema structure without requiring mapping or join logic.", "Suggests dumping complete raw database tables into the LLM context window to let the LLM manually ''join'' the data."], "partial_credit": ["Mentions querying database A, using the result to query database B, and summarizing them with an LLM, but lacks architecture for entity resolution or state management."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 180, 'How do you integrate a graph database (Neo4j) and use query results in generation?', '{"required_evidence": ["Describes exposing Cypher query generation or parameterized graph traversal tools to the agent, providing Neo4j node labels, relationship types, and property schemas.", "Explains executing Cypher queries safely (read-only transactions, parameter sanitization, timeout limits) and validating Cypher syntax before execution.", "Details how graph subgraphs, multi-hop relationship paths, and node attributes are formatted and injected into the LLM context for RAG generation (GraphRAG)."], "supporting_evidence": ["Discusses combining graph traversal with vector search (hybrid GraphRAG) to find vector entry points and traverse structural connections.", "Mentions using Cypher syntax repair loops where LLM regenerates queries upon receiving Neo4j execution error messages.", "May mention specific implementation examples such as: e.g., JSON, Cypher tabular results, or structured triplets"], "negative_evidence": ["Treats Neo4j as a relational database, attempting to run SQL queries instead of Cypher or Graph traversal APIs.", "Dumps unformatted, massive graph topologies directly into context, causing token overflow."], "partial_credit": ["Mentions writing Cypher queries from natural language and passing the returned nodes to an LLM, but lacks schema injection, security constraints, or GraphRAG structuring."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 180, 'How do you incorporate static analysis or external signals into agent decisions?', '{"required_evidence": ["Explains wrapping static analysis tools into deterministic callable tools or environment hooks.", "Describes structuring tool outputs (line numbers, rule violations, severity, compiler errors) into a concise diagnostic format that the agent''s reasoning loop can parse.", "Details the iterative remediation loop: agent drafts code/action -> static tool analyzes -> agent reads diagnostics -> agent reflects and adjusts its plan to fix violations before committing."], "supporting_evidence": ["Discusses combining deterministic rule engines with probabilistic LLM reasoning to enforce strict corporate coding standards and safety guarantees.", "Mentions gating actions with programmatic pass/fail policies that prevent agent execution unless all static analysis checks pass.", "May mention specific implementation examples such as: e.g., linters like flake8/eslint, AST parsers, type checkers like mypy, security scanners like Bandit/SonarQube"], "negative_evidence": ["Relies entirely on the LLM''s internal knowledge to ''imagine'' syntax and security validity without running actual external static analysis tools.", "Dumps multi-megabyte raw linter log outputs into the prompt without filtering or structuring."], "partial_credit": ["Mentions running a linter and feeding the error back to the LLM to fix bugs, but lacks architectural specifics on tool integration, structured error parsing, or decision gating."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 180, 'How do CI/CD and MLOps tools (MLflow, GitLab, Terraform) help ML and agent systems?', '{"required_evidence": ["Explains Terraform''s role: Infrastructure as Code for declaratively provisioning cloud compute, VPC networks, vector databases, IAM roles, and model endpoint infrastructure with drift detection.", "Explains GitLab''s role: automating unit/integration tests, prompt regression testing, docker container image building, and automated canary/blue-green deployments.", "Explains MLflow''s role: tracking experiments, model artifact versioning, and managing model registry lifecycles."], "supporting_evidence": ["Discusses GitOps principles where agent configurations, prompts, and tool schemas are version-controlled alongside application code.", "Covers automated eval gates in CI pipelines that block merge requests if agent accuracy on a golden test dataset drops below a defined threshold.", "Implementation examples and details: (IaC)", "Implementation examples and details: (or CI/CD)"], "negative_evidence": ["Confuses Terraform with model training frameworks, or MLflow with infrastructure provisioning tools.", "Believes MLOps is unnecessary for agentic systems because LLMs are pre-trained foundation models."], "partial_credit": ["Defines what Terraform, GitLab, and MLflow do individually, but fails to demonstrate how they integrate into a cohesive end-to-end ML/agent lifecycle."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'HARD', 'SPECIFIC', 240, 'How would you design a scalable architecture for many agents and high query volume?', '{"required_evidence": ["Describes decoupling ingestion, orchestration, and execution: API gateways, asynchronous message queues/event buses to buffer incoming queries, and stateless worker pools for agent processing.", "Explains scalable state and session management: centralized distributed caching for short-term session state and high-performance databases for persistent conversation histories and checkpoints.", "Details optimization and throughput management: semantic caching for repeated queries, token rate-limiting/circuit breaking against LLM providers, and utilizing tiered model routing ."], "supporting_evidence": ["Discusses sharding or partitioning agent checkpointers by user ID or session ID to prevent database hot spots.", "Mentions backpressure handling, priority queues for VIP users, and graceful degradation during traffic spikes.", "Implementation examples and details: (load balancing, rate limiting, authentication) (Kafka, RabbitMQ, SQS) (Kubernetes HPA)", "Implementation examples and details: (Redis) (Postgres, DynamoDB)"], "negative_evidence": ["Designs a monolithic synchronous HTTP architecture where all agent steps block web server threads, causing cascading timeouts under load.", "Stores conversation state and agent memory in local container memory or local disk in a multi-pod cluster."], "partial_credit": ["Mentions using a load balancer, Kubernetes autoscaling, and Redis cache, but lacks queuing architectures, LLM rate-limit management, or tiered model routing."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'HARD', 'SPECIFIC', 240, 'Design a platform that lets users bring their own models with standardization and abstraction.', '{"required_evidence": ["Designs a unified API abstraction layer normalizing inputs, streaming outputs, tool definitions, and token counts across diverse providers .", "Details adapter/driver architecture: pluggable provider connectors that translate standard interface calls into provider-specific schemas, handle authentication, and map response payloads.", "Implements secure model registration and validation: registering endpoints/API keys in encrypted key vaults, executing canary test probes to verify contract compliance, and managing custom runtime containers ."], "supporting_evidence": ["Discusses latency tracking, unified cost/token billing, circuit breaking, and dynamic load balancing across BYO-model endpoints.", "Mentions OpenLLM, LiteLLM proxy, or vLLM architecture as reference open-source abstraction patterns.", "Implementation examples and details: (e.g., OpenAI-compatible REST/gRPC spec) (OpenAI, Anthropic, HuggingFace, vLLM, custom endpoints)", "Implementation examples and details: (e.g., Triton, vLLM on Kubernetes)"], "negative_evidence": ["Forces developers to write bespoke wrapper code in client applications for every single proprietary model provider without an abstraction gateway.", "Assumes all models support identical hyperparameters and context behaviors without capability negotiation (e.g., function calling support, vision)."], "partial_credit": ["Suggests creating a common interface class with generic generate() methods, but omits endpoint security, dynamic adapter architecture, canary validation, and streaming normalization."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Infrastructure as Code & Security', 'MEDIUM', 'SPECIFIC', 180, 'How would you productionize agents at enterprise scale (security, access control, deployment)?', '{"required_evidence": ["Details enterprise security and access control: integrating with enterprise IAM/SSO, enforcing granular Role-Based Access Control / Attribute-Based Access Control on tool execution and data retrieval .", "Describes secure runtime sandboxing: executing untrusted agent code/tools in isolated environments with restricted egress and no access to host networks or metadata endpoints.", "Explains scalable deployment and governance: high-availability containerized orchestration, automated CI/CD evaluation gates, audit logging of all agent trajectories, and strict data loss prevention ."], "supporting_evidence": ["Discusses tenant isolation strategies (multi-tenant databases with row-level security vs dedicated per-tenant schemas/clusters).", "Mentions defense-in-depth against prompt injection and jailbreaks via input/output guardrail layers (e.g., NeMo Guardrails, Llama Guard).", "Implementation examples and details: (OAuth2/OIDC) (RBAC) (ABAC) (ensuring agents never access data unauthorized to the user)", "Implementation examples and details: (e.g., Docker, gVisor, Firecracker microVMs, AWS Lambda)"], "negative_evidence": ["Grants autonomous agents broad admin/superuser credentials to databases and APIs.", "Executes dynamic code generated by LLMs directly on production host machines without sandboxing."], "partial_credit": ["Mentions using Docker, setting up user logins, and hiding API keys in secret managers, but lacks deep enterprise security concepts like sandboxing, RBAC data scoping, or compliance auditing."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 180, 'What are the top two or three production issues you have faced with multi-agent systems, and how would you resolve them?', '{"required_evidence": ["Identifies specific realistic failure modes: infinite loops / runaway recursion between agents, context window degradation / context clobbering across multi-turn interactions, or cascading hallucinations / error amplification.", "Explains concrete resolutions for looping/deadlocks: hard recursion limits, cycle detection, deterministic supervisor timeouts, and human-in-the-loop escalation.", "Explains concrete resolutions for context/hallucination issues: strict state schemas with state reducers, aggressive context summarization/sliding windows, and validation/guardrail agents with maker-checker patterns."], "supporting_evidence": ["Discusses dealing with third-party LLM rate-limiting (HTTP 429) across parallel multi-agent swarms using token bucket rate limiters and exponential backoff.", "Mentions nondeterministic tool argument generation and fixing it with Pydantic schema validation and automated syntax retry loops."], "negative_evidence": ["Claims multi-agent systems in production never experience failures or that prompts just need to say ''be accurate and do not loop''.", "Fails to provide technical mitigation mechanisms, offering vague answers like ''I just restart the server''."], "partial_credit": ["Mentions high API costs and agents getting stuck in loops, but provides shallow or manual fixes without systematic architectural solutions."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 240, 'Given a Jira bug and a GitHub codebase, design agents for root-cause analysis, a code fix and a test. Which LLM, temperature, top-p and tools would you use?', '{"required_evidence": ["Designs a multi-agent workflow: Jira Ingestion / Triager agent, Root-Cause Analysis agent, Code Fixer agent, and QA/Testing agent .", "Specifies hyperparameter choices: low temperature and low top-p for deterministic, precise code generation and test execution, choosing a high-reasoning model .", "Identifies concrete tools: Jira API tool, GitHub search/grep/tree-sitter tools, git patch/diff generator, and isolated test runner ."], "supporting_evidence": ["Describes the verification loop: running the existing test suite, ensuring the new test fails before the fix and passes after the fix, with zero regressions.", "Mentions human-in-the-loop approval before opening a GitHub pull request or merging code.", "Implementation examples and details: (extracting reproduction steps and error logs) (searching codebase, analyzing stack traces, isolating buggy files/functions) (generating minimal targeted patches) (writing and executing regression tests in a sandbox)", "Implementation examples and details: (0.0 to 0.2) (e.g., 0.1 to 0.3) (e.g., frontier model, frontier model, or OpenAI o1/o3-mini)"], "negative_evidence": ["Recommends high temperature (e.g., 0.8 - 1.0) for code generation and bug fixing, which causes severe hallucination in code syntax.", "Allows the agent to execute untested code patches directly onto production branches without running automated tests."], "partial_credit": ["Describes the agents and tools but gives inappropriate or vague model/hyperparameter choices, or omits test execution in a sandbox."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'HARD', 'SPECIFIC', 240, 'Design a multi-agent code review system, including agent personas, PR trigger, context assembly, repository standards and evaluation metrics.', '{"required_evidence": ["Defines specialized agent personas: Security Auditor, Performance/Architecture Reviewer, Style & Standards Reviewer, and Lead Reviewer/Synthesizer .", "Details PR trigger and context assembly: GitHub/GitLab webhook on PR open/synchronize, fetching git diff, PR description, related Jira/issue tickets, and surrounding AST/file context rather than just raw diff hunks.", "Explains repository standards enforcement and evaluation metrics: injecting linter rules, style guides, and ADRs into agent prompts; measuring metrics like comment acceptance rate, developer false-positive rate, and review turnaround time."], "supporting_evidence": ["Discusses inline commenting via GitHub API and suppressing noisy, low-confidence suggestions.", "Mentions human reviewer feedback loops to continuously fine-tune agent personas and prompt guidelines.", "Implementation examples and details: (detecting vulnerabilities, secret leaks, injection flaws) (evaluating algorithmic complexity, database queries, anti-patterns) (enforcing repo conventions, naming, test coverage) (deduplicating and formatting the final PR comment)"], "negative_evidence": ["Designs a system that bombards developers with hundreds of trivial, unverified comments on every PR line.", "Relies solely on raw diffs without inspecting surrounding file context or project dependency architecture."], "partial_credit": ["Describes a webhook triggering an LLM to review a PR and post comments, but lacks multi-agent persona specialization, context assembly, or evaluation metrics."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 180, 'Design ticket triage and routing with agentic AI, and identify the main challenges.', '{"required_evidence": ["Designs the triage architecture: ticket ingestion, intent classification and severity/urgency scoring, entity extraction, and automated routing to appropriate support queues or automated resolution agents.", "Explains the retrieval and resolution pipeline: querying knowledge bases, historical resolved tickets, and system status dashboards to generate automated replies or diagnostic summaries.", "Identifies main production challenges: handling ambiguous/poorly written tickets,, data privacy, and catastrophic drift in ticket categories over time."], "supporting_evidence": ["Discusses confidence scoring thresholds where low-confidence classifications automatically fall back to human triage teams.", "Mentions automated sentiment analysis and SLA breach countdown monitoring.", "Implementation examples and details: (account ID, system affected, error codes)", "Implementation examples and details: (PII/credentials in tickets)"], "negative_evidence": ["Assumes all tickets can be resolved autonomously without human escalation or guardrails for sensitive edge cases.", "Proposes static keyword matching that breaks when users use non-standard terminology or slang."], "partial_credit": ["Explains categorizing tickets with an LLM and assigning them to teams, but overlooks security/PII, confidence thresholds, or edge-case handling."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 240, 'Design recruiting agents (resume analysis, candidate fit, bias/fairness, interview design, hiring decision) and multi-step HR workflows.', '{"required_evidence": ["Details specialized agents: Resume Parser/Extractor, Candidate Fit Evaluator, Bias & Fairness Auditor, and Interview Designer .", "Emphasizes strict compliance, ethics, and human authority: agents serve exclusively as decision-support; hiring/rejection decisions MUST remain with human recruiters/managers .", "Describes bias mitigation techniques: blind resume screening and evaluating based strictly on demonstrable skills and rubric alignment."], "supporting_evidence": ["Discusses legal and regulatory compliance (e.g., EEOC, NYC Local Law 144 on Automated Employment Decision Tools, EU AI Act requirements).", "Mentions tracking fairness metrics across candidate cohorts (disparate impact ratio, false rejection rates across subgroups).", "Implementation examples and details: (converting heterogeneous formats into structured profiles) (mapping experience against JD requirements using competency rubrics) (scrubbing demographic data, monitoring adverse impact, auditing evaluation criteria) (generating tailored technical/behavioral interview rubrics)", "Implementation examples and details: (preventing autonomous automated rejections)"], "negative_evidence": ["Advocates delegating final hiring or termination decisions completely to autonomous AI agents without human oversight.", "Ignores demographic bias, allowing models to evaluate candidates on subjective criteria or biased proxies (e.g., hobbies, school pedigree, gendered phrasing)."], "partial_credit": ["Describes parsing resumes and matching them to job descriptions, but fails to address bias/fairness, legal regulations, or human-in-the-loop decision boundaries."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 240, 'Design an agentic system for document understanding and generating insights from heterogeneous data.', '{"required_evidence": ["Describes multi-modal document ingestion and layout analysis: utilizing OCR, vision-language models, and document layout parsers to parse tables, forms, text, diagrams, and scanned PDFs.", "Explains multi-agent insight generation: specialized Extraction Agents, Cross-Document Synthesis Agent, and Insight/Reasoning Agent .", "Details verification and ground-truth traceability: providing exact page/bounding box citations and confidence scores for every extracted data point and synthesized insight."], "supporting_evidence": ["Discusses hybrid storage architecture: vector stores for semantic retrieval, relational/document DBs for structured fields, and knowledge graphs for interconnected entities.", "Mentions human-in-the-loop validation queues for documents with low OCR confidence or high extraction ambiguity.", "Implementation examples and details: (e.g., LayoutLM, unstructured)", "Implementation examples and details: (normalizing data into unified schemas) (reconciling conflicting information and cross-referencing sources) (computing aggregations, spotting anomalies, generating executive summaries)"], "negative_evidence": ["Attempts to extract tabular financial data or multi-column forms using naive text splitters without layout-aware parsing or vision models.", "Generates insights without source citations or verifiable references back to the original documents."], "partial_credit": ["Describes reading PDFs with an LLM and asking questions, but lacks multi-modal layout parsing, cross-document reconciliation, or citation mechanisms."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 240, 'Design a matchmaking or recommendation orchestrator that improves from feedback and optimizes long-term retention. Compare agentic, traditional ML and hybrid approaches.', '{"required_evidence": ["Compares paradigms: Traditional ML excels at ultra-low latency, high-throughput candidate retrieval over millions of items; Agentic approaches excel at deep contextual understanding, conversational elicitation, and reasoning over complex user preferences; Hybrid approach uses traditional ML for fast retrieval/filtering and agentic LLMs for multi-factor ranking, personalization, and explanation.", "Explains feedback loops and long-term retention: capturing explicit feedback and implicit feedback, utilizing contextual bandits or reinforcement learning from user feedback to balance exploration vs exploitation.", "Details the orchestrator architecture: candidate generator -> feature enrichment -> agentic ranker/reasoner -> diversity/novelty filter -> telemetry logger tracking retention cohorts."], "supporting_evidence": ["Addresses cold-start problems for new users/items using conversational agent interviews to rapidly establish preferences.", "Discusses avoiding filter bubbles and engagement-trap optimizations that harm long-term retention in favor of short-term clicks.", "Implementation examples and details: (collaborative filtering, matrix factorization, two-tower neural networks) (top-K)", "Implementation examples and details: (ratings, reviews) (dwell time, clicks, churn signals) (RLUF)"], "negative_evidence": ["Proposes using a raw LLM to scan a catalog of 10 million items directly on every user recommendation request.", "Claims traditional ML is completely obsolete and should never be used in modern recommendation systems."], "partial_credit": ["Compares traditional ML and LLMs and mentions user clicks, but lacks architectural details on hybrid candidate generation/re-ranking and long-term retention feedback loops."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 180, 'How can agents be applied to non-engineering uses such as project management or risk identification?', '{"required_evidence": ["Identifies specific operational workflows: automated project management and enterprise risk identification .", "Explains the agentic loop: continuous passive data ingestion from enterprise productivity tools -> correlation and dependency mapping -> proactive alerting and actionable mitigation drafting .", "Discusses human oversight and trust: presenting synthesized risk signals with clear evidence citations and requiring project manager approval before modifying roadmaps or sending alerts."], "supporting_evidence": ["Mentions predictive risk scoring based on historical project velocity and communication sentiment changes.", "Covers multi-agent collaboration (e.g., a Schedule Agent, Resource Agent, and Risk Agent negotiating trade-offs).", "Implementation examples and details: (cross-referencing Slack/Teams discussions, emails, and Jira/Asana boards to detect blocked tasks, compute milestone progress, and update schedules) (monitoring supplier delays, contract clauses, budget variances, and compliance deadlines)", "Implementation examples and details: (e.g., generating re-allocation plans or drafting escalation emails)"], "negative_evidence": ["Assumes non-engineering agents can automatically fire employees or cancel vendor contracts without human intervention.", "Restricts application to simple generic chatbots answering FAQ questions rather than proactive autonomous workflow management."], "partial_credit": ["Describes an agent summarizing meeting notes and sending reminders for upcoming deadlines, but lacks proactive risk detection or cross-platform enterprise integration."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Multi-Cloud Architecture & Comparison', 'MEDIUM', 'SPECIFIC', 180, 'What is your experience across AWS, Azure and GCP, and what factors decide which platform you use for a project? Have you programmed against Azure frameworks?', '{"required_evidence": ["Compares major cloud ecosystems across core capabilities: AWS, Azure, and GCP .", "Decision factors: existing client enterprise commitments/agreements, data residency and compliance requirements, ecosystem lock-in, tool maturity, and pricing/discount tiers .", "Azure programming experience: working with Azure SDKs, Azure Functions, Azure Blob Storage, Azure OpenAI / Azure AI Foundry SDK, or Azure Resource Manager /Bicep/Terraform."], "supporting_evidence": ["Discusses hybrid identity (Microsoft Entra ID / Managed Identities) and role-based access control (RBAC) across Azure subscriptions and resource groups.", "Explains networking paradigms (VNet peering vs AWS VPC peering, Private Endpoints vs PrivateLink).", "Implementation examples and details: (market maturity, broad service breadth like Bedrock/SageMaker/Lambda) (enterprise AD/Entra ID integration, OpenAI Service, Copilot, Microsoft 365 synergy) (data engineering with BigQuery, Vertex AI, Kubernetes/GKE leadership)", "Implementation examples and details: (e.g., Azure Enterprise Agreement)"], "negative_evidence": ["Claims all three clouds have identical APIs and management paradigms, or shows no awareness of platform-specific flagship strengths (e.g., Azure OpenAI exclusive partnership vs Bedrock multi-model approach)."], "partial_credit": ["Lists the clouds and some services (EC2, S3, Azure VMs), but cannot articulate a nuanced decision matrix or programmatic experience with Azure SDKs."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'What is your experience with multimodal models, and how do you integrate multiple models into one system?', '{"required_evidence": ["Explains multimodal model architectures and modalities: Vision-Language Models, Audio/Speech models, and text models, highlighting cross-attention or projection layers connecting modality encoders to language backbones.", "Describes system integration patterns: pipeline/compositional integration vs unified native multimodal foundation models.", "Details multi-model orchestration: managing disparate latencies, coordinating asynchronous streaming inputs, aligning shared embedding spaces, and memory/GPU resource allocation."], "supporting_evidence": ["Discusses handling modality fusion (early fusion vs late fusion) and tokenization budgets across image patches and text tokens.", "Covers edge/device deployment trade-offs between monolithic multimodal models and chained lightweight specialized models.", "Implementation examples and details: (e.g., CLIP, LLaVA, frontier modelV) (Whisper)", "Implementation examples and details: (e.g., Whisper for speech-to-text -> LLM for reasoning -> TTS for speech, or OCR/Object Detection -> LLM)"], "negative_evidence": ["Assumes multimodal models convert images to ASCII text strings before processing.", "Fails to recognize latency or compute bottlenecks when chaining heavy models (e.g., vision + speech + reasoning) in a single synchronous request."], "partial_credit": ["Mentions passing images to frontier modelV or using Whisper for audio transcription, but lacks architectural depth on modality fusion, unified embedding spaces, or pipeline orchestration."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 180, 'How would you approach a clustering problem: algorithm choice, choosing the number of clusters, and evaluation?', '{"required_evidence": ["Guides algorithm selection based on data characteristics: K-Means, DBSCAN/HDBSCAN, Hierarchical, GMM .", "Explains techniques for choosing K: Elbow method with inertia/SSE, Silhouette analysis across various K, Gap statistic, and business/domain interpretability constraints.", "Details clustering evaluation: internal metrics, stability analysis, and external business validation ."], "supporting_evidence": ["Discusses preprocessing prerequisites: feature scaling (StandardScaler/MinMaxScaler) and handling categorical features or high dimensionality (PCA/UMAP).", "Mentions how distance metrics (Euclidean, Cosine, Manhattan) dictate clustering outcomes.", "Implementation examples and details: (spherical clusters, uniform sizes, scalable) (arbitrary non-convex shapes, noise/outlier resistance, unknown cluster count) (small datasets, dendrograms/nested structures) (probabilistic soft assignment)", "Implementation examples and details: (Silhouette score, Calinski-Harabasz, Davies-Bouldin) (bootstrapping/cross-sample clustering consistency) (correlation with downstream KPIs)"], "negative_evidence": ["Applies K-Means to unscaled features with vastly different magnitudes (e.g., Age 0-100 and Salary 0-200,000).", "Selects K purely by picking an arbitrary number without plotting the elbow curve, calculating silhouette scores, or justifying domain constraints."], "partial_credit": ["Mentions using the elbow method for K-Means and calculating silhouette scores, but does not compare alternative algorithms like DBSCAN or discuss data preprocessing and stability."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 180, 'How would you assess the impact of onboarding and early product interactions on user spending patterns?', '{"required_evidence": ["Describes experimental and causal inference frameworks: randomized controlled trials as gold standard; quasi-experimental methods when A/B testing is infeasible.", "Identifies key metrics and cohort definitions: onboarding milestone completion rates, time-to-first-value,, LTV, retention curves, and monetization conversion rates across user cohorts.", "Explains addressing confounding variables and selection bias: controlling for acquisition channel, user demographic/firmographic attributes, marketing spend, and pre-existing purchase intent."], "supporting_evidence": ["Discusses survival analysis (Kaplan-Meier, Cox Proportional Hazards) to model time-to-first-purchase or churn risk.", "Mentions correlation vs causation pitfalls, such as highly motivated users naturally completing onboarding and spending more regardless of onboarding quality.", "Implementation examples and details: (A/B testing new onboarding flows) (Difference-in-Differences, Propensity Score Matching, Causal Impact/Synthetic Controls)", "Implementation examples and details: (TTFV) (Lifetime Value)"], "negative_evidence": ["Conflates correlation with causation, claiming that because users who finish onboarding spend more money, onboarding caused the increased spending without controlling for selection bias.", "Measures only immediate day-1 conversions, completely ignoring long-term retention and repeat spending patterns."], "partial_credit": ["Mentions tracking user cohorts and comparing spending between users who completed onboarding vs those who didn''t, but fails to address causal inference or selection bias."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How do you decide between traditional ML and LLMs? Which problems are unsuited to either?', '{"required_evidence": ["Decision criteria for Traditional ML : preferred for structured tabular data, high-throughput ultra-low-latency requirements, strict explainability/feature importance needs, and predictable mathematical optimization.", "Decision criteria for LLMs: preferred for unstructured text, multimodal reasoning, zero-shot/few-shot natural language comprehension, freeform text generation, summarization, and complex conversational interfaces.", "Identifies problems unsuited to either: problems unsuited to traditional ML include complex unstructured dialogue, open-domain semantic understanding, and creative content generation; problems unsuited to LLMs include low-latency high-frequency trading, exact deterministic arithmetic, graph traversal/combinatorial optimization, and tabular prediction where tree-based algorithms dominate."], "supporting_evidence": ["Mentions hybrid architectures (e.g., using an LLM for feature engineering from unstructured text, which is then fed into an XGBoost classifier).", "Discusses regulatory explainability (e.g., credit scoring where SHAP/LIME with traditional models is legally mandated over black-box LLMs).", "Implementation examples and details: (e.g., XGBoost, Random Forests, Logistic Regression) (<10ms)"], "negative_evidence": ["Proposes using an LLM to predict numerical tabular records (like housing prices or credit default probabilities) where XGBoost is standard.", "Claims traditional ML is obsolete and LLMs should be used for every machine learning problem."], "partial_credit": ["Notes that traditional ML is good for tabular data and LLMs for text, but does not provide clear criteria on latency, cost, explainability, or unsuited problem spaces."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Development Methodologies', 'MEDIUM', 'SPECIFIC', 180, 'What is spec-driven development, and how does it affect modern software workflows?', '{"required_evidence": ["Defines spec-driven development : writing formal, machine-readable specifications before writing implementation code.", "Explains the impact on workflows: parallel frontend/backend development via automated mock servers, automated SDK/client generation, and contract testing .", "Connects spec-driven development to modern AI/LLM workflows: specifications serve as deterministic schemas for tool-calling function definitions and prompt ground-truth contracts."], "supporting_evidence": ["Discusses single source of truth benefits preventing documentation drift and catching breaking changes in CI/CD before deployment.", "Mentions spectral/linter enforcement of API standards across distributed teams.", "Implementation examples and details: (API-first / contract-first development) (e.g., OpenAPI/Swagger, AsyncAPI, Protobuf/gRPC, JSON Schema)", "Implementation examples and details: (Pact)"], "negative_evidence": ["Confuses spec-driven development with traditional waterfall requirements documentation or PRD docs.", "Assumes specifications are created after code is fully written purely for documentation purposes."], "partial_credit": ["Explains writing API specifications in Swagger first so frontend developers know what endpoints to call, but misses SDK generation, contract testing, or AI tool calling implications."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic Architectures & Workflows', 'MEDIUM', 'SPECIFIC', 180, 'Is the output validated by a human or another agent before it moves to the next environment? How does that flow work?', '{"required_evidence": ["Differentiates between LLM-as-a-judge / critic agent automated validation and Human-in-the-Loop review gates.", "Explains the technical workflow for gating: pausing execution via checkpoints/interrupts, persisting state, notifying external services, awaiting approval/edit signals, and resuming execution.", "Defines thresholding or routing criteria that trigger human escalation vs. automatic agent approval ."], "supporting_evidence": ["Discusses dual-key authorization or audit trails for regulatory compliance when promoting state changes to staging or production environments.", "Mentions state modification capabilities where human reviewers can amend intermediate agent state before resuming graph execution.", "Implementation examples and details: (evaluating schema compliance, hallucination, policy checks) (HITL)", "Implementation examples and details: (webhooks/Slack/UI)"], "negative_evidence": ["Believes production AI agents should execute irreversible side effects across environments without validation gates or verification mechanisms.", "Assumes human-in-the-loop requires synchronous HTTP long-polling rather than asynchronous event-driven state suspension."], "partial_credit": ["Mentions having another prompt verify the response or having an admin check a dashboard, but lacks architecture details on workflow suspension, resume, and threshold criteria."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic Workflows & LangGraph', 'MEDIUM', 'SPECIFIC', 180, 'How do you store and manage conversation history, and how do you persist memory across sessions (short-term versus long-term)?', '{"required_evidence": ["Differentiates short-term vs long-term memory: short-term memory manages recent multi-turn dialogue context within an active session, while long-term memory persists user facts, preferences, and recurring entities across distinct sessions .", "Details short-term context management: sliding window token limits, recursive summarization of older dialogue turns, and message pruning to prevent context overflow.", "Details long-term memory extraction and retrieval: asynchronously extracting key facts/preferences via background LLM extraction, embedding user memories into a vector store or graph database, and performing semantic search at session initialization to inject relevant memories into the system prompt."], "supporting_evidence": ["Discusses privacy and memory hygiene: allowing users to view, edit, or delete stored memories (GDPR ''Right to be Forgotten'').", "Mentions memory systems like MemGPT/Letta or LangGraph Store.", "Implementation examples and details: (thread-scoped, stored in in-memory caches like Redis with TTLs) (user-scoped, stored in databases or vector stores)"], "negative_evidence": ["Suggests storing all historical messages across months into a single raw database table and dumping them into every prompt context.", "Conflates short-term session state with long-term cross-session knowledge."], "partial_credit": ["Distinguishes Redis for session history and database for persistent storage, but does not explain how long-term memories are extracted, indexed, or selectively retrieved."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'RAG & Vector Search', 'MEDIUM', 'SPECIFIC', 180, 'How do you evaluate groundedness, and how do you use it in a RAG or agent project?', '{"required_evidence": ["Defines groundedness : verifying that every factual claim in the generated output is directly supported and entailed by the retrieved context, preventing ungrounded hallucinations.", "Explains quantitative evaluation frameworks and metrics utilizing LLM-as-a-judge with chain-of-thought verification or NLI models.", "Details how groundedness scores are operationalized in production pipelines: gating responses, triggering fallback retrieval/regeneration loops when groundedness drops below a threshold, or alerting monitoring dashboards."], "supporting_evidence": ["Contrasts groundedness with context relevance (retrieval quality) and answer relevance (alignment to user intent) in the RAG triad.", "Mentions sentence-level attribution and citation generation to map output spans back to source chunk IDs.", "Implementation examples and details: (faithfulness)", "Implementation examples and details: (e.g., Ragas, TruLens, DeepEval, or G-Eval) (Natural Language Inference)"], "negative_evidence": ["Confuses groundedness with semantic similarity (e.g., cosine similarity of embeddings between answer and question) or BLEU/ROUGE lexical overlap.", "Believes high groundedness guarantees the answer is factually correct in the real world even if retrieved context is completely wrong or poisoned."], "partial_credit": ["Explains that groundedness means the answer comes from the context, but fails to explain how to evaluate it programmatically or integrate it into automated checks."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'CI/CD & Automation', 'MEDIUM', 'SPECIFIC', 180, 'How do you generate test strategies, identify black-box scenarios, and detect edge cases in AI-driven QA?', '{"required_evidence": ["Explains test strategy formulation: combining risk-based testing, boundary value analysis, state-transition testing, and synthetic user personas simulating diverse user expertise and intent.", "Details black-box scenario identification: probing systems via exploratory testing, behavioral fuzzing, and adversarial red-teaming .", "Describes automated edge-case detection: clustering low-confidence production logs, using LLM-assisted synthetic adversarial generation, and mutation testing."], "supporting_evidence": ["Mentions metamorphic testing (verifying that transformations like adding polite filler text do not alter the factual answer).", "Discusses automated invariant checks (e.g., property-based testing with Hypothesis).", "Implementation examples and details: (varying prompt phrasing, length, punctuation, multilingual inputs) (jailbreak attempts, prompt injections, contradictory premises)", "Implementation examples and details: (generating negative test cases targeted at known model weaknesses)"], "negative_evidence": ["Relies only on ''happy path'' test scenarios provided by developers.", "Assumes testing AI is identical to traditional deterministic software without accounting for non-determinism, hallucinations, or prompt vulnerability."], "partial_credit": ["Mentions testing edge cases like long inputs and prompt injections, but lacks a systematic methodology (fuzzing, metamorphic testing, production failure clustering, red teaming)."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'What are the trade-offs when evolving a product from traditional interfaces to a conversational AI experience?', '{"required_evidence": ["Analyzes user experience trade-offs: conversational naturalness and multi-intent flexibility versus discoverability of features, visual hierarchy, input latency, and cognitive load.", "Contrasts deterministic UI predictability with non-deterministic probabilistic LLM responses and hallucination risks.", "Proposes hybrid UI / generative UI architectures rather than pure text chat."], "supporting_evidence": ["Discusses accessibility, mobile responsiveness, and latency implications (streaming tokens vs. instantaneous pre-rendered client interactions).", "Explains the cost implications of per-interaction token usage compared to static client-side computation and server API calls.", "Implementation examples and details: (forms, buttons, known state transitions)", "Implementation examples and details: (e.g., conversational chat combined with interactive widgets, forms, charts, and structured controls)"], "negative_evidence": ["Claims pure conversational chat is strictly superior to traditional GUI interfaces for all product workflows, including dense tabular editing.", "Ignores the loss of feature discoverability inherent in an empty text input box."], "partial_credit": ["Discusses that chat is easy for users but LLMs can be slow or give wrong answers, without touching on hybrid UI designs, discoverability, or deterministic state tradeoffs."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How do you handle dynamic user requests that evolve over time (for example, adding data from multiple projects to a BOM)?', '{"required_evidence": ["Architects a dynamic state management engine that tracks session state, entity relationships, and incremental mutations across multi-turn interactions.", "Describes conflict resolution and data reconciliation strategies when merging disparate datasets .", "Implements conversational checkpointing and reversible undo/redo or staging operations so users can review, modify, and confirm incremental additions before final commit."], "supporting_evidence": ["Discusses optimistic locking and transactional consistency in the underlying relational or graph database when multiple concurrent updates occur.", "Details intent disambiguation workflows where the agent explicitly clarifies ambiguous project references or missing attribute schemas.", "Implementation examples and details: (delta updates)", "Implementation examples and details: (e.g., schema mapping, part number deduplication, units normalization, versioning in a Bill of Materials)"], "negative_evidence": ["Overwrites the entire document or BOM state with each LLM response without tracking provenance or diffs.", "Relies on prompt context alone to maintain complex tabular data integrity across dozens of turns without structured backend storage."], "partial_credit": ["Suggests storing previous user choices in session state or a database and appending new project items to an array without addressing schema alignment, conflicts, or validation."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'HARD', 'SPECIFIC', 240, 'How do you design RBAC and need-based access with multiple user personas, including authentication credentials and data visibility?', '{"required_evidence": ["roles, tenant IDs, and fine-grained permissions.", "Designs multi-tier access control: Role-Based Access Control mapped to roles and Attribute-Based Access Control evaluating contextual attributes .", "Implements data visibility and filtering at the database/storage layer so users never retrieve unauthorized records."], "supporting_evidence": ["Mentions centralized authorization policy engines like Open Policy Agent (OPA) or AWS Cedar / Oso.", "Discusses least-privilege credential scoping for API tokens and audit logging of access decisions.", "Numeric heuristics: Architects authentication and identity token flows: issuing OAuth2/OIDC JWTs containing user claims", "Implementation examples and details: (RBAC) (ABAC) (department, clearance level, resource ownership)"], "negative_evidence": ["Performs security filtering solely in frontend UI logic or downstream LLM prompts while returning all records from the database.", "Stores user roles directly in unverified client-side cookies or localStorage."], "partial_credit": ["Explains defining roles like Admin, Editor, Viewer in a database table and checking user.role in API controllers, without addressing data-layer row-level security or ABAC."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic Architectures & Workflows', 'MEDIUM', 'SPECIFIC', 180, 'How do you make a code review agent follow repository-specific style after negative feedback?', '{"required_evidence": ["Implements dynamic in-context retrieval of repository-specific guidelines, style manuals, .editorconfig/linter configs, and few-shot examples of accepted vs. rejected PR reviews.", "Establishes a feedback ingestion loop: capturing negative human feedback and persisting it into a vector/key-value memory store linked to the repository.", "Integrates deterministic static analysis tools into the agent''s toolset so style enforcement is verified by deterministic linters rather than relying purely on LLM heuristics."], "supporting_evidence": ["Discusses iterative self-reflection (Reflection pattern) where the agent compares draft comments against learned repo constraints before publishing.", "Mentions parameter-efficient fine-tuning (PEFT/LoRA) on curated historical PR review data if in-context learning reaches context capacity.", "Implementation examples and details: (e.g., thumbs down, review comment rejections, developer corrections)", "Implementation examples and details: (e.g., ESLint, Ruff, SonarQube)"], "negative_evidence": ["Suggests retraining base foundation models from scratch every time a developer rejects a style comment.", "Assumes hardcoding developer complaints into one giant static prompt is a scalable long-term solution."], "partial_credit": ["Suggests updating the system prompt with the developer''s complaint or adding a few examples to the prompt, without discussing automated feedback loops or linter integration."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Framework Evaluation & Architecture', 'MEDIUM', 'SPECIFIC', 180, 'How do you evaluate and choose between frameworks? Have you used both options in a comparison, and what drove the choice?', '{"required_evidence": ["Articulates a structured framework evaluation approach based on key technical dimensions: developer ergonomics, community/ecosystem maturity, production observability, latency overhead, flexibility/extensibility, and vendor lock-in.", "Provides a concrete comparison between two relevant alternatives .", "Explains business and operational drivers: team skill sets, maintenance burden, documentation clarity, debugging ease, and performance benchmarks."], "supporting_evidence": ["Highlights pitfalls of overly opinionated frameworks that abstract too much (''framework bloat'' or leaky abstractions) versus lightweight modular libraries.", "Mentions building minimal POC benchmarks with identical synthetic workloads to measure memory usage and throughput before committing.", "Implementation examples and details: (e.g., LangChain vs. LlamaIndex, LangGraph vs. AutoGen/CrewAI, FastAPI vs. Django/Flask, React vs. Vue)"], "negative_evidence": ["Chooses a framework purely based on GitHub stars, social media hype, or marketing claims without technical evaluation.", "Inability to cite trade-offs or limitations of the framework they selected."], "partial_credit": ["Compares two frameworks superficially (e.g., ''X is easier to learn than Y'') without discussing architectural trade-offs, production maintenance, or empirical criteria."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Causal Inference & Experimentation', 'MEDIUM', 'SPECIFIC', 180, 'How do you run A/B tests to compare model versions in production? Which metrics do you use, and how do you tie them to business outcomes?', '{"required_evidence": ["Experimentation setup & randomization: randomize at the user/session level using hashing algorithms to ensure consistent bucket assignment; verify Sample Ratio Mismatch to ensure unbiased treatment vs control cohorts.", "Metric hierarchy: define primary model quality metrics, guardrail/operational metrics, and North Star business metrics .", "Statistical rigor & power analysis: calculate required sample size upfront based on Minimum Detectable Effect, statistical power, and significance level; apply corrections for multiple hypothesis testing.", "Bridging model metrics to business outcomes: establish causal attribution via synthetic controls or instrumental variables, tracking long-term holdout groups to measure whether surrogate metric gains translate into durable revenue or churn reduction."], "supporting_evidence": ["Discuss CUPED (Controlled-experiment Using Pre-Experiment Data) variance reduction to achieve statistical significance faster.", "Explain network interference / spillover effects in two-sided marketplaces and cluster-based randomization to counter them.", "Implementation examples and details: (SRM)", "Implementation examples and details: (acceptance rate, click-through rate, completion rate) (latency, error rate, cost per query) (revenue, retention, conversion)"], "negative_evidence": ["P-hacks by continually checking p-values every hour and stopping the experiment early the moment p < 0.05 without sequential testing corrections.", "Measures only offline validation accuracy or immediate clicks without checking guardrail latency, error rates, or business cannibalization."], "partial_credit": ["Explains splitting users 50/50 and measuring CTR and conversion, but lacks discussion of sample size estimation, SRM checks, or causal linkage to business outcomes."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Domain Engineering & CAD/BIM', 'MEDIUM', 'SPECIFIC', 180, 'Have you worked with CAD or engineering software?', '{"required_evidence": ["Identifies experience or architectural familiarity with CAD/BIM/CAE environments .", "Explains technical challenges of engineering data: handling proprietary binary schemas, boundary representation, parametric modeling, mesh tessellation", "Discusses programmatic integration methods: CAD SDKs/APIs for automated geometry extraction, metadata parsing, or drawing generation."], "supporting_evidence": ["Mentions integrating AI models with spatial/geometric data or converting engineering designs into Bill of Materials (BOM) data structures.", "Discusses browser-based 3D visualization using WebGL, Three.js, or IFC.js.", "Implementation examples and details: (e.g., AutoCAD, SolidWorks, Revit, Autodesk Platform Services/Forge, FreeCAD, or IFC/STEP file formats)", "Implementation examples and details: (B-Rep)"], "negative_evidence": ["Confuses 2D vector graphic design tools (Illustrator, Figma) with parametric 3D CAD engineering platforms.", "Claims CAD models are just standard image files (PNG/JPEG) that an off-the-shelf vision model can fully inspect without 3D geometry parsing."], "partial_credit": ["States basic familiarity with viewing 3D models or using CAD software as an end-user, without explaining underlying data structures, APIs, or integration patterns."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'How do you detect and prevent data leakage (both training-data leakage and sensitive-data leakage), and what role do tools like Presidio play?', '{"required_evidence": ["Differentiates between training-data leakage and sensitive data leakage .", "Explains the role and operation of Microsoft Presidio: Presidio Analyzer uses regex, NER, and context words to detect PII; Presidio Anonymizer masks, hashes, redacts, or encrypts entities.", "Outlines multi-layered prevention pipelines: pre-ingestion sanitization, egress guardrails inspecting model outputs, strict evaluation benchmark decontamination, and differential privacy techniques."], "supporting_evidence": ["Discusses synthetic surrogate data substitution (pseudonymization) to preserve linguistic semantics while masking real PII.", "Mentions zero-data retention agreements with model API vendors and canary string detection.", "Implementation examples and details: (eval/test data contaminating pre-training or fine-tuning datasets, membership inference) (PII/secrets leaking into prompts, training corpora, or LLM completions)", "Implementation examples and details: (spaCy/HuggingFace)"], "negative_evidence": ["Assumes that asking the LLM ''Do not reveal any passwords or SSNs'' in the prompt is sufficient to prevent data leakage.", "Confuses ML benchmark data contamination with network packet sniffing."], "partial_credit": ["Explains that Presidio finds and masks PII like names and credit card numbers, but does not address training-data decontamination or systemic leak prevention pipelines."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'What guardrails do you apply for security, correctness and appropriate outputs, especially with internal enterprise documents and regulated industries?', '{"required_evidence": ["Details input guardrails: prompt injection detection, jailbreak classifiers, PII sanitization, and scope/relevance checks .", "Details output guardrails: hallucination/groundedness checks against source enterprise docs, regex/schema adherence, toxicity/bias filtering, and policy constraint checking.", "Addresses regulatory and compliance requirements : deterministic audit logs, traceable source citations for every claim, and cryptographic provenance."], "supporting_evidence": ["Discusses defensive system prompt patterns (delimiter wrapping, instruction hierarchy) combined with secondary evaluator models.", "Mentions automated fallback behaviors (safe canned refusal messages) when guardrails trigger.", "Implementation examples and details: (e.g., NeMo Guardrails, Llama Guard)", "Implementation examples and details: (JSON/Pydantic)"], "negative_evidence": ["Relies entirely on soft prompt instructions (''Be polite and do not leak secrets'') as the sole enterprise security layer.", "Believes guardrails can only be implemented as manual human review of every single LLM output."], "partial_credit": ["Mentions checking for bad words, validating JSON schemas, and asking the model not to hallucinate, without covering injection defense, compliance requirements, or programmatic guardrail frameworks."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How do you scale document ingestion for large volumes across multiple teams?', '{"required_evidence": ["Implements a multi-tenant distributed architecture: partitioned message queues, tenant-aware rate limiting, and fair-share scheduling to prevent noisy-neighbor starvation.", "Designs horizontally scalable worker pools: containerized microservices auto-scaling on queue depth, decoupling CPU-bound parsing/chunking from GPU-bound embedding generation.", "Ensures data isolation and schema governance: team-level namespaces/metadata tagging, centralized schema registries, and isolated vector collections/indexes."], "supporting_evidence": ["Discusses batching embedding API requests to maximize GPU throughput and optimize cloud inference API rate limits.", "Mentions backpressure handling, circuit breaking, and centralized monitoring with per-team quota dashboards.", "Implementation examples and details: (Kafka topics per domain/tenant or prioritized queues)", "Implementation examples and details: (using KEDA on Kubernetes)"], "negative_evidence": ["Allows all teams to write synchronously to a single monolithic ingestion database without queues, rate limits, or concurrency controls.", "Scales worker nodes purely vertically on a single VM until memory runs out."], "partial_credit": ["Suggests putting documents into Kafka and using Docker containers with Kubernetes to scale workers, without addressing multi-tenancy, fair-share scheduling, or tenant isolation."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'MLOps & Experimentation', 'MEDIUM', 'SPECIFIC', 180, 'What is a challenger-champion setup in an experimentation framework?', '{"required_evidence": ["Defines the pattern: the ''Champion'' is the currently proven, incumbent production model/system handling primary production traffic; the ''Challenger'' is one or more candidate models tested concurrently against it.", "Explains traffic routing and evaluation mechanisms: shadow execution or low-percentage live canaries, with continuous automated KPI comparison.", "Outlines promotion and rollback criteria: automated promotion of the challenger to champion status once it statistically outperforms the champion across key business and performance metrics without regressions."], "supporting_evidence": ["Contrasts champion-challenger setups with multi-armed bandits (dynamic traffic allocation based on reward exploitation vs exploration).", "Mentions infrastructure routing via API gateways, service meshes (Istio), or model server multi-model endpoints.", "Implementation examples and details: (challenger processes production traffic asynchronously in parallel without serving the user)"], "negative_evidence": ["Confuses champion-challenger with simple git branch merging or standard unit testing.", "Claims the challenger must immediately replace the champion across 100% of production traffic before evaluating performance."], "partial_credit": ["Explains that champion is the current model and challenger is the new model tested against it, but misses routing details, shadow modes, or automated statistical promotion criteria."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'MLOps & Experimentation', 'MEDIUM', 'SPECIFIC', 180, 'How do you support experimentation and model evaluation for data scientists?', '{"required_evidence": ["Provides self-service scalable infrastructure: managed Jupyter/JupyterHub environments on Kubernetes, on-demand GPU/CPU compute clusters, and pre-configured dev containers.", "Implements centralized tracking and registries: unified logging of parameters, code commits, datasets, metrics, and artifacts via MLflow, W&B, or Comet ML.", "Automates standardized evaluation pipelines: CI/CD evaluation jobs comparing candidate models against golden benchmark datasets, generating automated comparative leaderboards, drift metrics, and model cards."], "supporting_evidence": ["Details shared feature stores (Feast) preventing train-serve skew and speeding up feature exploration.", "Discusses budget alerts, auto-terminating idle GPU instances, and Spot instance management to control experiment cloud costs.", "Implementation examples and details: (Kubeflow) (Ray, Slurm)"], "negative_evidence": ["Forces data scientists to submit manual tickets to DevOps for every script execution or library installation.", "Leaves experiment results undocumented in individual local laptops with no centralized tracking."], "partial_credit": ["Mentions setting up MLflow and giving data scientists AWS EC2 GPU instances, without discussing self-service orchestration, automated evaluation benchmarks, or feature stores."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Cloud & Infrastructure as Code', 'MEDIUM', 'SPECIFIC', 180, 'How do you provision infrastructure (IaC, environments), and what tools do you use?', '{"required_evidence": ["Defines Infrastructure as Code principles: declarative configuration, version control in Git, state management, and automated continuous deployment pipelines.", "Identifies specific tools and their trade-offs .", "Explains multi-environment isolation strategies: managing dev, staging, and production environments using workspaces, directory structures, parameter files, and isolated VPCs/cloud accounts."], "supporting_evidence": ["Discusses remote state locking (e.g., S3 + DynamoDB lock table for Terraform) and automated drift detection.", "Mentions policy-as-code tools (e.g., Checkov, tfsec, OPA) integrated into pull requests to enforce security policies.", "Implementation examples and details: (IaC)", "Implementation examples and details: (e.g., Terraform / OpenTofu for multi-cloud infrastructure orchestration, AWS CDK / Pulumi for programmatic development, Ansible for configuration management, Helm for Kubernetes manifests)"], "negative_evidence": ["Advocates for manually clicking through cloud web consoles (ClickOps) to provision production enterprise infrastructure.", "Stores Terraform state files locally or checks sensitive state files into public Git repositories."], "partial_credit": ["Mentions using Terraform or CloudFormation to write code for EC2 and S3, but lacks details on state management, multi-environment isolation, or CI/CD automation."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'On-Premises & Open-Source AI Infrastructure', 'MEDIUM', 'SPECIFIC', 180, 'If a client needs to host this locally in an isolated data center using open-source tools, what would you use?', '{"required_evidence": ["Designs a fully air-gapped, on-premises orchestration layer: bare-metal Kubernetes with self-hosted private container registries and Git/CI .", "Selects self-hosted open-source model serving and AI frameworks: vLLM, Ollama, or LocalAI for LLM serving with open-weights models; Hugging Face TEI for embeddings; Milvus, Qdrant, or pgvector for vector search.", "Provides local supporting infrastructure: PostgreSQL, MinIO, Redis, RabbitMQ/Kafka, and Prometheus/Grafana for monitoring, without requiring internet connectivity."], "supporting_evidence": ["Discusses offline model weight transfers, checksum validation, air-gapped package mirrors (devpi, Nexus), and GPU driver / NVIDIA Container Toolkit installations.", "Mentions self-hosted observability tools such as Langfuse (self-hosted) or Jaeger.", "Implementation examples and details: (k3s, RKE2, OpenShift) (Harbor) (GitLab, Gitea)", "Implementation examples and details: (Llama 3, Mistral, Qwen)"], "negative_evidence": ["Relies on external SaaS APIs (OpenAI, Anthropic, Pinecone, AWS services) in an air-gapped isolated data center design.", "Fails to consider model weight storage, container registry mirroring, or lack of internet access for dependencies."], "partial_credit": ["Suggests running Ollama and Docker on a local server, but overlooks vector storage, air-gapped dependency management, networking, and enterprise scaling."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Observability & SRE', 'HARD', 'SPECIFIC', 240, 'How do you design AI infrastructure for alerts, logs and proactive troubleshooting?', '{"required_evidence": ["Architects the three pillars of observability tailored for AI: structured logging with correlation IDs across distributed agents, distributed tracing, and metrics collection .", "Defines AI-specific operational metrics: time-to-first-token, tokens-per-second, GPU utilization/VRAM, context length distributions, cache hit rates, cost per query, and model error rates.", "Configures proactive alerting rules and anomaly detection: SLO/SLA-based alerts via Alertmanager/PagerDuty for latency spikes, token budget burns, elevated hallucination/guardrail violation rates, and retrieval drift."], "supporting_evidence": ["Discusses log sanitization to scrub PII from prompts and completions before forwarding to centralized log storage (Elasticsearch/Loki).", "Mentions synthetic probing/canary queries running continuously to detect model degradation before end-users notice.", "Implementation examples and details: (OpenTelemetry, Langfuse, OpenLLMetry) (Prometheus)", "Implementation examples and details: (TTFT)"], "negative_evidence": ["Relies solely on basic server CPU/RAM metrics without monitoring LLM-specific latencies, token consumption, or error codes.", "Assumes looking at console stdout logs during an active outage is sufficient for proactive enterprise troubleshooting."], "partial_credit": ["Mentions setting up Grafana dashboards and sending Slack alerts when API calls fail or latency is high, but misses AI-specific metrics, distributed tracing, and proactive anomaly detection."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How do you use caching or fallback responses to improve robustness?', '{"required_evidence": ["Differentiates caching strategies: exact-match caching vs semantic caching with configurable similarity thresholds.", "Designs multi-tier fallback hierarchies: primary model -> cheaper/faster model -> cached response -> deterministic rule-based output -> graceful degradation / canned user-friendly error message.", "Implements circuit breakers and retry policies to prevent overwhelming failing upstream model providers."], "supporting_evidence": ["Discusses cache invalidation challenges (TTL management, user-personalized context breaking semantic similarity).", "Mentions streaming fallback handling when a streaming token stream terminates prematurely.", "Implementation examples and details: (hash of prompt/payload in Redis/Memcached) (vector embedding similarity via GPTCache or Redis)", "Implementation examples and details: (exponential backoff with jitter)"], "negative_evidence": ["Applies semantic caching blindly without considering that slight prompt differences can demand completely different factual outputs.", "Fails to define any fallback mechanism, allowing uncaught upstream 5xx errors to crash the user application."], "partial_credit": ["Mentions putting Redis in front of the API to store answers and showing a generic error message when the LLM fails, without discussing semantic caching, circuit breakers, or tiered model fallbacks."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'EASY', 'SPECIFIC', 180, 'Where and how do you manage application constants and configuration values?', '{"required_evidence": ["Applies Twelve-Factor App methodology: strict separation of config from code, injecting environment variables for environment-specific configurations.", "Categorizes configuration types: non-sensitive application constants, environment configs, and sensitive secrets .", "Implements runtime config validation and typed loading to fail fast at startup if required variables are missing or malformed."], "supporting_evidence": ["Discusses dynamic configuration services (e.g., LaunchDarkly, Consul, AWS AppConfig) allowing feature flag and config updates without redeploying code.", "Mentions CI/CD secrets masking and Git pre-commit hooks (git-secrets, TruffleHog) preventing secret commits.", "Implementation examples and details: (committed in code/constants files) (.env, config maps) (managed via secret managers like AWS Secrets Manager, HashiCorp Vault)", "Implementation examples and details: (e.g., Pydantic BaseSettings, Zod)"], "negative_evidence": ["Hardcodes database passwords, API keys, or environment URLs directly inside source code repositories.", "Commits production .env files with sensitive production secrets into public or shared Git repositories."], "partial_credit": ["Explains using .env files and os.environ to get variables, without discussing secret managers, typed schema validation, or dynamic configuration."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Data Engineering & Pipelines', 'EASY', 'SPECIFIC', 180, 'What dimensions of a data ecosystem do you know (ingestion, storage, processing, governance, quality, serving)?', '{"required_evidence": ["Systematically defines the six core dimensions: Ingestion, Storage, and Processing .", "Defines Governance, Quality, and Serving .", "Explains how these dimensions interconnect to provide an end-to-end reliable data lifecycle from raw events to analytical and AI consumption."], "supporting_evidence": ["Discusses FinOps / cost optimization and data observability as cross-cutting concerns across all dimensions.", "Provides real-world toolchain examples mapping across each dimension.", "Implementation examples and details: (batch vs streaming: Kafka, Flink, Airbyte) (data lakes, lakehouses, warehouses: S3, Iceberg, Snowflake) (compute engines: Spark, dbt, Flink)", "Implementation examples and details: (metadata, lineage, cataloging, compliance: DataHub, Apache Atlas) (validation, testing, drift detection: Great Expectations, Monte Carlo) (APIs, BI dashboards, vector search, feature stores)"], "negative_evidence": ["Confuses data storage with data processing (e.g., claiming S3 is an analytics compute engine).", "Omits data governance and quality, treating data ecosystems as purely raw ETL storage."], "partial_credit": ["Lists several tools and describes storing and querying data, but omits governance, quality validation, or serving layers."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 180, 'How do you design event-driven ingestion with automatic updates when documents are added?', '{"required_evidence": ["Architects event notifications: cloud object storage triggers emitting event payloads on ObjectCreated events.", "Implements decoupled event messaging: routing storage events into messaging queues / brokers to buffer spikes and ensure reliable delivery.", "Designs asynchronous worker processing: serverless functions or container workers consuming events, extracting text/embeddings, updating vector/relational databases, and handling idempotency."], "supporting_evidence": ["Addresses idempotency and deduplication using document content hashes (e.g., SHA-256) to prevent redundant re-indexing of duplicate events.", "Mentions Dead Letter Queues (DLQ) and retry policies for unparseable or corrupted documents.", "Implementation examples and details: (e.g., S3 Event Notifications, GCS Notifications)", "Implementation examples and details: (AWS SQS/SNS, EventBridge, Kafka)"], "negative_evidence": ["Suggests setting up an infinite polling loop that scans entire S3 buckets every 5 seconds to detect new files.", "Processes long-running heavy document parsing synchronously inside the event emission webhook handler, causing timeouts and dropped events."], "partial_credit": ["Mentions using S3 triggers and AWS Lambda to process files when uploaded, but lacks details on message queues, DLQs, or idempotency."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Observability & SRE', 'MEDIUM', 'SPECIFIC', 180, 'If you scale a workflow with multi-threading or horizontally, how do you track thread IDs and implement logging?', '{"required_evidence": ["Explains execution context propagation: using thread-local storage, Java ThreadLocal) or async context propagation to carry thread IDs and correlation/trace IDs.", "Implements structured logging: outputting logs in machine-readable JSON format containing timestamp, log level, thread ID/name, process ID, correlation ID, and tenant/user identifiers.", "Connects multi-threading to horizontal scaling: injecting unique distributed trace IDs at network entry points and propagating headers across HTTP/gRPC boundaries to a centralized logging system ."], "supporting_evidence": ["Discusses configuring logging formatters / MDC (Mapped Diagnostic Context) so thread and trace IDs are appended automatically without manual logging arguments.", "Mentions the risks of thread-local state leaks in thread pools if context is not cleared on return.", "Implementation examples and details: (e.g., Python threading.local() (e.g., Node.js AsyncLocalStorage, Python contextvars)", "Implementation examples and details: (trace_id, span_id)"], "negative_evidence": ["Suggests manually passing thread ID variables through every single internal function call as a parameter.", "Relies on unstructured plaintext console logging (print statements) for distributed enterprise debugging."], "partial_credit": ["Mentions logging thread IDs using Python logging formatters and passing a request ID across servers, without explaining async context vars or distributed trace context propagation."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Web Development & Debugging', 'EASY', 'SPECIFIC', 180, 'How do you troubleshoot a web app using the browser and network tools?', '{"required_evidence": ["Utilizes the Network panel: analyzing HTTP request/response headers, status codes, payload bodies, timing waterfalls, and inspecting CORS preflight failures.", "Utilizes Console and Sources/Debugger: inspecting client-side JS runtime exceptions, setting breakpoints, stepping through call stacks, inspecting variable scopes, and utilizing source maps for minified code.", "Inspects Application/Storage and Performance/Memory panels: checking cookies, localStorage, session tokens, indexedDB, diagnosing memory leaks via heap snapshots, and analyzing render bottlenecks/Lighthouse metrics."], "supporting_evidence": ["Mentions network throttling (simulating slow 3G) and device mode emulation to debug mobile-specific client issues.", "Discusses preserving network logs across page navigations (''Preserve log'') and disabling browser cache during debugging.", "Implementation examples and details: (4xx/5xx) (DNS lookup, TLS handshake, TTFB, download) (OPTIONS)"], "negative_evidence": ["Relies solely on adding console.log() statements and refreshing the page repeatedly without using breakpoints or network inspection tools.", "Cannot interpret HTTP status codes or Network panel timing waterfalls to isolate backend vs frontend latency."], "partial_credit": ["Mentions opening DevTools, checking the console for red errors, and looking at failed API calls in the network tab, without deep debugging (breakpoints, timing waterfalls, storage inspection)."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Multi-Cloud Architecture & Portability', 'HARD', 'SPECIFIC', 240, 'How would you design a system to be vendor-agnostic across AWS, GCP and Azure, including when clients are on different platforms?', '{"required_evidence": ["Applies Hexagonal / Clean Architecture: encapsulates cloud-specific SDKs behind provider-agnostic domain interfaces/adapters .", "Standardizes on cloud-neutral infrastructure: containerization with Docker and Kubernetes, deploying via standard Helm charts and Terraform/OpenTofu for infrastructure provisioning.", "Standardizes messaging, databases, and state stores: uses portable open-source or managed engines rather than proprietary cloud-only lock-in services where portability is paramount.", "Decouples authentication & secrets: adopts OpenID Connect,, and tools like HashiCorp Vault or external identity providers rather than hardcoded provider IAM."], "supporting_evidence": ["Considers trade-offs: least-common-denominator problem vs platform optimization, increased engineering complexity, and data egress costs.", "Mentions multi-cloud networking via service meshes (Istio) or VPN/interconnects.", "Implementation examples and details: (e.g., storage interface for S3/GCS/Blob, inference interface for Bedrock/Vertex/Azure OpenAI using abstraction layers like LiteLLM or LangChain providers)", "Implementation examples and details: (EKS/GKE/AKS)"], "negative_evidence": ["Advocates deeply embedding proprietary SDKs (boto3) throughout core business logic and claims rewriting will be trivial.", "Ignores the operational and cognitive cost of maintaining multi-cloud compatibility."], "partial_credit": ["Mentions Docker and Kubernetes as solutions, but does not address data stores, GenAI API abstractions, or multi-tenant cross-cloud identity/secrets."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Enterprise Integration & Security', 'MEDIUM', 'SPECIFIC', 180, 'How would you integrate a chatbot with a planning tool like Workday Adaptive Planning and handle permission-based access?', '{"required_evidence": ["Integrates with Workday Adaptive Planning via its REST/SOAP APIs or data export/import endpoints", "Implements User-Delegated Authentication rather than a shared service account with superuser permissions, ensuring the chatbot can only access records the logged-in user is authorized to see.", "Enforces permission-aware RAG / retrieval: queries and vector search results are filtered at query time using access control lists matching Workday role-based access control .", "Incorporates strict output sanitization and prompt injection defenses to prevent leaking unauthorized financial forecasts or executive compensation data."], "supporting_evidence": ["Discusses token refresh lifecycles, caching permission boundaries with appropriate TTLs, and audit logging of all generated prompts and retrieved planning sheets.", "Explains structured function calling where the bot generates API payloads that pass through an authorization middleware before execution against Workday.", "Numeric heuristics: utilizing OAuth 2.0 / SAML bearer assertion to maintain user identity context.", "Implementation examples and details: (on-behalf-of flow)"], "negative_evidence": ["Suggests using a single global admin API key for the chatbot and filtering data in the LLM prompt via instructions (''please only show data if user is an executive'').", "Indexes all sensitive enterprise planning data into an open, unfiltered vector database accessible to any querying user."], "partial_credit": ["Knows how to call Workday APIs and generate chatbot responses, but relies on coarse service accounts or post-generation LLM filtering rather than identity propagation."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Document AI & Legacy Automation', 'MEDIUM', 'SPECIFIC', 180, 'How would you build AI systems that automate paperwork-heavy, legacy-system and data-entry workflows (banking, credit unions)?', '{"required_evidence": ["Outlines an end-to-end Intelligent Document Processing pipeline: document classification, OCR/vision models, layout analysis, and entity extraction into validated schemas .", "Implements automated data validation with deterministic rules: cross-field reconciliation, checksum checks, and confidence scoring.", "Designs Human-in-the-Loop exception routing: documents with low OCR confidence, extraction ambiguities, or validation failures are flagged in a reviewer queue.", "Connects to legacy core banking platforms via secure RPA, batch SFTP/mainframe files, or API adapters with strict idempotency and audit trails."], "supporting_evidence": ["Addresses PII masking/redaction (e.g., Presidio) before processing, and GLBA/SOC2/PCI-DSS compliance.", "Mentions multimodal LLMs (e.g., frontier model, Claude Sonnet) with structured output / JSON schema mode for extracting unstructured handwritten or tabular forms.", "Implementation examples and details: (IDP) (e.g., AWS Textract, Azure Document Intelligence) (e.g., Pydantic)", "Implementation examples and details: (e.g., paystub gross income matches W-2, sum of invoice items matches total)"], "negative_evidence": ["Advocates blindly feeding raw customer tax returns/bank statements to an ungrounded LLM and directly executing financial transactions without schema validation or human review.", "Ignores image quality issues (skew, blur, low DPI, mobile scans) and assumes perfect text inputs."], "partial_credit": ["Mentions OCR and LLMs for parsing forms, but fails to address validation rules, human exception queues, or integration into legacy banking cores."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Workflow Automation & Strategy', 'MEDIUM', 'SPECIFIC', 180, 'How do you identify workflows suitable for automation, and when do you choose deterministic automation over AI?', '{"required_evidence": ["Evaluation criteria for automation candidates: high volume, repetitive, standardized business rules, measurable ROI, well-defined inputs/outputs, and quantifiable error tolerance.", "When to choose deterministic automation : fixed logic, binary outcomes, zero error tolerance, and lower operational/compute cost.", "When to choose AI/LLMs: unstructured or semi-structured data, semantic understanding, intent classification, summarization, and fuzzy matching where rules are too complex to hardcode."], "supporting_evidence": ["Describes hybrid architectures: deterministic outer loop (state machine, input validation, execution) wrapping AI inner nodes (extraction, reasoning) with deterministic validation guards.", "Mentions calculating total cost of ownership (TCO) including LLM token costs, latency SLA differences, and maintenance overhead.", "Implementation examples and details: (code, regex, RPA, workflow engines) (financial calculations, compliance checks, data transfers between structured APIs)", "Implementation examples and details: (emails, PDFs, conversational transcripts)"], "negative_evidence": ["Believes AI should replace all deterministic logic or uses LLMs for basic arithmetic, string matching, or relational database joins.", "Claims deterministic automation is obsolete now that LLMs exist."], "partial_credit": ["Understands that deterministic is rule-based and AI is probabilistic, but cannot provide concrete criteria or decision frameworks for enterprise workflow selection."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Platform Engineering & Multi-Tenancy', 'HARD', 'SPECIFIC', 240, 'How do you design a reusable framework where multiple teams upload their data and configure their own AI assistants (modular, reusable AI libraries)?', '{"required_evidence": ["Multi-tenant architecture & data isolation: tenant-specific namespaces or logical partitions in vector databases, tenant-keyed object storage, and row-level security in metadata stores.", "Declarative configuration schema: configuration-as-code defining agent persona, system prompts, retrieval parameters, and allowed tool/API registries.", "Modular core execution engine: plugin-based architecture separating ingestion, orchestration, and model adapters .", "Governance and guardrails: centralized rate limiting, per-team token quota tracking, cost attribution/chargeback, and content moderation/safety filters."], "supporting_evidence": ["Mentions dynamic runtime tool loading via MCP (Model Context Protocol) or OpenAPI specifications.", "Discusses evaluation harnesses (e.g., Ragas, promptfoo) allowing tenant teams to benchmark their assistant configurations before deployment.", "Implementation examples and details: (S3 prefixes/buckets) (RLS)", "Implementation examples and details: (YAML/JSON) (chunk size, top-k, similarity thresholds)"], "negative_evidence": ["Proposes sharing a single global prompt and unpartitioned vector index where all tenant data is mixed without isolation.", "Requires redeploying and recompiling the core application codebase every time a team updates a prompt or adds a document."], "partial_credit": ["Mentions multi-tenancy and configuration files, but misses runtime isolation, tool authorization, or platform-level cost/quota governance."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI Project Lifecycle', 'MEDIUM', 'SPECIFIC', 180, 'What do you consider in the POC phase of a generative AI project?', '{"required_evidence": ["Clear problem definition and feasibility: defining a tightly scoped use case with measurable business KPIs rather than open-ended exploration.", "Golden evaluation dataset & baseline: creating an annotated benchmark set of representative test cases and edge cases with defined quantitative evaluation metrics .", "Technical feasibility & constraints: evaluating latency, token cost, model context limits, API rate limits, and enterprise data availability/quality.", "Production path alignment: assessing security, compliance, and integration feasibility early so the POC doesn''t result in a throwaway demo."], "supporting_evidence": ["Distinguishes between prompt engineering, RAG, and fine-tuning, prioritizing the simplest solution first during POC.", "Emphasizes establishing human evaluation rubrics alongside automated LLM-as-a-judge evaluations.", "Implementation examples and details: (e.g., time saved, deflection rate, accuracy)", "Implementation examples and details: (e.g., precision, recall, faithfulness, semantic similarity)"], "negative_evidence": ["Judges POC success solely by anecdotal ''vibes'' or cherry-picked demos on 2-3 favorable examples without a systematic evaluation dataset.", "Immediately jumps to expensive pre-training or fine-tuning models before validating basic prompt engineering or retrieval baselines."], "partial_credit": ["Mentions testing prompts and checking accuracy, but lacks structured evaluation methodologies, cost/latency projections, or data governance considerations."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Azure AI Ecosystem', 'MEDIUM', 'SPECIFIC', 180, 'Have you used Copilot Studio, Azure AI Foundry and Power Platform, and how would you use them in a project?', '{"required_evidence": ["Defines roles of each platform: Copilot Studio, Azure AI Foundry, and Power Platform .", "Architecture for enterprise projects: Azure AI Foundry serves as the backend hub", "Power Automate integration: uses connectors to trigger external systems or execute business logic triggered by Copilot Studio user requests."], "supporting_evidence": ["Discusses Application Insights integration for tracing, Azure AI Search for enterprise RAG, and Content Safety filters in Azure AI Foundry.", "Mentions environment lifecycle management (ALM) using Power Platform Solutions and Azure DevOps/GitHub Actions.", "Implementation examples and details: (low-code conversational AI builder for creating custom copilots, dialogs, generative answers, and plugin actions within Microsoft 365 / Teams) (pro-code developer platform for model evaluation, fine-tuning, prompt engineering, RAG, and Azure OpenAI and model catalog) (Power Automate, Power Apps for deterministic workflow orchestration and enterprise system connectors)", "Implementation examples and details: (custom models, vector indexes, evaluation pipelines, safety guardrails)"], "negative_evidence": ["Confuses Copilot Studio (conversational agent builder) with GitHub Copilot (code autocomplete), or thinks Azure AI Foundry is a low-code UI builder.", "Suggests building heavy custom ML training and data pipelines directly inside Copilot Studio dialogs."], "partial_credit": ["Recognizes Microsoft/Azure tools and knows Copilot is a chatbot and Power Platform does automation, but cannot detail how they interoperate in an enterprise architecture."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Systems Programming & C/C++', 'MEDIUM', 'SPECIFIC', 180, 'How would you adapt to C/C++ (pointers, manual memory management) if required?', '{"required_evidence": ["Memory management fundamentals: Contrasts stack vs heap allocation; understands raw pointer mechanics, dereferencing, pointer arithmetic, and avoiding memory corruption through explicit malloc/free in C.", "Modern C++ idioms : Emphasizes Resource Acquisition Is Initialization; relies on smart pointers to automate resource deallocation and eliminate manual delete.", "Tooling and memory safety verification: Uses debugging and sanitization tools such as Valgrind, AddressSanitizer, LeakSanitizer, and static analyzers to detect memory leaks and invalid accesses."], "supporting_evidence": ["Discusses move semantics (std::move, rvalue references) to avoid expensive deep copies while maintaining strict ownership transfer.", "Mentions cache locality, memory alignment, and cache-friendly data structures (e.g., std::vector over linked lists).", "Implementation examples and details: (dangling pointers, double free, buffer overflows, memory leaks)", "Implementation examples and details: (RAII & Smart Pointers) (RAII) (std::unique_ptr for exclusive ownership, std::shared_ptr / std::weak_ptr for shared ownership)"], "negative_evidence": ["Advocates widespread use of raw owning pointers with manual new/delete in modern C++ codebases.", "Shows no awareness of RAII or memory sanitizers, assuming manual vigilance is sufficient for memory safety."], "partial_credit": ["Understands what pointers and malloc/free are, but cannot speak to modern C++ memory management (smart pointers, RAII) or diagnostic tooling (Valgrind/ASan)."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Model Selection & Deployment Strategy', 'MEDIUM', 'SPECIFIC', 180, 'How do you decide between self-hosted or open-source models and cloud-hosted models, and what trade-offs do you consider?', '{"required_evidence": ["Latency and throughput guarantees: self-hosted models on dedicated GPUs provide predictable latency, custom batching, and no rate-limit throttling; cloud-hosted APIs suffer from shared multi-tenant latency jitter and TPM/RPM rate limits.", "Data privacy, security, and IP: self-hosted ensures zero data leaves VPC/on-prem boundary; cloud-hosted models require strict BAA/DPA agreements and verification of zero-data-retention.", "Cost at scale : cloud APIs are cheaper for low-to-moderate or bursty query volumes; self-hosting dedicated GPU instances requires high, steady utilization to justify fixed infrastructure and MLOps maintenance costs.", "Model quality and maintenance: proprietary cloud models lead frontier reasoning capabilities out-of-the-box; open-source models require quantization, fine-tuning, and infrastructure patching."], "supporting_evidence": ["Discusses cold-start times, GPU availability/shortages in cloud providers, and vLLM PagedAttention memory optimization.", "Mentions hybrid routing architectures where simple tasks route to self-hosted smaller models and complex reasoning cascades to frontier cloud APIs.", "Implementation examples and details: (vLLM, TGI, Triton) (OpenAI, Anthropic, Bedrock)", "Implementation examples and details: (crucial for healthcare, defense, banking)"], "negative_evidence": ["Assumes self-hosting an open-source model like Llama 3 70B on AWS is trivial and costs less than API calls even for 100 requests per day.", "Claims cloud LLM APIs store and publicly train on all enterprise customer prompt data by default."], "partial_credit": ["Notes that cloud is easier and self-hosting is more private, but lacks quantitative metrics on GPU sizing, throughput, latency, or TCO."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 180, 'How do you use Bedrock, EKS, ECS, SageMaker, S3, DynamoDB, RDS, Textract, Lambda, Cognito, API Gateway and CloudWatch to build and monitor scalable GenAI systems?', '{"required_evidence": ["triggered by Lambda or orchestrated on ECS/EKS microservices, storing structured metadata and vectors in RDS or DynamoDB for conversational history.", "Delineates model inference layers: uses Amazon Bedrock for managed foundation model APIs and Amazon SageMaker for fine-tuning or hosting custom models, integrated with LangChain/orchestrators on EKS/ECS.", "Explains API access and security: Amazon Cognito handles authentication and RBAC, integrated with API Gateway for rate limiting, throttling, and routing to compute layers.", "Details observability and monitoring: CloudWatch captures logs, traces, container insights, custom GenAI metrics, and configures anomaly alarms."], "supporting_evidence": ["Discusses cost optimization techniques such as caching responses in DynamoDB/DAX and using S3 lifecycle rules for raw documents.", "Mentions Bedrock Guardrails for PII redaction and content safety integrated directly at the API Gateway/orchestration boundary.", "Implementation examples and details: (pgvector)", "Numeric heuristics: Structures the ingest/processing pipeline: Textract extracts text from documents stored in S3"], "negative_evidence": ["Lists all services blindly without explaining how data and requests flow between the ingestion, inference, storage, and monitoring tiers.", "Confuses the distinct roles of Bedrock (managed FM APIs) and SageMaker (custom training/hosting), or DynamoDB (NoSQL key-value) and RDS (relational/vector)."], "partial_credit": ["Explains 4-5 of the services well (e.g., Bedrock, S3, Lambda, API Gateway) but omits orchestration on EKS/ECS, vector/session storage, or CloudWatch monitoring."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Serverless Architecture & AWS Lambda', 'MEDIUM', 'SPECIFIC', 180, 'How do you use AWS Lambda for event-driven processing, and how do you handle cold starts?', '{"required_evidence": ["Event-driven processing mechanisms: synchronous invocations, asynchronous invocations, and poll-based stream/queue mappings .", "Understanding cold starts: explains the cold start lifecycle .", "Cold start mitigation strategies: Provisioned Concurrency, optimizing package size, using fast-boot runtimes, and keeping initialization logic lean."], "supporting_evidence": ["Mentions AWS Lambda SnapStart (for Java) taking MicroVM snapshots of initialized states, and lazy-loading heavy SDKs/dependencies inside the handler only when needed.", "Discusses database connection pooling challenges (Lambda exhaustion of connection pools) and solutions like AWS RDS Proxy.", "Implementation examples and details: (API Gateway, ALB) (S3 events, SNS, EventBridge with built-in retries and Dead Letter Queues - DLQs) (SQS, Kinesis, DynamoDB Streams with batching)", "Implementation examples and details: (microVM initialization via Firecracker, runtime bootstrap, downloading code/layers, executing initialization code outside handler)"], "negative_evidence": ["Believes scheduled CloudWatch cron ''pings'' are a complete substitute for Provisioned Concurrency under concurrent traffic spikes.", "Claims Lambda functions maintain persistent in-memory global state across arbitrary concurrent invocations."], "partial_credit": ["Knows that Lambda is triggered by S3/SQS and that cold starts cause latency on first request, but cannot explain Provisioned Concurrency or package optimization."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Scalability & Capacity Planning', 'MEDIUM', 'SPECIFIC', 180, 'How do you plan for and scale to a target number of concurrent users on AWS?', '{"required_evidence": ["Traffic profiling & capacity calculation: calculates requests per second, average latency, throughput, and compute/memory footprints from user concurrency targets using Little''s Law .", "Decoupling and horizontal scaling: places stateless application tiers in Auto Scaling Groups or ECS/EKS with HPA behind an Application Load Balancer .", "Database and caching tier scaling: offloads read traffic with ElastiCache and CDN; scales databases using read replicas, DynamoDB on-demand / auto-scaling, or Aurora Serverless with connection pooling .", "Load testing and bottleneck analysis: conducts simulated load and stress testing using tools like Locust,, or Distributed Load Testing on AWS to identify failure points before hitting target concurrency."], "supporting_evidence": ["Discusses AWS service quotas and requesting increases in advance (e.g., Lambda concurrency, EIPs, EC2 vCPU quotas).", "Mentions graceful degradation: circuit breakers, rate limiting (WAF), and SQS buffering to smooth bursty spikes.", "Implementation examples and details: (RPS) (L = lambda * W)", "Implementation examples and details: (EC2) (Horizontal Pod Autoscaler) (ALB)"], "negative_evidence": ["Assumes vertical scaling (upgrading to a larger EC2/database instance) is sufficient for arbitrarily large concurrency targets.", "Ignores database connection limits and assumes backend services scale infinitely without caching or connection management."], "partial_credit": ["Mentions Auto Scaling groups and load balancers, but omits load testing, database bottleneck management, or concrete capacity calculation methodology."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'How do you secure sensitive documents on AWS (encryption, KMS, IAM, access policies)?', '{"required_evidence": ["encrypts at rest using AWS KMS Customer Managed Keys with automated key rotation .", "", "KMS Key Policies: enforces defense-in-depth by managing KMS key policies separately from IAM policies", "and continuous auditing via AWS CloudTrail data events and Amazon Macie ."], "supporting_evidence": ["Explains envelope encryption mechanics: data encryption keys (DEKs) generated by KMS encrypting document files locally, with KMS storing only the encrypted DEK.", "Mentions S3 Block Public Access at the account and bucket levels as an essential baseline.", "Implementation examples and details: (aws:SecureTransport: true) (CMK) (SSE-KMS or DSSE-KMS)", "Numeric heuristics: Encryption at rest and in transit: enforces TLS 1.3 in transit via S3 bucket policies"], "negative_evidence": ["Relies solely on basic S3-managed keys (SSE-S3) without key policy governance, or advocates granting wildcard s3:* permissions across the entire account.", "Assumes IAM policies alone are sufficient without configuring KMS key policies or bucket-level encryption enforcement."], "partial_credit": ["Mentions using KMS and S3 bucket policies and setting up IAM roles, but cannot explain envelope encryption, KMS key policies, or transport enforcement."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'How do you securely manage AWS credentials in production, including Secrets Manager, IAM roles, SSM parameters and key rotation?', '{"required_evidence": ["ECS task roles, or Lambda execution roles .", "AWS Secrets Manager vs SSM Parameter Store: uses SSM Parameter Store for cost-effective configuration and basic encrypted secrets; uses Secrets Manager for high-value secrets requiring automated, built-in rotation .", "Automated rotation lifecycle: sets up automated rotation schedules with zero application downtime .", "Access control and auditability: restricts secret access using IAM policies and KMS key permissions; logs every credential retrieval and secret access in AWS CloudWatch and CloudTrail."], "supporting_evidence": ["Explains in-memory caching of secrets on the application side (with appropriate TTL) to reduce API latency and avoid throttling/cost from repeated Secrets Manager requests.", "Mentions Workload Identity Federation / OIDC for secure CI/CD pipelines (e.g., GitHub Actions deploying to AWS without static credentials).", "Implementation examples and details: (AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY) (leveraging AWS STS for short-lived credentials)", "Numeric heuristics: IAM Roles and temporary credentials: eliminates hardcoded static long-term access keys  by using IAM Roles attached to EC2 instance profiles"], "negative_evidence": ["Advocates committing .env files with static AWS keys to Git repositories or hardcoding credentials in Dockerfiles.", "Suggests rotating database passwords manually by shutting down production applications."], "partial_credit": ["Knows to use Secrets Manager and IAM roles instead of hardcoded keys, but cannot explain the rotation mechanism (AWSCURRENT/AWSPREVIOUS) or the difference between SSM Parameter Store and Secrets Manager."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Concurrency & Parallelism', 'MEDIUM', 'SPECIFIC', 180, 'How do you choose between threads, asyncio and multiprocessing for a service doing HTTP calls plus occasional heavy parsing?', '{"required_evidence": ["Characteristics of each concurrency model in Python: asyncio; threading; multiprocessing .", "Architecture for the hybrid workload: Use asyncio as the primary driver for high-volume network HTTP calls, and offload occasional heavy parsing to a ProcessPoolExecutor via loop.run_in_executor to avoid blocking the event loop."], "supporting_evidence": ["Discusses serialization overhead: pickling objects across process boundaries, and using shared memory (multiprocessing.shared_memory) or lightweight payloads.", "Mentions Python 3.12/3.13 free-threaded Python (PEP 703) and subinterpreters (PEP 684) as emerging alternatives to multiprocessing.", "Implementation examples and details: (single-threaded cooperative multitasking using an event loop; ideal for massive I/O concurrency like thousands of simultaneous HTTP calls with minimal memory overhead, but blocks the entire event loop if CPU-bound work is executed) (preemptive multitasking managed by the OS; good for blocking I/O bound calls, but constrained by the Global Interpreter Lock - GIL preventing true parallel CPU execution) (spawns separate OS processes with independent memory spaces and separate GILs; enables true multi-core CPU parallelism for heavy computational tasks like parsing, but incurs higher inter-process communication - IPC and memory overhead)", "Implementation examples and details: (e.g., with aiohttp / httpx) ()"], "negative_evidence": ["Proposes executing heavy CPU parsing directly in the main asyncio coroutine, which stalls the entire event loop and drops incoming HTTP connections.", "Claims Python threads achieve multi-core parallel CPU execution for pure Python parsing tasks despite the GIL."], "partial_credit": ["Understands that asyncio/threads are for I/O and multiprocessing is for CPU, but does not provide a concrete combined architecture (loop.run_in_executor with process pool) for the described hybrid workload."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Concurrency & Parallelism', 'MEDIUM', 'SPECIFIC', 180, 'How would you run four threads concurrently, terminate one when any finishes, and wait for the rest?', '{"required_evidence": ["Thread execution & termination reality: OS threads cannot be forcibly killed safely from the outside without risking resource leaks or corrupted locks; cooperative cancellation using a shared cancellation flag is required.", "uses a thread-safe completion queue or barrier/latch ).", ""], "supporting_evidence": ["Shows code implementation using Python''s concurrent.futures.ThreadPoolExecutor and concurrent.futures.wait(futures, return_when=FIRST_COMPLETED).", "Discusses handling cancellation within blocking I/O calls (e.g., closing sockets or setting timeouts so blocking calls wake up to check the flag).", "Implementation examples and details: (threading.Event, atomic boolean, or token)", "Implementation examples and details: (e.g., queue.Queue or concurrent.futures.wait(..., return_when=FIRST_COMPLETED)"], "negative_evidence": ["Proposes calling deprecated or dangerous methods like thread.stop() or pthread_cancel() without explaining lock corruption or resource leakage risks.", "Omits calling join() on the remaining threads, leaving zombie or unjoined threads."], "partial_credit": ["Suggests using threading.Event to signal termination, but fails to clearly articulate the mechanism for detecting when the first thread finishes or joining the rest."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Graph Orchestration & Concurrency', 'MEDIUM', 'SPECIFIC', 180, 'How do you invoke multiple instances of a graph, for example 100 threads at once?', '{"required_evidence": ["Graph immutability & thread-safe compilation: The graph structure is static and immutable; state is instantiated per execution run via a unique run/thread configuration .", "ensuring state persistence isolates tenant state using distinct thread_id keys to prevent collisions.", "Resource management & rate limiting: Implements concurrency throttling ) to avoid overwhelming external LLM provider rate limits or database connection pools."], "supporting_evidence": ["Discusses batch APIs (e.g., graph.abatch()) which natively optimize parallel graph dispatches with internal concurrency controls.", "Considers distributed execution via message queues (Celery/SQS) if 100 graph instances exceed single-machine memory or CPU limits.", "Implementation examples and details: (nodes, edges, compiled workflow definition, e.g., in LangGraph) (configurable={''thread_id'': ...})", "Implementation examples and details: () () (e.g., Postgres, Redis, or in-memory checkpointer)"], "negative_evidence": ["Recompiles the entire graph object 100 times inside each thread, causing excessive memory consumption and initialization latency.", "Shares a single mutable state dictionary across all 100 threads without thread-local isolation, causing race conditions and state corruption."], "partial_credit": ["Suggests looping over a list of threads or using ThreadPoolExecutor, but overlooks graph state isolation (thread_id), checkpointer concurrency, or downstream API rate limiting."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Algorithms & Data Structures', 'MEDIUM', 'SPECIFIC', 180, 'Use a stack to build the smallest number from an "I/D" pattern, including edge cases and when to push and pop.', '{"required_evidence": ["at each step i,, pops all elements from the stack and appends them to the result string.", "Why the stack works: Pushing sequentially guarantees the smallest available digits are used; popping upon ''I'' maintains increasing order, while delaying the pop during consecutive ''D''s reverses the accumulated digits, naturally generating the strictly descending sequence required for decreases.", "Edge cases: Single-character patterns, all ''D''s, all ''I''s, and handling the final digit push and pop loop boundary at index n."], "supporting_evidence": ["Analyzes complexity: O(n) time complexity (each digit 1 to n+1 is pushed and popped exactly once) and O(n) auxiliary space for the stack.", "Mentions an alternative two-pointer / greedy reversal approach on an initially sorted array of digits.", "Implementation examples and details: (where n is length of pattern) (from 0 to n)", "Numeric heuristics: Conceptual algorithmic strategy: Iterates from 1 to n+1 pushes i+1 onto the stack. When reaching the end of the pattern or encountering ''I''"], "negative_evidence": ["Suggests backtracking or O(n!) brute force permutations of digits instead of the linear stack-based greedy solution.", "Fails to handle the final loop boundary (i == n), resulting in truncated output missing the last sequence of digits."], "partial_credit": ["Understands that ''D'' requires reversing digits and knows a stack reverses order, but cannot formulate the exact push-and-pop condition (pushing i+1, popping on ''I'' or end)."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Algorithms & Data Structures', 'MEDIUM', 'SPECIFIC', 180, 'Longest substring where each character appears at most twice: how do you use a sliding window, track character counts, and decide when to shrink or expand?', '{"required_evidence": ["Sliding window state tracking: Maintains two pointers defining the active window, and a frequency hash map or array tracking character counts in the current window.", "Expansion and condition check: Expands the window by advancing right, incrementing the count of s[right] in the frequency map.", "the window violates the constraint", "Result update: At each valid step, updates the maximum length: max_len = max."], "supporting_evidence": ["Complexity analysis: O(n) time complexity because both left and right traverse the string at most once; O(1) or O(k) auxiliary space where k is the alphabet size.", "Mentions edge cases: empty string, string where all characters are identical (''aaaa'' -> 2), string with all unique characters, and alternating characters.", "Implementation examples and details: (left and right) (e.g., size 128/256 for ASCII)", "Implementation examples and details: (left++)"], "negative_evidence": ["Proposes checking all O(n^2) or O(n^3) substrings with nested loops and separate frequency counters.", "Resets left back to 0 or right upon violation rather than advancing left monotonically."], "partial_credit": ["Explains sliding window and frequency map, but gets the shrinking condition wrong (e.g., shrinks only once instead of while count > 2) or fails to calculate length properly."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Algorithms & Data Structures', 'MEDIUM', 'SPECIFIC', 180, 'Can a string become a palindrome by removing at most two characters? Cover the two-pointer approach, mismatches, and test cases.', '{"required_evidence": ["increment left and decrement right.", "return false.", "maintaining an overall O time complexity and O = O call stack space.", "Edge and test cases: Already a palindrome,,, and impossible strings ."], "supporting_evidence": ["Generalizes to arbitrary K: for small fixed K, branching is O(2^K * n); for large K, dynamic programming (Longest Palindromic Subsequence) is preferred with n - LPS(s) <= 2 in O(n^2) time.", "Discusses early exit optimizations and string slicing memory overhead.", "Implementation examples and details: (s)", "Numeric heuristics: Two-pointer approach & branching recursion: Initialize pointers left = 0 right = len - 1. While s[left] == s[right]"], "negative_evidence": ["Greedily deletes one character without exploring both branches (e.g., always choosing to delete left), which fails on test cases where only deleting right yields a palindrome.", "Generates all O(n^2) pairs of deleted characters and tests each for palindromicity (O(n^3) time)."], "partial_credit": ["Solves the standard ''remove at most 1 character'' problem correctly, but fails to extend the recursion to handle 2 character deletions or manage the branching search space."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Algorithms & Data Structures', 'MEDIUM', 'SPECIFIC', 180, 'Find the duplicate in an array of n+1 integers in 1..n. Compare the set approach (time and space), slow/fast pointers, and why both start at the same index.', '{"required_evidence": ["Comparison of approaches: Hash Set / Boolean array runs in O time but requires O auxiliary space,; Slow/Fast Pointers treats array values as pointers, running in O time and O auxiliary space without mutating the input array.", "", "signifying two distinct indices point to the same value ."], "supporting_evidence": ["Also compares with binary search over the range [1, n]: count numbers <= mid; runs in O(n log n) time and O(1) space.", "Explains why starting inside the cycle or at arbitrary indices can fail to find the duplicate if there are disconnected components.", "Implementation examples and details: (n) (n) (1) (Floyd''s Cycle Finding) (i -> nums[i]) (n) (1)", "Numeric heuristics: violating the O space constraint of LeetCode 287"], "negative_evidence": ["Suggests sorting the array (O(n log n) time) or mutating array signs as the primary solution, ignoring the read-only constraint.", "Cannot explain why slow and fast pointers must start at index 0, or thinks any random index will always work."], "partial_credit": ["Compares the time/space trade-offs of the set vs Floyd''s algorithm, but cannot articulate why starting both at index 0 guarantees finding the cycle entrance."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 180, 'How does a stack simulate recursion in an in-order traversal iterator?', '{"required_evidence": ["Call stack simulation: Standard recursive in-order traversal implicitly relies on the system call stack; an explicit iterator simulates this by using an explicit stack to maintain the current path of unvisited parent nodes.", "Left-spine push operation: During initialization and after processing any right child, the iterator pushes the current node and repeatedly traverses all left children, pushing each onto the stack until reaching None.", "next pops the top node from the stack, and if that node has a right child, pushes the right child and all its subsequent left descendants onto the stack before returning node.val.", "Complexity analysis: Amortized O time per next call and O space complexity, where h is tree height."], "supporting_evidence": ["Contrasts with Morris traversal (threaded binary tree) which achieves O(1) auxiliary space by temporarily modifying tree pointers.", "Explains iterator statefulness: allows pausing, stepping, and lazy evaluation without traversing the entire tree upfront into a list.", "Implementation examples and details: (Left, Node, Right) (std::stack / list)", "Implementation examples and details: (curr = curr.left)"], "negative_evidence": ["Performs a complete recursive traversal in the constructor, storing all N elements in an array/list, violating the O(h) memory constraint.", "Claims each individual call to next() is strictly worst-case O(1) rather than amortized O(1)."], "partial_credit": ["Understands that a stack holds the left nodes, but struggles with the exact steps inside next() (popping and then traversing the right child''s left spine)."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Algorithms & Data Structures', 'MEDIUM', 'SPECIFIC', 180, 'In a rotated sorted array, how do you tell which half is sorted, and how does that move the pointers?', '{"required_evidence": ["the left half [low ... mid] is normally sorted; otherwise, the right half [mid ... high] is normally sorted.", "Pointer movement logic: If left half is sorted, check if target lies within the sorted range . If yes, search left; otherwise search right . If right half is sorted, check if target lies within the sorted range . If yes, search right; otherwise search left .", "Termination & complexity: Maintains O binary search time complexity and O space."], "supporting_evidence": ["Addresses the duplicate values edge case (LeetCode 81): when nums[low] == nums[mid] == nums[high], it is impossible to determine the sorted half, forcing pointer reduction (low++, high--) and degrading worst-case time to O(n).", "Explains prevention of integer overflow when calculating mid: low + (high - low) / 2.", "Implementation examples and details: (low + high) (or nums[high]) (nums[mid] < nums[low])", "Numeric heuristics: Identifying the sorted half: Compute mid =  // 2. Compare nums[mid] with nums[low] : If nums[low] <= nums[mid]"], "negative_evidence": ["Suggests finding the rotation pivot first via a separate linear scan (O(n)) before running binary search.", "Fails to verify whether the target falls within the bounds of the sorted half, moving pointers incorrectly."], "partial_credit": ["Knows that comparing nums[mid] to nums[low] identifies the sorted half, but makes off-by-one errors or mixes up the conditions for updating low and high."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Algorithms & Data Structures', 'EASY', 'SPECIFIC', 180, 'Find the shortest path in a unit-weight graph with BFS, using parent tracking.', '{"required_evidence": ["BFS for unit-weight shortest path: Breadth-First Search traverses level by level, ensuring the first time the destination node is dequeued/visited, it is reached via the minimum number of edges.", "Parent tracking data structure: Maintains a parent dictionary / array and a visited set / boolean array. When exploring neighbor v of current node u, if v is unvisited: mark visited, set parent[v] = u, and enqueue v.", "Path reconstruction: Once the destination node is reached, reconstruct the path by backtracking from destination to source using curr = parent[curr], storing nodes in a list, and reversing the list.", "Complexity: O time complexity and O auxiliary space for queue, visited set, and parent map."], "supporting_evidence": ["Explains why Dijkstra''s algorithm is unnecessary overhead (O((V+E) log V)) for unit-weight graphs compared to standard BFS (O(V+E)).", "Handles edge cases: source equals destination, destination unreachable (parent map traversal terminates or destination never visited), disconnected graphs.", "Implementation examples and details: (initialized with None or -1)", "Implementation examples and details: (V + E) (V)"], "negative_evidence": ["Proposes Depth-First Search (DFS) to find the shortest path in a general unweighted graph.", "Forgets to mark nodes as visited when enqueuing, leading to infinite loops in cyclic graphs or exponential redundant enqueuing."], "partial_credit": ["Explains BFS with a queue and visited set, but fails to implement or explain parent tracking for path reconstruction."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Algorithms & Data Structures', 'MEDIUM', 'SPECIFIC', 180, 'Find the top K most frequent elements, and how would you optimize it?', '{"required_evidence": ["Frequency counting baseline: Counts element frequencies using a hash map in O time.", "Min-Heap approach: Maintains a min-heap of size K storing pairs. For each element in the frequency map, pushes into the heap and pops if heap size exceeds K. Time complexity: O where m is unique elements; space complexity: O.", "accumulating the first K elements. Time complexity: O linear time; space complexity: O.", ""], "supporting_evidence": ["Contrasts trade-offs: Bucket sort guarantees strictly O(n) worst-case time but uses extra array memory; Quickselect achieves O(n) average time and O(1) extra space beyond unique elements, but degrades to O(n^2) worst-case without randomized pivot selection.", "Explains why a max-heap of all m elements is suboptimal (O(m + K log m) vs min-heap of size K).", "Implementation examples and details: (collections.Counter in Python or unordered_map in C++) (n)", "Implementation examples and details: (frequency, element) (n + m log K) (n + K)"], "negative_evidence": ["Suggests full sorting of the frequency map (O(m log m)) and claims it cannot be further optimized.", "Confuses finding top K frequent elements with finding the K-th largest element in an unsorted array."], "partial_credit": ["Explains the hash map plus min-heap approach of size K (O(n log K)), but cannot describe the O(n) Bucket Sort or Quickselect optimizations."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Algorithms & Parallel Computing', 'MEDIUM', 'SPECIFIC', 180, 'Compute factorials incrementally from a previous value. How would you parallelize it for very large inputs?', '{"required_evidence": ["Explain incremental factorial computation using recurrence n! = n * ! via memoization or iterative accumulation in O extra space and O time.", "Explain that naive recurrence is strictly sequential, so parallelization requires binary splitting / divide-and-conquer range multiplication: product of range [a, b] = range * range.", "Address arbitrary-precision integer arithmetic overhead, noting that balanced tree multiplication keeps operand bit-lengths balanced to optimize Karatsuba / FFT multiplication algorithms."], "supporting_evidence": ["Mention prime factorization approaches (e.g. Legendre''s formula) to compute powers of prime factors and multiply them using parallel tree reduction.", "Discuss worker pools (multiprocessing, fork-join, OpenMP) with work stealing to distribute sub-range multiplications across available CPU cores.", "Implementation examples and details: (n-1) (1) (n)", "Implementation examples and details: (a, m) (m+1, b)"], "negative_evidence": ["Suggests parallelizing naive iteration by simply putting a lock on a shared accumulator variable, resulting in complete thread contention and zero speedup.", "Claims dynamic programming or memoization alone parallelizes factorial computation without recognizing the serial dependency graph."], "partial_credit": ["Proposes range partitioning (dividing 1..N into chunks across threads) but misses the need for hierarchical tree reduction or arbitrary precision bit-length balancing."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Object-Oriented Design & Data Structures', 'EASY', 'SPECIFIC', 180, 'How do you compare and order cards to find the highest card?', '{"required_evidence": ["Define a card data structure with attributes for Rank and Suit, mapped to numerical or enum weights.", "Implement comparison logic that first compares rank values and uses suit values as a tiebreaker if required by the game rules.", "Explain finding the highest card in a collection in O time using a single linear scan tracking the maximum element, rather than sorting in O."], "supporting_evidence": ["Discuss handling contextual game rules, such as trump suits, Ace-high vs Ace-low, or wildcards where card ranking dynamically depends on game state.", "Mention total ordering guarantees and transitivity properties when overriding equality and comparison operators.", "Implementation examples and details: (e.g., 2-10, Jack, Queen, King, Ace) (e.g., Clubs, Diamonds, Hearts, Spades)", "Implementation examples and details: (e.g., overriding __lt__, implementing Comparable/Comparator)"], "negative_evidence": ["Proposes sorting the entire collection of N cards (O(N log N)) when only the single maximum card is requested.", "Hardcodes string comparisons for card ranks (e.g. comparing ''10'' vs ''2'' lexicographically where ''2'' > ''10'')."], "partial_credit": ["Explains rank and suit mapping and comparisons, but does not specify how tie-breaking works or how to find the maximum in O(N)."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 180, 'Compute reader scores from books and pages, and output the top five.', '{"required_evidence": ["Aggregate reader scores by grouping book/page reading logs per reader using a hash map / dictionary to accumulate total scores in O(N) time.", "Use a min-heap of fixed size k=5(or Quickselect) to find the top 5 readers in O = O(M) time where M is the number of distinct readers, avoiding an expensive full sort(O(M log M)).", "Properly handle edge cases: fewer than 5 readers, duplicate reader IDs, tie-breaking criteria for identical scores, and invalid/negative page counts."], "supporting_evidence": ["Demonstrate idiomatic usage in standard libraries, such as Python''s collections.defaultdict and heapq.nlargest.", "Discuss scaling considerations when input data exceeds memory, such as MapReduce / PySpark aggregation or SQL window functions (DENSE_RANK).", "Mentions specific implementation details or heuristics such as: M log 5."], "negative_evidence": ["Sorts the entire aggregated dataset of millions of readers using sort() (O(M log M)) without considering memory or heap-based selection.", "Fails to aggregate scores per reader before selecting top records, mistakenly ranking individual reading sessions."], "partial_credit": ["Correctly describes hash map aggregation and suggests sorting the entire list to take the first 5 elements."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'EASY', 'SPECIFIC', 180, 'Given a JSON list of events, compute counts per type, the top event type, and total purchase revenue.', '{"required_evidence": ["Parse JSON and iterate through events in a single pass(O(N)), validating required fields(type, price/amount) to prevent KeyError or schema mismatch.", "Maintain a hash map or Counter for event type counts, updating the top event type either dynamically or via max(counts, key=counts.get) after iteration.", "Accumulate purchase revenue only for purchase event types, ensuring safe numeric type casting(float/int/Decimal) and guarding against missing or malformed values."], "supporting_evidence": ["Recommend using decimal.Decimal instead of floating point to prevent precision loss in financial revenue computations.", "Mention streaming/generator parsing (e.g. ijson) if the JSON file is too large to fit in memory."], "negative_evidence": ["Makes multiple passes over the list (e.g. one pass to count types, another to find top type, another for revenue) when a single pass suffices.", "Uses standard float addition for high-precision currency transactions without acknowledging floating-point rounding inaccuracies."], "partial_credit": ["Provides working logic using Python dict or collections.Counter but fails to handle missing keys, malformed JSON, or non-purchase events safely."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'System Design & Data Structures', 'HARD', 'SPECIFIC', 240, 'Design an in-memory hierarchical task tracker: add, rename and finish tasks, print hierarchically, use unique IDs (and why not names), choose between list, dict and tree, and scale it.', '{"required_evidence": ["Design a Tree structure where each Task node has id, name, status, and children, combined with an in-memory hash map(id -> TaskNode) for O lookups, renames, and status updates.", "Explain why IDs are essential instead of names: names are not globally unique, can be renamed without breaking references, and support hierarchical re-parenting and index consistency.", "Implement hierarchical printing via Depth-First Search(DFS) recursion or an iterative stack, tracking indentation levels and subtree completion.", "Address scaling to millions of tasks: thread-safety with read-write locks or concurrent skip lists/maps, pagination of large subtrees, and persistence via an adjacency list or closure table in a database."], "supporting_evidence": ["Discuss cascading operations: mark parent finished when all children finish, or cancel all descendants when parent is cancelled.", "Mention memory optimization techniques like flyweight patterns, interning strings, and flat array-based tree representations (indices rather than pointers).", "Mentions specific implementation details or heuristics such as: 1."], "negative_evidence": ["Chooses a flat list requiring O(N) linear scans for every lookup and hierarchical traversal.", "Advocates using task names as primary keys, ignoring naming collisions and renaming side effects."], "partial_credit": ["Designs a basic tree with recursive print and explains why unique IDs are needed, but omits the hash map index for O(1) updates and does not address concurrency/scaling."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'System Design & Data Structures', 'MEDIUM', 'SPECIFIC', 180, 'How do snapshots preserve immutability when files change afterward? What must snapshot_diff do to detect added, modified and deleted files, and what outputs do you expect for edge-case sequences?', '{"required_evidence": ["Explain snapshot immutability mechanisms: Copy-On-Write(COW), content-addressable storage, or read-only filesystem clones/hardlinks that reference immutable data blocks.", "Define snapshot_diff logic: compare metadata/content hashes across two snapshots to identify files present in S2 but not S1(Added), present in S1 but not S2(Deleted), and present in both but with different hashes/content(Modified).", "Detail edge-case sequences and expected outputs: rapid file renames/moves(detected via inode or identical content hash), empty snapshots, file created and deleted between snapshots(invisible in diff), and file replaced by directory with identical name."], "supporting_evidence": ["Reference Git''s tree/blob object model or ZFS/Btrfs snapshotting as practical implementations of Merkle DAGs and Copy-On-Write block pointers.", "Discuss optimization via hierarchical tree hashing where unchanged directories can be skipped in O(1) time during diffing.", "Mentions specific implementation details or heuristics such as: Merkle trees / SHA-256 hashes.", "Mentions specific implementation details or heuristics such as: S1, S2."], "negative_evidence": ["Claims that taking a snapshot requires physically duplicating all file contents eagerly regardless of storage architecture.", "Relies solely on file timestamps (mtime) for diff detection, ignoring file modification timestamp tampering and identical-content touches."], "partial_credit": ["Explains Copy-on-Write and basic diff classification (added/modified/deleted), but misses edge cases like renames, type collisions (file-to-dir), or content hashing."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Defensive Programming & Error Handling', 'EASY', 'SPECIFIC', 180, 'How do you handle empty inputs and prevent runtime errors?', '{"required_evidence": ["Use defensive guard clauses / early returns at function entry to validate inputs(None, empty strings, empty collections, zero values) before business logic.", "Leverage language idioms and safe navigation: default parameters, optional types(Optional[T], null safety), ternary fallbacks, or the null coalescing operator.", "Distinguish between expected empty states versus exceptional empty states that violate contracts(raising ValueError or IllegalArgumentException)."], "supporting_evidence": ["Discuss schema validation libraries (e.g. Pydantic, Zod) to enforce non-empty contracts at system boundaries.", "Explain the Null Object Pattern to eliminate null checks throughout domain logic.", "Mentions specific implementation details or heuristics such as: empty search query returning empty list []."], "negative_evidence": ["Wraps the entire codebase in bare ''except Exception: pass'' blocks that swallow runtime errors silently.", "Assumes inputs are always populated because upstream systems ''should'' validate them."], "partial_credit": ["Mentions checking ''if not input:'' at the beginning of functions but does not distinguish contract exceptions from valid empty defaults or mention typed null safety."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 180, 'How do you vertically stack two DataFrames, and how do you update a column row-wise efficiently (trade-offs of apply)?', '{"required_evidence": ["Demonstrate vertical stacking using pd.concat and explain handling of matching vs mismatched columns(join=''outer'' vs ''inner'').", "Identify why DataFrame.apply is slow: it iterates over rows in pure Python overhead, boxing each row into a Series object and disabling C-level vectorization.", "Provide efficient row-wise alternatives: vectorized pandas/NumPy operations, list comprehensions with zip, or Cython/Numba."], "supporting_evidence": ["Mention memory reallocation costs when calling pd.concat inside a loop, recommending appending to a list of DataFrames/dicts and concatenating once.", "Discuss df.itertuples() as a faster alternative to .apply() or .iterrows() if custom Python control flow is strictly unavoidable.", "Mentions specific implementation details or heuristics such as: [df1, df2], axis=0, ignore_index=True.", "Mentions specific implementation details or heuristics such as: axis=1."], "negative_evidence": ["Recommends looping with df.iterrows() or iterative df.append() in a loop as best-practice high-performance solutions.", "Claims df.apply(axis=1) runs vectorized C code under the hood."], "partial_credit": ["Mentions pd.concat([df1, df2]) and says .apply() is slow, but cannot provide vectorized NumPy/pandas alternatives or explain why .apply() is slow."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Data Engineering & Big Data', 'MEDIUM', 'SPECIFIC', 180, 'How do you find duplicate records in a Spark DataFrame, and which Spark operations have you used?', '{"required_evidence": ["Find duplicates by grouping on primary/subset keys and filtering: df.groupBy(subset).count.filter or using window functions row_number.over(Window.partitionBy(subset).orderBy(...)).", "Use df.dropDuplicates(subset) or df.distinct to deduplicate records, explaining that dropDuplicates retains an arbitrary row unless ordered within a window.", "Detail fundamental Spark operations used: transformations(filter, select, withColumn, groupBy, join) vs actions(count, collect, write, take), noting wide vs narrow dependencies and shuffle implications."], "supporting_evidence": ["Explain the performance cost of wide transformations (shuffling across the network) in groupBy and dropDuplicates, and tuning spark.sql.shuffle.partitions.", "Discuss broadcast joins (broadcast(small_df)) to eliminate shuffles when joining large datasets with small lookup tables.", "Mentions specific implementation details or heuristics such as: ''count > 1''."], "negative_evidence": ["Suggests converting the Spark DataFrame to pandas via toPandas() to find duplicates on the driver node for production datasets.", "Confuses transformations and actions, claiming groupBy or filter immediately executes computation on the cluster."], "partial_credit": ["Mentions dropDuplicates() or groupBy().count(), but cannot explain window functions, wide vs narrow transformations, or Spark shuffle mechanics."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Data Engineering & Big Data', 'MEDIUM', 'SPECIFIC', 180, 'How do a data lake and a Delta Lake differ?', '{"required_evidence": ["Define Data Lake: a raw, centralized storage repository storing structured, semi-structured, and unstructured data files(Parquet, ORC, CSV, JSON) without transactional guarantees.", "Define Delta Lake: an open-source storage layer built on top of cloud object storage that brings ACID transactions, a transaction log(_delta_log), and table management to data lakes.", "Enumerate key Delta Lake capabilities: ACID compliance, schema enforcement and evolution, time travel(data versioning / historical rollbacks), unified batch and streaming, and compaction/Z-ordering optimizations."], "supporting_evidence": ["Explain how the transaction log achieves concurrency control (optimistic concurrency control) without distributed database locking.", "Compare Delta Lake with Apache Iceberg and Apache Hudi in the modern lakehouse storage layer ecosystem.", "Mentions specific implementation details or heuristics such as: S3, ADLS, GCS."], "negative_evidence": ["Claims Delta Lake is a proprietary closed hardware database appliance rather than a file format and storage layer on top of object storage.", "Believes standard data lakes inherently support ACID transactions and row-level updates/deletes out of the box."], "partial_credit": ["Explains that Delta Lake adds ACID transactions and history/versioning to a data lake, but cannot explain the transaction log or parquet foundation."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Data Engineering & Big Data', 'MEDIUM', 'SPECIFIC', 180, 'How do you understand a new data environment (schemas, quality, undocumented behavior, dependencies)?', '{"required_evidence": ["Schema & metadata discovery: inspect data catalogs, schemas, data dictionaries, primary/foreign keys, and upstream ELT orchestration DAGs(Airflow/dbt lineage).", "Profiling data quality: run statistical profiling(null rates, distributions, uniqueness, cardinality, range checks, orphan records) using tools like Great Expectations, Soda, or dbt tests.", "Uncovering undocumented behaviors: interview data producers/stakeholders, analyze git history and commit messages of transformation pipelines, and inspect query logs for actual production query patterns.", "End-to-end lineage mapping: trace data provenance from ingestion sources through transformation layers to downstream consumption(BI dashboards, ML models, APIs)."], "supporting_evidence": ["Construct a shadow pipeline or run reconciliation checks between upstream raw sources and downstream aggregates to detect data leakage or drift.", "Leverage automated lineage tools like OpenLineage, Marquez, or Monte Carlo for observability."], "negative_evidence": ["Relies exclusively on outdated static documentation without validating against actual live database records and query logs.", "Assumes columns adhere strictly to their names without checking for semantic overload (e.g., ''status'' containing undocumented string codes)."], "partial_credit": ["Mentions looking at database tables, running SQL ''SELECT *'', and talking to teammates, but lacks a systematic approach covering lineage, profiling, and automated testing."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Distributed Systems & Cloud Architecture', 'MEDIUM', 'SPECIFIC', 180, 'How would you scale a system from millions of files per day to billions per week, and support reprocessing after failures?', '{"required_evidence": ["Distributed asynchronous ingestion: decouple file ingestion using distributed message streaming / event buses(the appropriate framework/tool, the appropriate framework/tool SQS/SNS, Kinesis) with partition keys to distribute load across consumer worker pools.", "Batching & file compaction: aggregate millions of small files into optimized columnar batches to avoid the ''small file problem'' on object storage.", "Idempotent processing architecture: design processing jobs with deterministic unique transaction IDs, upsert semantics, or partitioned output writes to ensure reprocessing produces identical results without duplication.", "Reprocessing & backfill strategy: maintain an immutable event log or raw data lake zone, enabling replay of specific date ranges or partitions with dead-letter queues(DLQ) and backfill DAGs."], "supporting_evidence": ["Discuss autoscaling worker fleets (Kubernetes KEDA, AWS EMR/Batch) based on queue lag / consumer offset metrics.", "Explain stateful checkpointing and distributed snapshotting (e.g. Apache Flink checkpoints or Spark Structured Streaming checkpoints) for fault tolerance.", "Specifically mentions Kafka.", "Specifically mentions AWS."], "negative_evidence": ["Proposes processing individual small files synchronously via REST endpoints or single monolithic servers.", "Designs reprocessing without idempotency, causing double-counting or corrupting historical aggregations during replays."], "partial_credit": ["Suggests using Kafka and Spark to handle high volume, but fails to address the small file problem, idempotent recomputation, or specific backfill mechanisms."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 180, 'How do you design a system for peak load while minimizing idle-time cost?', '{"required_evidence": ["Elastic auto-scaling: implement horizontal pod/virtual machine autoscaling driven by predictive and reactive metrics(CPU, memory, queue depth, request latency).", "Asynchronous queue-based load leveling: buffer spiky incoming traffic using queues(SQS, the appropriate framework/tool, the appropriate framework/tool) to allow backend workers to process at a steady, cost-effective rate rather than over-provisioning for peak instantaneous spikes.", "Serverless & Spot/Preemptible instances: utilize serverless compute(the appropriate framework/tool Lambda, Cloud Run) for sporadic workloads and mix Spot instances with On-Demand/Reserved instances for fault-tolerant batch workers.", "Caching & edge offloading: absorb read peaks using CDNs(Cloudflare, CloudFront) and distributed in-memory caches(the appropriate framework/tool) to protect origin databases."], "supporting_evidence": ["Discuss scale-to-zero capabilities with Knative or AWS Aurora Serverless v2 for off-peak periods.", "Explain FinOps practices including scheduled scaling, rightsizing, and cost anomaly alerts.", "Mentions specific implementation details or heuristics such as: HPA, EC2 Auto Scaling Groups.", "Specifically mentions RabbitMQ."], "negative_evidence": ["Recommends permanently over-provisioning infrastructure to the maximum historical peak capacity.", "Relies solely on reactive CPU metrics for autoscaling without accounting for queue backpressure or instance warmup latency."], "partial_credit": ["Mentions using auto-scaling groups and AWS Lambda to scale up and down, but does not discuss queue buffering, caching, or spot instance cost optimization."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Web Architecture & Protocols', 'MEDIUM', 'SPECIFIC', 180, 'How does a real-time dashboard receive live data (polling, WebSockets, SSE)?', '{"required_evidence": ["Short & Long Polling: client periodically sends HTTP GET requests(short polling has high HTTP header overhead and latency; long polling holds the connection open until new data arrives, reducing empty polls but still requiring HTTP reconnection).", "Server-Sent Events(SSE): unidirectional, persistent HTTP connection where server pushes text/JSON streams to the client over standard HTTP/2, with built-in browser reconnection and event IDs.", "WebSockets: full-duplex, bidirectional TCP connection established via an HTTP handshake upgrade, ideal for interactive low-latency bidirectional communication.", "Architectural trade-off comparison: SSE is simpler, firewall-friendly, and perfect for read-only dashboards; WebSockets are required if clients must also send frequent low-latency messages; polling is simple fallback but resource-inefficient at scale."], "supporting_evidence": ["Mention connection management at scale: WebSocket gateways, sticky sessions, Redis Pub/Sub, or managed services like AWS API Gateway WebSockets.", "Discuss HTTP/2 multiplexing eliminating the browser connection limit for SSE."], "negative_evidence": ["Claims WebSockets are always necessary for real-time dashboards even when the communication is strictly unidirectional from server to client.", "Asserts that short polling at millisecond intervals scales efficiently for thousands of concurrent dashboard users."], "partial_credit": ["Defines polling, WebSockets, and SSE accurately, but cannot articulate architectural trade-offs or why SSE is often preferred for dashboards."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Machine Learning & Modeling', 'MEDIUM', 'SPECIFIC', 180, 'What is the intuition behind decision-tree splitting criteria (impurity measures)?', '{"required_evidence": ["Explain core intuition: split nodes such that child subsets are as homogeneous / pure as possible with respect to the target variable, maximizing information gain.", "Define Gini Impurity: probability that a randomly chosen element is misclassified if labeled randomly according to class distribution), reaching 0 for pure nodes and maximum for uniform distributions.", "Define Entropy and Information Gain: Shannon entropy)) measures uncertainty; Information Gain is the reduction in parent entropy achieved by splitting on an attribute.", "Contrast with regression splitting criteria: Mean Squared Error(MSE / variance reduction) or Mean Absolute Error(MAE), minimizing target variance within leaves."], "supporting_evidence": ["Compare Gini vs Entropy: Gini is computationally cheaper (no logarithmic calculations) and yields similar split trees in practice.", "Explain bias of standard Information Gain toward high-cardinality attributes and how Gain Ratio penalizes splits with many branches.", "Mentions specific implementation details or heuristics such as: 1 - sum(p_i^2.", "Mentions specific implementation details or heuristics such as: -sum(p_i * log2(p_i."], "negative_evidence": ["Claims Gini impurity and entropy measure physical thermodynamic energy or distance between vectors.", "Asserts that higher entropy or higher Gini values indicate better, purer tree splits."], "partial_credit": ["Explains that decision trees split to make groups purer and mentions Gini or Entropy formulas, but fails to explain the concept of information gain or regression criteria."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Deep Learning & Neural Networks', 'MEDIUM', 'SPECIFIC', 180, 'How does batch normalization help with vanishing gradients?', '{"required_evidence": ["Define Batch Normalization operation: normalizes layer inputs across the mini-batch to zero mean and unit variance, followed by learnable scale(gamma) and shift(beta) parameters.", "Preventing activation saturation: by keeping pre-activations centered near zero and bounded in variance, it prevents non-linear activations(sigmoid, tanh, or negative ReLUs) from saturating in regions with near-zero derivatives.", "Stabilizing gradient flow through layers: prevents internal covariate shift / exploding-vanishing layer scales, making the loss surface smoother(Lipschitz continuous) and allowing higher learning rates without divergence."], "supporting_evidence": ["Explain Santurkar et al. (2018) finding: BN primarily smoothens the optimization landscape / Hessian spectrum rather than strictly eliminating internal covariate shift.", "Contrast Batch Normalization behavior during training (batch statistics) vs inference (running exponential moving average of mean and variance)."], "negative_evidence": ["Claims Batch Normalization is applied across all training data at once rather than per mini-batch.", "Asserts that Batch Normalization eliminates the need for activation functions or backpropagation."], "partial_credit": ["Explains that BN normalizes activations to mean 0 and variance 1 to keep gradients from becoming too small, but misses learnable parameters or loss surface smoothing."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'Why do transformers beat RNNs, LSTMs, GRUs and CNNs for sequence and contextual data?', '{"required_evidence": ["Explains parallel computation: self-attention processes all tokens simultaneously, removing sequential recurrence bottlenecks and enabling massive parallel training on modern GPUs/TPUs.", "Explains mitigation of vanishing/exploding gradients over long contexts: self-attention provides a direct O path length between any two tokens, whereas RNNs/LSTMs must compress sequential state across O(N) steps where information decays.", "Compares against CNNs: CNNs require stacking many convolutional layers or dilated kernels to expand their receptive field, whereas self-attention captures global receptive field in a single layer."], "supporting_evidence": ["Discusses scaling laws demonstrating that transformers scale compute, parameter count, and data more effectively than recurrent architectures.", "Mentions positional encodings as the explicit mechanism replacing sequential recurrence to preserve word order.", "Mentions specific implementation details or heuristics such as: 1."], "negative_evidence": ["Claims RNNs or LSTMs are easier to parallelize across GPUs than Transformers.", "Believes transformers have O(1) overall computational complexity rather than O(1) maximum path length between tokens."], "partial_credit": ["Mentions that transformers process sequences faster and handle long-term memory better than RNNs, but lacks technical depth on parallelization bottlenecks or maximum path length."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Machine Learning & Modeling', 'MEDIUM', 'SPECIFIC', 180, 'What are the limits of mean, median and mode imputation? How do you choose imputation strategies for different missingness types (for example healthcare time series), and what dimensionality-reduction techniques are common?', '{"required_evidence": ["Limitations of univariate statistical imputation: mean/median/mode distort feature distributions, artificially shrink variance/standard error, bias parameter estimates, and destroy inter-feature correlations.", "Taxonomy of missingness: MCAR(Missing Completely at Random), MAR(Missing at Random), and MNAR(Missing Not at Random\\u2014e.g. sick patients having tests ordered while healthy ones do not, making the absence itself informative).", "Healthcare time-series imputation strategies: forward-fill / last observation carried forward(LOCF) with time-elapsed indicators, interpolation/splines, MICE(Multivariate Imputation by Chained Equations), KNN imputation, or missingness mask indicators.", "Common dimensionality-reduction techniques: linear methods(PCA, Factor Analysis, SVD) vs non-linear manifold learning(t-SNE, UMAP, Autoencoders), explaining their trade-offs regarding variance preservation vs neighborhood clustering."], "supporting_evidence": ["Explain GAIN (Generative Adversarial Imputation Networks) or diffusion models for complex tabular/time-series data imputation.", "Emphasize computing imputation statistics strictly on training folds to prevent data leakage into validation/test splits."], "negative_evidence": ["Recommends default mean imputation for MNAR healthcare variables without adding missingness indicators, masking critical clinical signals.", "Claims PCA should be applied before handling missing data without realizing standard PCA requires complete matrices."], "partial_credit": ["Explains mean/median drawbacks and mentions PCA/t-SNE, but fails to discuss missingness categories (MCAR/MAR/MNAR) or specialized time-series imputation techniques."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Machine Learning & Modeling', 'MEDIUM', 'SPECIFIC', 180, 'How do you make models generalize (data splitting, validation)?', '{"required_evidence": ["Rigorous dataset partitioning: split into Train, Validation, and Test sets; strictly seal the test set until final model evaluation to prevent data leakage and optimistic bias.", "Cross-validation strategies: use k-fold cross-validation, Stratified K-Fold for imbalanced classification, and GroupKFold to avoid leakage when samples share groupings.", "Temporal splitting for sequential/time-series data: use forward-chaining / rolling-window time-based splits rather than random shuffling to preserve causality and prevent future lookahead.", "Generalization and regularization techniques: apply early stopping, dropout, weight decay, data augmentation, and evaluate the train-vs-validation loss gap to diagnose overfitting."], "supporting_evidence": ["Discuss nested cross-validation to perform unbiased hyperparameter tuning and model selection simultaneously.", "Explain adversarial validation to detect distribution shift between training and test sets.", "Mentions specific implementation details or heuristics such as: multiple records from same patient/user.", "Mentions specific implementation details or heuristics such as: TimeSeriesSplit."], "negative_evidence": ["Performs random train-test splitting on time-series data or user-grouped data, introducing major data leakage.", "Tunes hyperparameters directly on the test set and reports the resulting test score as generalization performance."], "partial_credit": ["Mentions 80/20 train/test splits and k-fold cross validation, but misses temporal splitting, stratified/grouped splits, or proper leakage prevention."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 240, 'How do you test non-deterministic outputs and design negative test scenarios?', '{"required_evidence": ["Explains testing non-deterministic outputs: using semantic assertions, schema validation(Pydantic/JSON schema), embedding cosine similarity against reference embeddings, and LLM-as-a-judge with confidence intervals rather than exact string equality.", "Details designing negative test scenarios: testing adversarial prompt injections, out-of-domain queries, incomplete/malformed inputs, empty retrieval contexts, and toxicity/policy bypass attempts(jailbreaks).", "Describes asserting expected refusals: verifying that the model gracefully refuses or raises controlled fallback errors on negative inputs rather than hallucinating or leaking sensitive instructions."], "supporting_evidence": ["Mentions temperature setting (temperature = 0) to reduce variance during testing, while running multi-run statistical assertions to evaluate distribution stability.", "Discusses automated red-teaming frameworks (e.g., Garak, PyRIT)."], "negative_evidence": ["Asserts strict string equality (assert response == expected_string) for generative outputs in test suites.", "Ignores negative testing, assuming positive happy-path testing covers all edge cases."], "partial_credit": ["Mentions setting temperature to 0 and checking for bad words, but lacks semantic assertions, negative test design patterns, or structured refusal validation."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'MLOps & Model Lifecycle', 'MEDIUM', 'SPECIFIC', 180, 'How often do you fine-tune, and how do you detect data drift (for example KL divergence)?', '{"required_evidence": ["Fine-tuning frequency cadence: determined by business domain dynamics, data arrival rate, drift magnitude, and compute cost(ranging from continuous/daily for dynamic recommendation to monthly/quarterly or trigger-based for LLMs).", "Statistical drift detection methods: calculate Kullback-Leibler(KL) divergence, Jensen-Shannon(JS) divergence, Population Stability Index(PSI), or Kolmogorov-Smirnov(KS) test comparing baseline/reference distributions to current production distributions.", "Distinction between drift types: Covariate / Data Drift P(X)(input feature distribution changes), Prior Probability Drift P(Y), and Concept Drift P(Y|X)(relationship between inputs and outputs changes, requiring retraining even if inputs look similar)."], "supporting_evidence": ["Explain practical limitations of KL divergence: asymmetric, undefined when target probability is zero (requiring epsilon smoothing or symmetric JS divergence).", "Discuss embedding drift detection via centroid shift or Maximum Mean Discrepancy (MMD) for high-dimensional unstructured data."], "negative_evidence": ["Suggests fine-tuning complex foundation models on every single incoming user query in real time.", "Confuses data drift (change in inputs) with software bugs or server latency spikes."], "partial_credit": ["Mentions monitoring distributions using KL divergence and retraining when accuracy drops, but cannot differentiate covariate drift from concept drift or explain practical retraining schedules."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Machine Learning & Modeling', 'MEDIUM', 'SPECIFIC', 180, 'Which models would you consider for time-series or demand forecasting, and how do you select one offline and online?', '{"required_evidence": ["Model taxonomy for forecasting: Statistical baselines(ARIMA/SARIMAX, Exponential Smoothing/ETS), Tree-based regressors with lag/window features(LightGBM, XGBoost), Deep Learning models(DeepAR, Temporal Fusion Transformers / TFT, N-BEATS), and Foundation Time-Series Models(Chronos, TimesFM).", "Offline selection & validation: rolling-origin cross-validation(walk-forward backtesting) evaluating business-relevant metrics like WAPE, MASE, RMSE, and pinball loss(for quantile/probabilistic forecasts).", "Online selection & production evaluation: shadow testing or multi-armed bandits / canary A/B testing measuring real-time forecast error, operational stability, inference latency, and business impact(stockout rate, inventory waste, holding costs).", "Cold-start and exogenous feature handling: utilizing global models that learn across thousands of series simultaneously and incorporate static item metadata plus promotional calendars."], "supporting_evidence": ["Discuss intermittent/lumpy demand forecasting methods like Croston''s method for spare parts or low-volume goods.", "Explain hierarchical time series reconciliation (e.g. Bottom-Up, Top-Down, MinT) across store, regional, and national levels.", "Mentions specific implementation details or heuristics such as: LightGBM, TFT."], "negative_evidence": ["Uses standard random k-fold cross validation on time-series data, leaking future demand into historical training folds.", "Relies solely on naive linear regression or simple moving average for complex seasonal multi-echelon retail demand."], "partial_credit": ["Names several forecasting models (ARIMA, XGBoost, LSTM) and mentions backtesting, but does not explain walk-forward validation or how to evaluate models online."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Data Engineering & Big Data', 'MEDIUM', 'SPECIFIC', 180, 'How do you preprocess and validate data (missing values, outliers, versioning)?', '{"required_evidence": ["Missing value handling: identify missing mechanisms, apply appropriate imputation(mean/median for skewed features, KNN/iterative, or explicit indicator flags), ensuring imputers are fit solely on training data.", "Outlier detection and treatment: detect anomalies via statistical bounds or isolation forests; handle via winsorization/clipping, transformation(log/Box-Cox), or domain-specific filtering.", "Data and schema validation: enforce structural and statistical expectations at pipeline gates using schemas(Pydantic, Great Expectations, Deequ) to catch schema drift, out-of-range values, and null violations.", "Data versioning & reproducibility: track dataset snapshots, transformations, and artifacts using tools like DVC, Delta Lake time travel, or Feast feature stores linked to Git commit hashes."], "supporting_evidence": ["Discuss sklearn Pipeline and ColumnTransformer to prevent leakage between preprocessing and modeling steps.", "Mention automated CI/CD data checks blocking corrupt data releases into production training stores.", "Mentions specific implementation details or heuristics such as: IQR 1.5x rule, Z-score > 3."], "negative_evidence": ["Performs outlier removal and imputation on the entire dataset prior to train/test splitting, creating major data leakage.", "Deletes all rows containing any missing values blindly, discarding large fractions of valid data."], "partial_credit": ["Lists imputation, IQR outlier detection, and mentions DVC, but fails to emphasize leakage prevention or programmatic data contracts."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Machine Learning & Modeling', 'MEDIUM', 'SPECIFIC', 180, 'How do you build models for edge devices (memory, latency, distillation)?', '{"required_evidence": ["Model compression techniques: Post-Training Quantization(PTQ) and Quantization-Aware Training(QAT) to convert FP32 weights to INT8/INT4; structured/unstructured pruning to remove redundant weights.", "Knowledge Distillation: train a compact student model to mimic the soft probability distributions and intermediate representations of a large teacher model, retaining performance at a fraction of compute.", "Edge-optimized architectures: select lightweight neural architectures designed for edge hardware.", "Runtime inference engines & hardware acceleration: compile models using edge runtimes(ONNX Runtime, TensorRT, CoreML, TFLite) to leverage NPU, GPU, and DSP hardware acceleration."], "supporting_evidence": ["Discuss static vs dynamic quantization and flash memory / SRAM bandwidth constraints on microcontrollers (TinyML).", "Explain operator fusion and layer pruning during graph optimization.", "Mentions specific implementation details or heuristics such as: MobileNet with depthwise separable convolutions, EfficientNet, MobileViT, TinyLlama."], "negative_evidence": ["Attempts to deploy uncompressed 32-bit billion-parameter foundation models directly to edge devices without quantization or architecture adaptation.", "Claims quantization reduces memory footprint but has zero impact on inference latency or numerical precision."], "partial_credit": ["Mentions quantization and knowledge distillation, but lacks details on edge runtimes (TFLite/ONNX) or edge-specific architectures (MobileNet)."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'How much memory does hosting an 8B model locally need?', '{"required_evidence": ["Weight memory calculation: 8 billion parameters require ~16 GB in FP16/BF16, ~8 GB in INT8, and ~4-5.5 GB in INT4.", "KV Cache memory overhead: memory required for storing key-value activations during generation depends on context length, layer count, attention heads, and batch size, easily adding 2-8+ GB.", "Activation memory & runtime CUDA overhead: allocate an additional 1-2 GB for the appropriate framework/tool/CUDA runtime context, model activations, and buffer memory.", "Hardware recommendation conclusion: an 8B model requires at least a 24 GB VRAM GPU for FP16 serving with decent context/concurrency, or an 8-16 GB GPU/Unified RAM for INT4/GGUF quantization."], "supporting_evidence": ["Discuss KV cache optimization techniques like PagedAttention (vLLM) and Grouped-Query Attention (GQA) that drastically reduce KV memory footprint.", "Contrast inference memory requirements with fine-tuning memory (which requires optimizer states, gradients, and forward activations\\u2014often 4x-6x model size unless using LoRA/QLoRA).", "Mentions specific implementation details or heuristics such as: 2 bytes per parameter.", "Mentions specific implementation details or heuristics such as: 1 byte per parameter."], "negative_evidence": ["Claims an 8B model in FP16 only takes 8 GB of RAM (confusing bytes per parameter with parameter count).", "Ignores the KV cache entirely, assuming model weight size is the only memory required during inference."], "partial_credit": ["Calculates weight sizes correctly (16 GB for FP16, 4 GB for INT4) but forgets the KV cache and runtime CUDA overhead."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'What consequences do you expect when swapping a very large model for a much smaller one with everything else held constant?', '{"required_evidence": ["Quality & capability degradation: reduced multi-step complex reasoning, lower zero-shot task generalization, diminished world knowledge, and higher hallucination rates.", "Instruction following & schema compliance: smaller models struggle more with strict schema adherence, edge cases, and long system prompt instructions.", "Performance improvements: substantial decrease in inference latency(Time-to-First-Token and Time-per-Output-Token), higher throughput(tokens/second), and dramatically reduced compute/VRAM requirements.", "Economic impact: drastic reduction in hosting or API token costs, enabling cost-effective scaling to millions of daily requests."], "supporting_evidence": ["Explain mitigation strategies: few-shot prompting, schema enforcement engines (Instructor, Outlines), knowledge distillation, or task-specific fine-tuning to recover small model accuracy.", "Discuss cascading / router architectures: using the small model for 90% of simple requests and routing difficult edge cases to the large model.", "Mentions specific implementation details or heuristics such as: complex JSON outputs."], "negative_evidence": ["Claims a smaller model will produce identical outputs if prompted with the exact same system prompt.", "Believes smaller models have equal multi-step mathematical and reasoning capability as frontier foundation models without fine-tuning."], "partial_credit": ["Notes that latency and cost decrease while output quality and reasoning degrade, but fails to mention instruction following, hallucination risks, or mitigation strategies."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'How do you select a foundation model (context window, reasoning, cost) and optimize cost?', '{"required_evidence": ["Model selection evaluation criteria: benchmark reasoning capability on domain-specific tasks, verify required context window(accounting for effective recall across needle-in-a-haystack tests), and evaluate input/output token pricing vs latency SLAs.", "Tiered model routing & cascading: route simple classification/extraction queries to lightweight, cheap models and escalate complex multi-step reasoning to frontier models.", "Prompt engineering & caching optimizations: use prompt caching(prefix caching) for long static contexts/system instructions, trim redundant prompt tokens, and compress context.", "Architecture optimization: use semantic caching(the appropriate framework/tool/GPTCache) for duplicate queries, switch to fine-tuned small open-source models for high-volume static tasks, and batch offline workloads."], "supporting_evidence": ["Discuss LLM evaluation frameworks (Ragas, DeepEval, promptfoo) to make objective model selection decisions based on Pareto frontiers of quality vs cost.", "Explain structured outputs with constrained decoding to avoid output token bloat and retry overhead.", "Mentions specific implementation details or heuristics such as: frontier model-mini, small/fast model, Llama-3-8B.", "Mentions specific implementation details or heuristics such as: frontier model, frontier model."], "negative_evidence": ["Always routes 100% of user traffic to the most expensive frontier model regardless of task complexity.", "Assumes models with large theoretical context windows (e.g. 1M tokens) have perfect recall without testing for retrieval degradation."], "partial_credit": ["Mentions choosing models based on price and context size and using smaller models to save money, but lacks concrete cost optimization strategies like semantic caching, prompt caching, or model routing."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Analytics & Product Metrics', 'MEDIUM', 'SPECIFIC', 180, 'How do you analyze a decline in new-user spend (cohorts, segment shifts, product, pricing and onboarding changes, external factors)?', '{"required_evidence": ["Cohort analysis & funnel decomposition: break down new-user spend across weekly/monthly acquisition cohorts; decompose spend into Users * Conversion Rate * Average Order Value(AOV) / transaction frequency to isolate where the funnel is breaking.", "Mix shift & segment shift analysis(Simpson''s Paradox): perform step-down decomposition across dimensions(acquisition channel, geography, device, marketing campaign) to verify if individual segment spend dropped or if traffic shifted toward lower-monetizing segments.", "Internal product & pricing audits: review recent releases, paywall/pricing changes, onboarding UX experiments, payment gateway failures, or checkout bugs launched concurrently with the decline.", "External macro & competitive factors: evaluate seasonality, holidays, macroeconomic shifts, competitor promotions, or privacy tracking changes affecting traffic quality."], "supporting_evidence": ["Utilize difference-in-differences (DiD) or counterfactual causal modeling against unaffected user cohorts to measure the exact impact of a product change.", "Check data pipeline and tracking telemetry integrity first to ensure the decline is real and not an ingestion logging anomaly.", "Mentions specific implementation details or heuristics such as: iOS ATT, ad targeting shifts."], "negative_evidence": ["Jumps to a single speculative root cause immediately without systematically isolating funnel stages, cohorts, or segment shifts.", "Compares aggregate numbers across two different time periods without accounting for cohort maturation or traffic source changes."], "partial_credit": ["Suggests checking cohorts and looking at marketing channels or recent product releases, but lacks structured mathematical decomposition (Conversion x AOV) or mix-shift analysis."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'HARD', 'SPECIFIC', 240, 'How would you design a matchmaking system for 100k users with weekly personalized matches, and how do you ensure match quality?', '{"required_evidence": ["Multi-stage matchmaking pipeline: candidate generation / retrieval(fast filtering via hard constraints like location, age, preferences using spatial/vector indexes), candidate scoring / ranking(Two-Tower ML models, GNNs, or gradient boosted trees predicting mutual match affinity), and global optimization assignment.", "Two-sided matching optimization: formulate as a Stable Marriage / Gale-Shapley variant, Minimum Cost Maximum Flow, or Integer Linear Programming(ILP) to maximize global platform utility while satisfying capacity constraints.", "Mutual preference & reciprocity: ensure scoring incorporates two-sided probabilities P(Match) = P(A likes B) * P(B likes A), rather than unidirectional preference.", "Match quality assurance & feedback loop: track quality metrics(mutual response rate, conversation length, second-date rating, unmatch/report rate), calibrate scores using contextual bandits, and run pre-release quality audits."], "supporting_evidence": ["Explain batch scheduling architecture: running the weekly matching job asynchronously using distributed batch workflows (Spark / Ray on Airflow) during off-peak hours.", "Address fairness and popularity de-biasing to ensure top profiles do not monopolize all incoming matches while leaving active users unmatched.", "Mentions specific implementation details or heuristics such as: exactly 1-3 matches per user per week."], "negative_evidence": ["Designs the system as an unconstrained greedy nearest-neighbor search, resulting in the top 1% most attractive users receiving 100,000 matches while the remaining 99% receive zero.", "Proposes running heavy deep learning inference synchronously on user login rather than pre-computing weekly batches offline."], "partial_credit": ["Describes filtering by preferences and ranking using machine learning, but fails to formulate the global assignment problem (Gale-Shapley/ILP) or account for two-sided reciprocity."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Recommendation Systems', 'MEDIUM', 'SPECIFIC', 180, 'How do you handle missing or sparse user data, fairness when many users prefer the same profile, and stale explicit data?', '{"required_evidence": ["Sparse / missing data mitigation: leverage transfer learning, graph neural networks(GNNs) over social/behavioral graphs, matrix factorization with regularization(ALS), cross-domain metadata, and active learning onboarding questionnaires.", "Fairness & popularity distribution(superstar problem): implement bipartite matching capacity constraints(capping maximum weekly inbound matches per profile), exposure-damping / popularity penalties in ranking scores, or diversity re-ranking(Maximal Marginal Relevance - MMR).", "Decaying stale explicit data: apply exponential time-decay weighting to historical interactions(exp(-lambda * delta_t)), dynamically reconcile explicit preferences against recent implicit behavior, and prompt users with periodic profile refresher flows."], "supporting_evidence": ["Discuss Gini coefficient of impressions/matches across the user base as an objective system-level fairness metric.", "Explain collaborative filtering bias corrections, such as Inverse Propensity Weighting (IPW) to correct for observational exposure bias."], "negative_evidence": ["Allows unrestricted winner-take-all dynamics where popular users receive an unmanageable volume of matches they cannot realistically reply to.", "Treats 3-year-old explicit user preferences as equally valid and permanent compared to yesterday''s user swipes."], "partial_credit": ["Addresses popularity caps and mentions using time decay for old data, but lacks solutions for sparse data (GNNs, cross-domain embeddings) or formal fairness metrics."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Recommendation Systems', 'MEDIUM', 'SPECIFIC', 180, 'How would you balance exploration and exploitation in matchmaking?', '{"required_evidence": ["Exploitation vs Exploration trade-off definition: exploitation serves candidates with the highest known predicted match probability; exploration serves uncertain, newly joined, or under-exposed candidates to gather data and refine user preference models.", "Multi-Armed Bandits & contextual bandits: implement algorithms such as LinUCB(Upper Confidence Bound with uncertainty bonus) or Thompson Sampling(Bayesian sampling from posterior reward distributions) to balance discovery and reward.", "Epsilon-greedy with exploration budgets: allocate a dedicated fraction of recommendations to exploration, ensuring explore candidates still meet baseline compatibility constraints.", "Guarding user experience during exploration: constrain exploration candidate distance using pessimistic lower bounds or safety floors to prevent catastrophic bad matches."], "supporting_evidence": ["Discuss serendipity and diversity metrics: measuring long-term user retention gains resulting from diverse recommendations vs short-term CTR drops.", "Explain off-policy evaluation (OPE) methods like Doubly Robust estimation to evaluate bandit policies from historical logs.", "Mentions specific implementation details or heuristics such as: epsilon ~ 5-15%."], "negative_evidence": ["Proposes pure greedy exploitation, which creates severe feedback loops, filter bubbles, and starves new users of exposure.", "Suggests 100% random exploration without any preference filtering, destroying user trust and match quality."], "partial_credit": ["Explains epsilon-greedy exploration and why showing new profiles is necessary, but lacks formal bandit formulations (LinUCB/Thompson Sampling) or safety guardrails."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Recommendation Systems', 'MEDIUM', 'SPECIFIC', 180, 'How would you use minimax and minimax regret, risk budgets and worst-case bounds to avoid repeated poor recommendations?', '{"required_evidence": ["Minimax formulation: optimize recommendations against the worst-case user preferences / states, maximizing the minimum guaranteed user utility(max_a min_s U(a, s)) to avoid catastrophic user dissatisfaction.", "Minimax Regret formulation: minimize the maximum regret\\u2014the difference between the reward of the chosen recommendation and the best possible recommendation in hindsight(min_a max_s [U(a*_s, s) - U(a, s)]), providing robust bounds without overly conservative pessimism.", "Risk budgets & worst-case bounds: enforce constraints where each user has a maximum risk tolerance budget per session.", "Anti-repetition & fatigue penalties: introduce hard negative filters, sliding-window frequency capping, and severe penalties for repeated unclicked or dismissed items to prevent recommendation deadlocks."], "supporting_evidence": ["Discuss Conditional Value at Risk (CVaR) optimization in recommender reward objectives to optimize the tail 5% of worst recommendation experiences.", "Explain the balance between conservative worst-case bounds and serendipity/novelty.", "Mentions specific implementation details or heuristics such as: limiting low-confidence or high-variance exploratory recommendations to at most 1 out of 5 slots."], "negative_evidence": ["Optimizes exclusively for expected (mean) reward, ignoring tail risk and catastrophic negative user experiences that drive user churn.", "Claims minimax decision theory can only be applied to zero-sum board games like chess rather than robust recommendation systems."], "partial_credit": ["Defines minimax and regret conceptually and mentions frequency capping, but does not formulate risk budgeting or worst-case bounds within recommendation algorithms."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Machine Learning & Modeling', 'MEDIUM', 'SPECIFIC', 180, 'How would you model a user belief state and update it with Bayesian updates after each accept or reject?', '{"required_evidence": ["Belief state representation: model user preferences over candidate latent attributes/features theta as a probability distribution, or Beta distributions over categorical attributes).", "Likelihood modeling: define observation likelihood P(Action | theta, x) for accept or reject given item features x using a logistic/sigmoid function sigma(theta^T x) or probit link function.", "Bayesian posterior update: apply Bayes'' theorem P(theta | y) proportional to P(y | theta, x) * P(theta); for non-conjugate logistic likelihoods, use approximate inference(Laplace approximation, Expectation Propagation, Variational Inference) or Kalman/Assumed Density Filtering.", "Uncertainty shrinkage & next item selection: each accept/reject updates the mean preference mu and shrinks the covariance / variance Sigma, which feeds directly into Thompson Sampling by sampling theta_tilde ~ N(mu, Sigma) for the next recommendation."], "supporting_evidence": ["Reference TrueSkill or Elo rating systems as 1D/bivariate Gaussian Bayesian belief updates based on pairwise outcomes.", "Discuss particle filtering / sequential Monte Carlo when modeling multimodal or non-linear dynamic preference drift.", "Mentions specific implementation details or heuristics such as: multivariate Gaussian theta ~ N(mu, Sigma.", "Mentions specific implementation details or heuristics such as: y=1."], "negative_evidence": ["Claims Bayesian updating requires retraining an entire deep neural network from scratch after every single swipe.", "Confuses Bayesian updating with standard gradient descent, stating that Bayes'' rule calculates gradients of a loss function."], "partial_credit": ["Formulates prior, likelihood, and posterior conceptually (P(theta|D) proportional to P(D|theta)P(theta)), but cannot explain how to update mean and variance/covariance or how to handle non-conjugate updates."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Recommendation Systems & Causal Inference', 'MEDIUM', 'SPECIFIC', 180, 'How would you use counterfactual reasoning and hypothesis simulation to reconsider rejected candidates?', '{"required_evidence": ["Defines counterfactual reasoning in candidate ranking: estimating ''what would the outcome have been if candidate features, context, or scoring thresholds had been different''.", "Explains hypothesis simulation techniques such as inverse propensity scoring(IPS), doubly robust estimation, or generative user/interviewer simulation under modified policy thresholds.", "Details how rejected candidates are re-evaluated by isolating confounding factors to estimate counterfactual rewards without naive re-evaluation."], "supporting_evidence": ["Discusses exploration-exploitation frameworks (e.g., contextual bandits, epsilon-greedy) to prevent permanent deterministic exclusion of borderline candidates.", "Mentions building synthetic cohorts to simulate policy shifts offline before deploying them live.", "Mentions specific implementation details or heuristics such as: progression, conversion, acceptance.", "Mentions specific implementation details or heuristics such as: presentation bias, rigid hard cutoffs, missing signals."], "negative_evidence": ["Conflates counterfactual reasoning with simply re-running the same model on the exact same rejected cohort without adjusting for selection bias.", "Assumes unobserved outcomes of rejected candidates can be treated as known ground truth."], "partial_credit": ["Explains counterfactual reasoning conceptually as ''what-if'' testing, but lacks formal causal estimation methods (e.g., propensity weighting, bandit algorithms)."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Recommendation Systems & Feedback Loops', 'MEDIUM', 'SPECIFIC', 180, 'How do you track rejections (a hypothesis bank) to improve later recommendations?', '{"required_evidence": ["Describes capturing structured rejection metadata rather than a binary negative label.", "Explains the hypothesis bank architecture as a structured repository that stores falsifiable hypotheses that can be tested when new data or criteria emerge.", "Details how rejection data is used to improve future recommendations via hard negative mining, dynamic constraint relaxation, or recalibrating ranking loss functions."], "supporting_evidence": ["Addresses label delay and survival analysis when candidates gain qualifications or succeed in other similar roles later.", "Differentiates between hard rejections (fundamental mismatch) and soft rejections (timing, headcount limits).", "Mentions specific implementation details or heuristics such as: specific rejection reasons, stage of rejection, candidate features, model scores, decision-maker attributes, timestamp.", "Mentions specific implementation details or heuristics such as: ''rejected due to missing skill X''."], "negative_evidence": ["Treats all rejections as uniform, permanent negative training examples, introducing systemic feedback loops and model bias.", "Proposes storing unstructured free-text rejection notes without schema, taxonomy, or feature extraction."], "partial_credit": ["Mentions logging reasons for rejection in a database, but does not explain how this hypothesis bank informs model re-training or downstream recommendation adjustments."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'How do you suggest relevant follow-up questions from conversation history?', '{"required_evidence": ["Describes generation techniques: prompting the LLM with current dialogue context to output 2-3 concise, anticipatory follow-up questions formatted as structured JSON.", "Explains grounding follow-up suggestions in available knowledge/retrieved context: ensuring proposed questions relate to verified documentation paths and user intent rather than ungrounded speculative topics.", "Details ranking and filtering heuristics: deduplicating against previously asked user questions, filtering out questions the current response already answered, and optimizing for user goal completion."], "supporting_evidence": ["Mentions offline mining of frequent query transitions (Markov chains or graph of common user journeys) to suggest proven high-utility next steps.", "Discusses UI integration: rendering suggestions as interactive clickable chips to reduce user typing friction."], "negative_evidence": ["Generates generic or redundant questions that the assistant just answered in the immediately preceding message.", "Suggests open-ended queries that lead the user into known product limitations or unsupported domains."], "partial_credit": ["Suggests asking the LLM to output 3 questions based on the chat, but lacks grounding constraints, deduplication against past turns, or structured schema output."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Vector Databases & Retrieval', 'EASY', 'SPECIFIC', 180, 'Why is cosine similarity preferred over Euclidean or Manhattan distance?', '{"required_evidence": ["Explains that cosine similarity measures the angular orientation between two vectors regardless of their magnitude, making it invariant to document length or embedding norm differences.", "Contrasts with Euclidean and Manhattan distance, which are sensitive to absolute vector length and suffer from distance concentration in high-dimensional spaces.", "Notes that when embeddings are L2-normalized, cosine similarity and squared Euclidean distance produce identical rankings."], "supporting_evidence": ["Mentions computational efficiency: for normalized vectors, cosine similarity reduces to a standard dot product, enabling highly optimized BLAS / SIMD matrix operations.", "Mentions specific implementation details or heuristics such as: L2.", "Mentions specific implementation details or heuristics such as: L1.", "Mentions specific implementation details or heuristics such as: unit length ||v|| = 1."], "negative_evidence": ["Claims cosine similarity measures vector magnitude and absolute distance.", "States that cosine similarity and Euclidean distance are completely unrelated even on normalized unit vectors."], "partial_credit": ["States that cosine similarity measures angles and ignores text length, but fails to explain why length variation occurs or how normalization connects cosine to Euclidean distance."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Vector Databases & Retrieval', 'MEDIUM', 'SPECIFIC', 180, 'When do you need to re-embed a corpus, and what signals trigger it?', '{"required_evidence": ["Identifies structural model triggers: upgrading to a new embedding model, altering embedding dimensions, modifying chunking strategies(size/overlap), or changing document normalization/preprocessing logic.", "Identifies data and distribution drift signals: semantic shift in terminology, temporal decay, or significant drops in retrieval recall, MRR, and NDCG.", "Details operational re-indexing strategies: running zero-downtime dual/shadow index deployments(blue/green index) to backfill embeddings asynchronously before switching traffic."], "supporting_evidence": ["Discusses cost/latency trade-offs of full corpus re-embedding vs training linear alignment projection layers between embedding spaces.", "Mentions automated monitoring of query-document embedding similarity distribution shifts.", "Mentions specific implementation details or heuristics such as: emergence of new domain jargon, slang, product names."], "negative_evidence": ["Believes embeddings from different models, versions, or dimensions can be queried together in the same index space.", "Advocates re-embedding the entire multi-terabyte corpus for every single new document ingestion."], "partial_credit": ["Mentions that switching models requires re-embedding, but fails to identify data drift signals, chunking alterations, or zero-downtime deployment patterns."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'RAG & Document Processing', 'MEDIUM', 'SPECIFIC', 180, 'How do you preserve semantic meaning in text (chunking, overlap, context)?', '{"required_evidence": ["Explains boundary-aware semantic chunking: splitting text along natural structural boundaries(sentences, paragraphs, Markdown headers, or syntax trees for code) rather than arbitrary fixed-character counts.", "Explains chunk overlap: retaining 10-20% sliding window overlap across adjacent chunks to prevent severing sentences, coreference chains, and cross-boundary context.", "Describes context enrichment strategies: prepending document/section hierarchy breadcrumbs, parent-document retrieval(small-to-big chunking), or generating synthetic summary headers per chunk."], "supporting_evidence": ["Discusses late chunking (passing full document through transformer before pooling chunk token spans) or token-level contextual retrieval (e.g., ColBERT).", "Mentions using LLMs to generate situational context summaries prepended to each chunk prior to embedding."], "negative_evidence": ["Recommends fixed-size character slicing without overlap or sentence boundary awareness.", "Claims semantic meaning is best preserved by making chunks as large as the model''s maximum context window regardless of retrieval precision."], "partial_credit": ["Mentions chunk overlap and splitting by paragraphs, but omits discussion of context enrichment, parent-child indexing, or semantic boundary detection."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Vector Databases & Retrieval', 'MEDIUM', 'SPECIFIC', 180, 'How do you compare vector stores (for example FAISS versus Pinecone) and evaluate them?', '{"required_evidence": ["Contrasts architectural models: standalone in-process vector library(FAISS) requiring self-managed hosting, sharding, replication, and persistence vs fully managed cloud-native SaaS(Pinecone) providing automated horizontal scaling, high availability, and managed APIs.", "Defines evaluation benchmarks: query latency percentiles vs recall@k curve, QPS throughput under concurrent load, index build/upsert latency, and memory/disk storage efficiency.", "Evaluates enterprise feature support: hybrid search, dynamic metadata filtering(pre-filtering vs post-filtering), RBAC, backup/restore, and total cost of ownership(TCO)."], "supporting_evidence": ["Compares specialized vector databases with general-purpose databases adding vector extensions (e.g., pgvector).", "Mentions benchmark suites like ANN-Benchmarks for standardized vector store evaluation.", "Mentions specific implementation details or heuristics such as: p95/p99.", "Mentions specific implementation details or heuristics such as: dense + BM25 sparse vectors."], "negative_evidence": ["Claims FAISS is a distributed database service with built-in networking, replication, and managed security.", "Assumes managed SaaS vector stores are always superior without considering data privacy, sovereign hosting, or on-prem latency requirements."], "partial_credit": ["Identifies FAISS as a local library and Pinecone as a managed cloud service, but fails to provide technical evaluation criteria (recall vs latency, QPS, filtering, TCO)."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Vector Databases & Retrieval', 'MEDIUM', 'SPECIFIC', 180, 'How do you optimize queries and rank results for relevance?', '{"required_evidence": ["Explains query transformation techniques: query expansion, HyDE(Hypothetical Document Embeddings), query decomposition for multi-part intents, and step-back prompting.", "Describes hybrid retrieval combining dense vector similarity(semantic understanding) with sparse lexical search fused via Reciprocal Rank Fusion(RRF) or relative score fusion.", "Details multi-stage ranking pipelines: fast first-stage bi-encoder retrieval followed by a compute-intensive cross-encoder re-ranker to evaluate joint query-document attention."], "supporting_evidence": ["Discusses diversity re-ranking such as Maximal Marginal Relevance (MMR) to eliminate redundant passages in retrieved context.", "Mentions fine-tuning domain-specific cross-encoders on hard negative mining pairs.", "Mentions specific implementation details or heuristics such as: BM25 for exact keyword/part-number matching.", "Mentions specific implementation details or heuristics such as: Cohere Rerank, BGE-Reranker."], "negative_evidence": ["Relies purely on naive vector similarity search top-k and assumes vector distance perfectly correlates with relevance.", "Passes hundreds of raw retrieved chunks directly to the LLM generator without re-ranking, wasting tokens and introducing distraction."], "partial_credit": ["Mentions re-ranking or hybrid search, but does not explain query transformation techniques (e.g., HyDE) or rank fusion algorithms (e.g., RRF)."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'How do you enforce permissions with metadata filtering in a single vector index (document-level access control)?', '{"required_evidence": ["Explains storing authorization metadata directly inside the vector payload metadata for each chunk.", "Differentiates pre-filtering(filtering vectors by metadata before or during ANN graph traversal) from post-filtering(filtering after top-k retrieval), explaining why pre-filtering avoids empty or truncated results when users lack access to top items.", "Details query-time security context injection: extracting validated permissions from verified authentication tokens(JWT claims) on the backend and injecting them into the search filter clause, preventing client-side filter tampering."], "supporting_evidence": ["Discusses index partitioning trade-offs: single multi-tenant index with metadata filtering vs dedicated namespaces or isolated indices per tenant.", "Addresses caching challenges: handling cache invalidation when document access control lists are updated while vector embeddings remain unchanged.", "Mentions specific implementation details or heuristics such as: document ACLs, permitted user IDs, role/group tags, and tenant IDs."], "negative_evidence": ["Recommends post-filtering on small top-k results, which can return zero results if top matches belong to unauthorized users.", "Allows the client or frontend to provide unvalidated metadata filters, allowing unauthorized privilege escalation."], "partial_credit": ["Mentions adding user or group IDs to vector metadata, but does not distinguish pre-filtering from post-filtering or explain server-side security context injection."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'How do you design source citations for traceability?', '{"required_evidence": ["Describes chunk-level metadata tracking: associating unique document identifiers, section headers, chunk IDs, page numbers, or URI anchors with every retrieved passage passed to the context.", "Explains citation prompting and structured generation: constraining the LLM to output inline citation tags linked to specific context items using JSON schemas or tool calls.", "Details post-generation citation validation: verifying that cited claims are factually entailed by the referenced chunk using string matching, Natural Language Inference(NLI), or automated attribution checks."], "supporting_evidence": ["Discusses UI/UX integration: rendering interactive citation badges that highlight the exact bounding box or passage in a side-by-side document viewer upon user click.", "Mentions attribution benchmarks such as ALCE or Ragas citation precision and recall metrics.", "Mentions specific implementation details or heuristics such as: `[^1]`, `[Doc-123, p.4]`."], "negative_evidence": ["Assumes LLMs will inherently provide accurate, hallucination-free citations without structured chunk IDs and prompt constraints.", "Suggests citing only top-level document titles without granular page or paragraph provenance."], "partial_credit": ["Explains prompting the model to list sources at the end of the response, but lacks structured chunk metadata mapping or automated attribution verification."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'RAG & Document Processing', 'MEDIUM', 'SPECIFIC', 180, 'How do you extract, structure and store document metadata consistently?', '{"required_evidence": ["Describes a multi-layered metadata taxonomy: extracting system metadata(file size, hash, timestamps, MIME type), structural metadata(page count, headers, reading order), and semantic metadata(topics, entities, summary).", "Explains schema validation and enforcement: using strict schema validation libraries paired with LLM structured outputs(function calling / instructor) to guarantee type consistency.", "Details persistence architecture: storing primary structured metadata in relational or document databases with transactional integrity, while projecting searchable filter fields into the vector store."], "supporting_evidence": ["Discusses deduplication and idempotency: hashing content (e.g., SHA-256) to prevent redundant extraction and re-processing of unchanged files.", "Mentions handling schema evolution through versioned schemas and database migrations.", "Mentions specific implementation details or heuristics such as: Pydantic, JSON Schema.", "Mentions specific implementation details or heuristics such as: PostgreSQL, MongoDB."], "negative_evidence": ["Stores raw unstructured text directly in vector stores without separate structured metadata tracking or validation.", "Permits arbitrary, unvalidated metadata fields, resulting in schema drift and broken downstream query filters."], "partial_credit": ["Lists types of metadata to extract, but does not provide a concrete validation mechanism (schemas) or dual storage pattern."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'RAG & Document Processing', 'MEDIUM', 'SPECIFIC', 180, 'How do you normalize unstructured sources (PDFs, wikis, HTML, manuals)?', '{"required_evidence": ["Defines a canonical intermediate representation(IR) such as Markdown, structured JSON AST, or HTML to which all heterogeneous source formats are converted.", "Describes source-specific normalization pipelines: stripping web boilerplate(navbars, scripts, ads) using DOM parsers, reconstructing PDF reading order and removing running headers/footers, and parsing wiki syntax.", "Details text sanitization: applying Unicode normalization(NFKC/NFC), collapsing excessive whitespace, standardizing character encodings, and stripping non-printable control characters."], "supporting_evidence": ["Mentions unified document processing frameworks such as Unstructured.io, Apache Tika, or Docling that standardize diverse inputs into common document objects.", "Discusses preserving semantic document hierarchies (H1-H6 tags, lists, tables) across all converted formats.", "Mentions specific implementation details or heuristics such as: UTF-8."], "negative_evidence": ["Suggests using simple raw regex on PDF binary streams or raw HTML, stripping all structural formatting, tables, and links.", "Treats all document formats identically without format-specific extraction engines."], "partial_credit": ["Mentions stripping HTML tags and extracting text from PDFs, but lacks discussion of a unified canonical representation (IR) or text sanitization standards."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'RAG & Document Processing', 'MEDIUM', 'SPECIFIC', 180, 'How do you handle tables, multi-column layouts and images in PDFs without losing context?', '{"required_evidence": ["Explains layout analysis / vision-based document parsing to accurately determine reading order across multi-column pages and prevent text interleaving.", "Describes table extraction and representation: detecting table boundaries, reconstructing row/column spanning cells, and serializing tables into structured formats(Markdown, HTML `<table>`, or JSON key-value pairs) rather than naive flattened text.", "Details image and diagram processing: extracting embedded figures, generating descriptive contextual captions using Vision LLMs, and embedding these summaries adjacent to surrounding narrative text."], "supporting_evidence": ["Discusses keeping tables as atomic chunks with repeated column headers when splitting large tables across multiple chunks.", "Mentions combining programmatic text extraction for native digital text with vision OCR fallbacks for embedded charts.", "Mentions specific implementation details or heuristics such as: LayoutLM, Docling, YOLO document detectors, or Vision-LLMs."], "negative_evidence": ["Advocates standard line-by-line programmatic text extractors (like basic PyPDF2) that read horizontally across multi-column text, corrupting the reading order.", "Discards tables and diagrams or treats them as flat unstructured whitespace strings."], "partial_credit": ["Acknowledges that multi-column layouts and tables get corrupted by basic extractors and mentions using OCR or Markdown tables, but does not detail layout detection or image captioning pipelines."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'RAG & Document Processing', 'MEDIUM', 'SPECIFIC', 180, 'How do you compare extraction tools (Tika, Textract, Docling) and choose one?', '{"required_evidence": ["Compares tool characteristics: Apache Tika(fast, low-cost, open-source, broad format support, basic text extraction, weak on complex layouts/tables), the appropriate framework/tool Textract(managed cloud OCR, high accuracy on complex forms, tables, key-value pairs, costly at high scale), Docling(modern open-source AI layout parser, strong on complex layouts and tables, outputs structured Markdown/JSON).", "Defines structured evaluation criteria: parsing accuracy on tables and complex multi-column layouts, processing latency and throughput, total cost per page at scale, and data privacy / on-premise deployment requirements.", "Recommends a tiered hybrid extraction architecture: utilizing lightweight tools(Tika/PyMuPDF) for straightforward native digital text, escalating complex layouts, forms, and scans to Docling or Textract."], "supporting_evidence": ["Mentions other modern document extraction tools such as Unstructured, Marker, or Azure AI Document Intelligence.", "Discusses benchmarking extraction quality using a representative golden test set of domain documents.", "Specifically mentions AWS."], "negative_evidence": ["Claims Apache Tika provides deep-learning based table parsing and complex layout understanding out of the box.", "Selects an expensive cloud API for all documents without evaluating latency, volume cost, or enterprise privacy constraints."], "partial_credit": ["Describes what each tool is generally used for, but fails to provide structured trade-off dimensions (cost, accuracy, latency, privacy) or a decision framework."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 180, 'How do you scale and parallelize ingestion (distributed, async, event-driven)?', '{"required_evidence": ["Architects an event-driven decoupled pipeline: document uploads trigger cloud object storage notifications published to distributed message queues.", "Explains distributed worker pools and autoscaling: using containerized workers that consume ingestion tasks asynchronously, chunking and embedding documents in parallel.", "Details fault tolerance and rate limiting: implementing Dead Letter Queues(DLQs), exponential backoff retries, idempotent writes via document content hashing, and token-bucket rate limiting against external embedding/LLM APIs."], "supporting_evidence": ["Discusses batching vector upsert operations and embedding generation requests to maximize throughput and minimize network round trips.", "Mentions workflow orchestrators like Apache Airflow, Temporal, or AWS Step Functions for managing multi-stage DAGs.", "Mentions specific implementation details or heuristics such as: S3 Event Notifications.", "Mentions specific implementation details or heuristics such as: AWS SQS, Apache Kafka, RabbitMQ."], "negative_evidence": ["Proposes processing large document uploads synchronously within the HTTP web server request-response lifecycle.", "Fails to provide mechanisms for retry backoff, dead-letter queues, or rate-limiting against downstream vector databases and AI APIs."], "partial_credit": ["Describes using a message queue and multiple workers, but neglects idempotency, dead-letter queues, backpressure, or rate-limiting."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'What file validation (type, size, format) and safe-upload practices do you use?', '{"required_evidence": ["Explains deep file validation: checking MIME types and verifying magic bytes / file signatures rather than trusting client-provided file extensions; enforcing strict file size caps and archive decompression ratio limits(zip bomb defense).", "Describes safe upload architecture: issuing time-limited pre-signed URLs allowing clients to upload directly to an isolated staging storage bucket, bypassing application servers.", "Details security scanning and sanitization: running automated antivirus/malware scanners, sanitizing filenames to prevent path traversal(`../`), and stripping embedded macros, active scripts, or executables."], "supporting_evidence": ["Mentions PDF-specific sanitization: disabling embedded JavaScript execution and stripping active form triggers during parsing.", "Discusses isolating ingestion worker environments in sandboxed, non-root ephemeral containers with restricted network egress.", "Mentions specific implementation details or heuristics such as: S3 pre-signed PUT.", "Mentions specific implementation details or heuristics such as: ClamAV, AWS GuardDuty."], "negative_evidence": ["Relies exclusively on filename extension strings (e.g., checking if filename ends with `.pdf`) to validate file types.", "Saves uploaded files directly into public web-accessible server directories without sanitization or scanning."], "partial_credit": ["Mentions checking file size and extension and using antivirus, but lacks magic byte inspection, path traversal protection, or pre-signed upload patterns."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'RAG & Document Processing', 'MEDIUM', 'SPECIFIC', 180, 'How do you adapt OCR to new form types, such as new tax forms?', '{"required_evidence": ["Explains template and coordinate registration: identifying anchor points, fiducial markers, or standardized text landmarks to align, deskew, and normalize document coordinates.", "Describes layout-aware extraction models: leveraging multimodal layout models or Vision-LLMs with few-shot visual examples and strict JSON schema definitions for key-value extraction.", "Details Human-in-the-Loop(HITL) active learning: routing low-confidence field extractions to human reviewers, capturing corrections, and using them to fine-tune extraction models or update spatial heuristic rules."], "supporting_evidence": ["Discusses synthetic data generation: programmatically populating blank form templates with synthetic taxpayer data to train models prior to receiving live production forms.", "Mentions graph neural networks or spatial adjacency heuristics for matching form labels to corresponding value boxes.", "Mentions specific implementation details or heuristics such as: IRS Form numbers, tax year labels.", "Mentions specific implementation details or heuristics such as: LayoutLMv3, Donut."], "negative_evidence": ["Assumes hardcoded static pixel coordinates will reliably extract fields across diverse printer margins, scanner skews, and user resolutions.", "Claims standard flat OCR without layout understanding or post-processing can parse complex multi-box forms reliably."], "partial_credit": ["Mentions training an OCR model or writing new regex rules for the new form, but lacks discussion of layout alignment, multimodal models, or HITL feedback loops."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'HARD', 'SPECIFIC', 240, 'Design a contract-analysis system (clauses, template comparison, risk highlighting).', '{"required_evidence": ["Architects core system modules: Document Ingestion/OCR, Clause Segmentation & Classification(categorizing clauses into standard types: Indemnification, Liability, Governing Law), Template Diffing Engine, and Risk Highlighting Engine.", "Explains semantic template comparison and redlining: comparing extracted clauses against approved organizational playbooks using semantic similarity and token-level diff algorithms to identify deviations.", "Describes risk scoring and highlighting logic: evaluating clauses against predefined risk rubrics, assigning severity tags(Low/Medium/High), and generating recommended fallback language."], "supporting_evidence": ["Addresses enterprise privacy and security: tenant data isolation, zero-retention agreements with external LLM APIs, and comprehensive audit logging.", "Describes a reviewer UI with side-by-side redline diffs and one-click clause replacement options.", "Mentions specific implementation details or heuristics such as: Myers diff / Levenshtein.", "Mentions specific implementation details or heuristics such as: unlimited liability caps, unilateral termination clauses."], "negative_evidence": ["Suggests dumping an entire 100-page contract into a single unconstrained prompt asking ''Is this contract risky?'' without clause segmentation or grounded rubrics.", "Relies purely on exact string matching for comparison, which fails when clauses are legally identical but rephrased."], "partial_credit": ["Mentions extracting clauses with LLMs and comparing to a baseline template, but lacks discussion of clause segmentation taxonomy, risk rubric evaluation, or redline mechanics."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'RAG & Document Processing', 'MEDIUM', 'SPECIFIC', 180, 'What components does document understanding with risk scoring need?', '{"required_evidence": ["Identifies document ingestion and layout decomposition: OCR and structural parsing components(headers, tables, paragraphs, clauses) that convert raw files into structured document trees.", "Identifies the risk extraction and scoring engine: entity/attribute extractors, deterministic compliance rule checkers, and statistical/LLM risk classifiers that map findings to a weighted multi-factor risk scoring formula.", "Identifies auditability, provenance, and triage infrastructure: linking every risk flag directly to exact document coordinates/snippets, and providing a Human-in-the-Loop review queue for automated escalation."], "supporting_evidence": ["Discusses calibration of risk thresholds to balance precision and recall, minimizing alert fatigue while preventing missed critical risks.", "Mentions tracking concept drift and maintaining version-controlled risk policy definition files."], "negative_evidence": ["Treats risk scoring as a black-box LLM prompt that outputs an ungrounded score from 1 to 10 without structured decomposition or defensible criteria.", "Omits provenance tracking and evidence attribution, preventing users from verifying flagged risks."], "partial_credit": ["Lists several components (OCR, LLM, database, UI) but fails to explain the risk scoring methodology, explainability/provenance, or HITL escalation criteria."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'RAG & Document Processing', 'MEDIUM', 'SPECIFIC', 180, 'How do you keep answers accurate for complex technical manuals?', '{"required_evidence": ["Explains structural and syntax-aware chunking: chunking technical manuals by semantic hierarchy(sections, procedural steps, caution/warning callouts, schematics) rather than arbitrary token boundaries.", "Details precision retrieval optimizations: hybrid search combining the appropriate framework/tool(critical for exact part numbers, model codes, and error codes) and dense vector retrieval, followed by cross-encoder re-ranking.", "Enforces strict grounding and verification constraints: prompting LLMs to answer strictly from retrieved snippets, penalizing extrapolation, and verifying step-by-step procedures against cited sections."], "supporting_evidence": ["Discusses version-controlled indexing: isolating product manuals by exact hardware/software/firmware release version to prevent cross-version hallucinations.", "Mentions automated self-correction reflection loops where a validator model verifies the response against technical manual constraints before output.", "Specifically mentions BM25."], "negative_evidence": ["Relies exclusively on dense vector retrieval, which frequently fails to retrieve exact alphanumeric model codes or part numbers.", "Allows the model to guess or generate plausible-sounding troubleshooting steps not explicitly documented in the manual."], "partial_credit": ["Mentions chunking manuals and using RAG with citations, but omits hybrid retrieval for exact part numbers, structural chunking (warnings/steps), or versioning."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'How do you extend a text system to multimodal inputs, and how do text and voice assistants differ?', '{"required_evidence": ["Explains extending text architectures to multimodal: integrating vision encoders or native multimodal LLMs that project visual/audio tokens into a shared semantic embedding space.", "Contrasts latency and streaming requirements: voice assistants require strict sub-second end-to-end latency necessitating streaming ASR, streaming LLM inference, and streaming TTS, whereas text assistants can tolerate multi-second batch responses.", "Highlights conversational differences: voice interfaces require concise spoken language(avoiding markdown tables, code blocks, long URLs), robust turn-taking and barge-in(interruption) detection, and resilience to ASR phonetic transcription errors."], "supporting_evidence": ["Discusses native end-to-end speech-to-speech multimodal models (e.g., frontier model voice mode) that preserve prosody, emotional inflection, and tone.", "Mentions Voice Activity Detection (VAD) and acoustic noise suppression algorithms.", "Mentions specific implementation details or heuristics such as: CLIP, ViT.", "Mentions specific implementation details or heuristics such as: <300-500ms."], "negative_evidence": ["Assumes voice assistants are merely text chatbots wrapped with standard batch TTS, ignoring latency budgets, barge-in, and concise formatting requirements."], "partial_credit": ["Notes that voice uses speech-to-text and text-to-speech, and images use multimodal models, but fails to discuss latency constraints, barge-in, or output format adaptation."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'RAG & Document Processing', 'MEDIUM', 'SPECIFIC', 180, 'How do you use historical support tickets to build a support assistant that also reduces ticket creation?', '{"required_evidence": ["Details ticket data cleaning and knowledge distillation: filtering resolved tickets, removing PII, deduplicating repetitive issues, and synthesizing verified Q&A knowledge base articles rather than indexing raw, chaotic agent-customer banter.", "Architects a proactive self-service deflection mechanism: integrating the assistant at the point of ticket creation to resolve queries immediately before submission.", "Defines tracking and deflection metrics: monitoring deflection rate(ticket form abandoned after viewing suggestion), resolution rate without human escalation, CSAT, and post-assistant ticket creation volume."], "supporting_evidence": ["Mentions clustering unresolved tickets to identify documentation gaps for product/technical writing teams.", "Discusses human-agent copilot handoff: if deflection fails, pre-populating the ticket with conversation summary and attempted troubleshooting steps.", "Mentions specific implementation details or heuristics such as: inline as user types ticket subject/description."], "negative_evidence": ["Proposes indexing raw historical tickets directly into a RAG vector store without cleaning, causing the assistant to replicate outdated advice, PII leaks, or incorrect resolutions.", "Focuses only on answering user queries without analyzing how to prevent or intercept ticket submission."], "partial_credit": ["Describes using tickets as training/RAG data to answer questions, but misses data curation (PII, filtering bad resolutions) and deflection mechanisms at the point of entry."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 180, 'How would you pass data from S3 to an LLM for fine-tuning or inference?', '{"required_evidence": ["Differentiates fine-tuning from inference: For fine-tuning, training data is formatted and ingested directly from S3 paths via SageMaker Training Jobs(using File Mode/Fast File Mode) or Bedrock Custom Model jobs.", "Explains real-time inference workflows: fetching raw documents from S3 via pre-signed URLs or streaming in memory, chunking the content, and injecting relevant excerpts into the LLM prompt context window.", "Explains RAG and automated ingestion: using S3 as a data source for vector indexing for semantic search retrieval before LLM invocation.", "Discusses batch inference: utilizing asynchronous batch processing jobs that read input manifests from S3 and output completions to an S3 destination."], "supporting_evidence": ["Mentions high-throughput data access optimizations like Amazon FSx for Lustre linked to S3 for distributed multi-GPU model training.", "Highlights IAM permissions (least-privilege S3 bucket policies and instance profiles) ensuring secure read access for inference containers.", "Mentions specific implementation details or heuristics such as: JSONL instruction datasets.", "Mentions specific implementation details or heuristics such as: Bedrock Knowledge Bases syncing S3 buckets to vector stores."], "negative_evidence": ["Suggests uploading the entire unstructured contents of multi-gigabyte S3 files directly into a single real-time LLM prompt without chunking or retrieval.", "Assumes that fine-tuning an LLM requires uploading raw unformatted PDF or Word documents directly to model weights without preprocessing into structured text formats."], "partial_credit": ["Explains how to download a file from S3 using boto3 and send its text to an API, but fails to distinguish fine-tuning data pipelines from RAG/batch inference."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'LLM Evaluation & Benchmarking', 'MEDIUM', 'SPECIFIC', 180, 'What is a golden dataset? How do you build one (coverage, edge cases, format and scale, domain-expert involvement), and how do you validate labels and define relevance?', '{"required_evidence": ["Defines a golden dataset: a curated, high-quality, ground-truth benchmark of representative inputs and verified reference outputs used to reliably evaluate model quality, regressions, and performance.", "Details construction strategy: sampling production distributions across diverse user intents, intentionally incorporating boundary/edge cases(adversarial prompts, malformed inputs, out-of-domain queries), and establishing standard structured formats.", "Explains domain-expert involvement and label validation: creating clear annotation guidelines, calculating inter-annotator agreement(Cohen''s/Fleiss'' Kappa), resolving discrepancies via consensus, and establishing strict grading criteria for relevance."], "supporting_evidence": ["Discusses dataset maintenance: dataset versioning, preventing test-set contamination, and continuous refreshment based on production drift.", "Mentions synthetic data generation paired with human expert verification to scale sample size.", "Mentions specific implementation details or heuristics such as: query, context, expected answer, grading rubric."], "negative_evidence": ["Assumes an automated LLM generator can create a golden dataset without human validation or domain expert oversight.", "Believes a golden dataset is static and never needs updates or edge-case expansions."], "partial_credit": ["Defines what a golden dataset is and mentions having experts label examples, but fails to explain inter-annotator agreement, edge-case coverage, or formal label validation."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you build a full evaluation pipeline, and how do you know it delivers the expected quality?', '{"required_evidence": ["Details components of an end-to-end evaluation pipeline: curated golden datasets(covering core tasks and edge cases), component-level metrics(retrieval recall/precision, generation faithfulness/relevance), and automated evaluation runners.", "Explains offline vs online evaluation: offline evaluation gates pull requests/deployments via CI/CD, while online evaluation monitors real user feedback(thumbs up/down, edit distance, acceptance rate) and live telemetry.", "Details calibration against ground truth: measuring statistical correlation between automated evaluator scores and human expert ratings to ensure the pipeline is trustworthy."], "supporting_evidence": ["Discusses synthetic test generation pipelines to continually expand golden datasets.", "Mentions shadow deployments (dark traffic) and A/B testing to compare candidate model versions against production baselines.", "Mentions specific implementation details or heuristics such as: Cohen''s Kappa, Spearman correlation."], "negative_evidence": ["Relies exclusively on ad-hoc manual prompt testing in a playground without metrics, golden datasets, or CI/CD gating."], "partial_credit": ["Describes using a golden dataset and an evaluation tool, but does not explain how to validate the judge''s quality or integrate online feedback."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'LLM Evaluation & Benchmarking', 'MEDIUM', 'SPECIFIC', 180, 'How do you measure faithfulness, relevance, toxicity and bias, and what actions follow low scores?', '{"required_evidence": ["Defines metrics and measurement techniques: Faithfulness(measuring if claims in generated response are mathematically entailed by retrieved context, using NLI or LLM judges), Relevance(measuring if response directly addresses user query), Toxicity(using specialized classification models like Perspective API or Llama Guard), and Bias(demographic parity, counterfactual sentiment testing across protected attributes).", "Details immediate runtime remediation actions: response suppression/fallback message, dynamic re-prompting with stricter grounding, or escalation to human review.", "Details systemic offline remediation actions: fine-tuning retrieval chunking/re-ranking(for low faithfulness/relevance), updating system prompts with negative constraints, and retraining/filtering fine-tuning datasets."], "supporting_evidence": ["Mentions guardrail frameworks like NeMo Guardrails or Guardrails AI to block toxic/unfaithful responses before streaming to user.", "Discusses tracking metric trends on observability dashboards (Langfuse, Arize, Datadog)."], "negative_evidence": ["Conflates faithfulness with relevance (e.g., assuming an answer is faithful just because it sounds helpful and relevant to the user).", "Has no concrete remediation plan other than ''retraining the whole model from scratch''."], "partial_credit": ["Defines each metric accurately, but provides vague or incomplete runtime/systemic remediation actions for low scores."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'LLM Evaluation & Benchmarking', 'MEDIUM', 'SPECIFIC', 180, 'How is a confidence score calculated, and how do you set a threshold such as 0.9?', '{"required_evidence": ["Explains methods to calculate confidence scores: token-level probabilities(perplexity, average log-likelihood of generated tokens, minimum token probability), ensemble self-consistency / semantic entropy across multiple sampled outputs, or specialized calibrator models.", "Explains why raw LLM softmax probabilities are notoriously overconfident and poorly calibrated, requiring calibration techniques.", "Details the methodology for setting a threshold : conducting ROC/PR curve analysis on a validation dataset, evaluating the business cost of false positives(hallucinations) vs false negatives(unnecessary rejections/escalations) to select the optimal operating point."], "supporting_evidence": ["Mentions semantic entropy (sampling multiple answers at temperature > 0 and clustering them by meaning to evaluate semantic variance).", "Discusses conformal prediction to establish rigorous mathematical coverage guarantees at given confidence levels.", "Mentions specific implementation details or heuristics such as: Platt scaling, temperature scaling, isotonic regression.", "Mentions specific implementation details or heuristics such as: like 0.9."], "negative_evidence": ["Suggests simply asking the LLM in the prompt ''On a scale of 0 to 1, how confident are you?'' and trusting that raw self-reported number.", "Picks 0.9 arbitrarily without empirical validation on an evaluation dataset or consideration of business trade-offs."], "partial_credit": ["Mentions using token probabilities or self-consistency, but fails to discuss model miscalibration or how to empirically determine the threshold via ROC/precision-recall curves."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'LLM Evaluation & Benchmarking', 'MEDIUM', 'SPECIFIC', 180, 'How do you prove a change really improved efficiency?', '{"required_evidence": ["Explains rigorous experimental design: conducting randomized controlled trials(A/B testing) or interleaved testing between control and treatment groups, holding external variables constant.", "Defines concrete efficiency metrics: system efficiency and user/operational efficiency(handle time, tasks completed per hour, time-to-resolution, deflection rate).", "Details statistical hypothesis testing: verifying statistical significance using t-tests or Mann-Whitney U tests to ensure gains are not random variance."], "supporting_evidence": ["Addresses counter-metrics and guardrail metrics: ensuring efficiency gains didn''t degrade quality, CSAT, or accuracy (e.g., faster responses that hallucinate).", "Discusses Difference-in-Differences (DiD) or synthetic controls when randomized A/B testing is not feasible.", "Mentions specific implementation details or heuristics such as: p95/p99 latency, compute/token cost per query, server utilization.", "Mentions specific implementation details or heuristics such as: p-value < 0.05, confidence intervals."], "negative_evidence": ["Compares pre-launch and post-launch numbers without a control group, ignoring external seasonalities and marketing campaigns.", "Declares victory based on a tiny non-statistically significant sample or a vanity metric."], "partial_credit": ["Mentions running an A/B test and measuring response time or user speed, but omits statistical significance testing, guardrail metrics, or hypothesis formulation."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'CI/CD & Automation', 'MEDIUM', 'SPECIFIC', 180, 'How do you test AI and full-stack systems (unit, integration, end-to-end, contract), including BLEU and automated quality evaluation?', '{"required_evidence": ["Maps testing pyramid to AI systems: Unit tests(deterministic functions, schema parsers, prompt template formatting), Integration tests(vector DB connections, API calls with mocked LLM responses, database writes), End-to-End tests(complete pipeline execution from user input to frontend render), and Contract tests(API schemas, structured JSON validation, provider tool definitions).", "Explains automated AI quality evaluation: using evaluation suites(evals) running on golden datasets during CI/CD to measure semantic similarity, faithfulness, and groundedness.", "Critiques BLEU and n-gram metrics: explains BLEU''s limitation in generative AI(over-reliance on exact n-gram overlap, inability to capture semantic equivalence or factual truth) and why model-based evals(LLM-as-a-judge, embeddings) are preferred."], "supporting_evidence": ["Discusses test fixtures and deterministic caching (e.g., VCR.py for recorded LLM HTTP responses) to make CI builds fast and inexpensive.", "Mentions synthetic adversarial tests (fuzzing prompts for prompt injection, jailbreaks, and format breaking)."], "negative_evidence": ["Suggests calling live non-deterministic third-party LLMs on every unit test run in CI without mocking.", "Relies exclusively on BLEU score as the sole metric for assessing complex AI conversational quality."], "partial_credit": ["Describes standard unit, integration, and E2E tests and mentions BLEU, but lacks AI-specific CI evaluation (evals on golden sets) or fails to critique BLEU''s limitations."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How do you measure adoption and ROI of internal AI tools and developer productivity?', '{"required_evidence": ["Defines adoption metrics: Daily/Monthly Active Users(DAU/MAU), tool usage frequency, code/text acceptance rate, and workflow retention cohorts.", "Defines productivity and ROI metrics: engineering velocity(PR cycle time, lead time for changes, deployment frequency, time spent per task) combined with quality guardrails(change failure rate, defect density, MTTR).", "Calculates financial ROI: comparing estimated engineering hours saved multiplied by developer cost against infrastructure, tooling, and LLM API token expenses."], "supporting_evidence": ["References established developer productivity frameworks like SPACE (Satisfaction, Performance, Activity, Communication, Efficiency) and DORA metrics.", "Warns against vanity activity metrics like pure lines of code (LOC) generated.", "Mentions specific implementation details or heuristics such as: % of AI-suggested completions retained without edit."], "negative_evidence": ["Measures developer productivity solely by raw lines of AI-generated code written or number of commits.", "Claims ROI is purely qualitative and cannot be measured with financial or time-based metrics."], "partial_credit": ["Mentions tracking active users and time saved, but omits code acceptance rate, DORA/quality guardrail metrics, or financial ROI calculation."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 180, 'If a parallel task fails, how does checkpointing preserve state, where is it stored, and how do you trigger a retry?', '{"required_evidence": ["Explains checkpointing mechanics: saving an immutable snapshot of graph/workflow state and thread history at every step(super-step) boundary, ensuring uncorrupted state is preserved prior to failure.", "Identifies storage backends: persistent state stores such as the appropriate framework/tool, the appropriate framework/tool, DynamoDB, or cloud blob storage with ACID or atomic transaction guarantees, keyed by thread_id and checkpoint_id.", "Details retry mechanisms: resuming execution directly from the last valid checkpoint(time-travel/replay), executing exponential backoff retries on the failed branch, or routing the failure to an error recovery/compensation node without rerunning completed parallel tasks."], "supporting_evidence": ["Discusses checkpoint compaction and retention policies to manage database storage growth.", "Mentions human-in-the-loop intervention at checkpoint: modifying the checkpoint state before replaying.", "Specifically mentions Redis.", "Specifically mentions PostgreSQL."], "negative_evidence": ["Assumes checkpointing stores state in ephemeral in-memory worker memory, which vanishes if the pod/process crashes.", "Suggests restarting the entire parallel workflow from step 0 on any single branch failure."], "partial_credit": ["Explains that checkpointing saves progress to a database so the workflow can resume, but lacks detail on super-step boundaries, storage keys (thread_id), or partial parallel branch retry."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 180, 'How do you handle context-window limits: token estimation, summarization, truncation, and safeguards against overflow?', '{"required_evidence": ["Token estimation: utilizes model-specific byte-pair tokenizers to compute exact token counts rather than inaccurate character or word heuristics before calling APIs.", "Context management techniques: 1. Truncation: sliding-window truncation preserving system instructions and dropping oldest dialogue turns or lower-ranked retrieval chunks. 2. Summarization: recursive or progressive summarization compressing older turns into a concise running abstract. 3. Selective chunk pruning: filtering retrieval context based on relevance score thresholds.", "Safeguards against overflow: implementing strict token budget allocation(reserving fixed token margins for system prompt, dynamic context, user query, and max completion tokens); wrapping API calls in try-catch handlers to catch context-length errors and trigger automated fallback cascades."], "supporting_evidence": ["Mentions Map-Reduce and Refine chaining strategies for summarizing documents that exceed the total context window.", "Explains the trade-off of summarization: adds latency and extra LLM cost while risking loss of fine-grained factual details.", "Mentions specific implementation details or heuristics such as: tiktoken for OpenAI, Hugging Face AutoTokenizer."], "negative_evidence": ["Uses basic character length (len(text) // 4) as a production safeguard without error handling for token spikes in code or non-English text.", "Truncates from the top of the prompt, accidentally deleting the system instructions and safety rules."], "partial_credit": ["Mentions counting tokens with tiktoken and cutting off old messages or summarizing them, but lacks details on token budget allocation or overflow error handling."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Concurrency & Parallelism', 'MEDIUM', 'SPECIFIC', 180, 'How would you stream responses, and how do you handle guardrails and disconnections during streaming? Why streaming over WebSockets?', '{"required_evidence": ["Explains streaming mechanics: Server-Sent Events(SSE) vs. WebSockets, noting SSE is unidirectional and simpler over HTTP/2, while WebSockets allow full-duplex interactive multi-modal / client interruptions.", "Details inline guardrail inspection: buffering chunks into rolling window token buffers or semantic sentences to evaluate content policy before flushing to the client, or running speculative async guardrails with revocation.", "Explains disconnection handling: tracking connection state(client heartbeat/ping-pong), canceling upstream LLM generation via AbortController/CancellationToken to conserve inference tokens, and persisting partial state to allow stream resumption."], "supporting_evidence": ["Compares SSE advantages (native browser EventSource, HTTP status codes, standard CDN proxying) versus WebSocket advantages (bidirectional audio/speech, low overhead framing).", "Explains UI containment strategies for late guardrail triggers: sending a tombstone event to wipe or replace toxic text rendered on the client."], "negative_evidence": ["Claims streaming requires buffering the entire model output before running any guardrails, completely negating the latency benefit of streaming.", "Ignores backend resource exhaustion from orphaned LLM generations when clients disconnect."], "partial_credit": ["Explains SSE or WebSockets for streaming text chunks, but fails to address chunk-level guardrail evaluation or disconnect cleanup."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'With 50,000 users on a horizontally scaled system, how do you track which queries went where and provide explainability?', '{"required_evidence": ["Explains distributed tracing using W3C Trace Context / OpenTelemetry standards, injecting and propagating correlation IDs(trace_id, span_id, request_id) across load balancers, API gateways, microservices, and LLM calls.", "Details centralized logging and telemetry infrastructure: streaming structured logs and trace spans to systems like Jaeger, Tempo, the appropriate framework/tool, or Datadog with user, session, and route tags.", "Addresses LLM explainability and auditability: logging prompt templates, retrieved document IDs, tool execution arguments, model version, temperature, and token usage alongside the trace ID."], "supporting_evidence": ["Discusses high-volume sampling strategies (head-based vs. tail-based sampling) to manage the storage and cost overhead of tracing 50,000 concurrent users.", "Mentions LLM observability frameworks (Langfuse, Arize Phoenix, OpenInference) for deep trajectory inspection and debuggability.", "Specifically mentions Elasticsearch."], "negative_evidence": ["Suggests relying on local log files stored across container instances without centralized aggregation or trace correlation IDs.", "Recommends logging full raw user prompts and responses containing unmasked PII directly to unencrypted plain-text logs."], "partial_credit": ["Mentions adding a unique ID to logs and using ELK or Datadog, but does not detail distributed context propagation, sampling strategies, or LLM-specific explainability traces."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Concurrency & Parallelism', 'MEDIUM', 'SPECIFIC', 180, 'Why use timeouts versus event-based completion for long tasks, and polling versus webhooks for PR detection?', '{"required_evidence": ["Compares timeouts vs. event-based completion: timeouts are failure-handling safety nets to prevent hanging resources, whereas event-based completion(pub/sub, message queues, callbacks) enables decoupled, reactive notification the moment work finishes.", "Compares polling vs. webhooks for PR detection: webhooks provide instant, push-based notification with low resource consumption, whereas polling involves repeated pull queries that introduce latency and API rate-limit waste.", "Discusses trade-offs and edge cases: webhooks require public endpoints and retry handling for delivery failures, whereas polling serves as an idempotent backup/reconciliation mechanism when webhooks fail or firewall constraints exist."], "supporting_evidence": ["Mentions exponential backoff with jitter when polling is unavoidable, and HMAC signature verification for secure webhook consumption.", "Explains the ''webhook with polling fallback/reconciliation'' architecture for mission-critical reliability (e.g., missed GitHub events)."], "negative_evidence": ["Assumes tight polling loops (e.g., every 50ms) are superior to event-driven architectures for long-running workflows.", "Relies solely on timeouts as the primary completion trigger rather than an error/deadlock breaker."], "partial_credit": ["Correctly contrasts polling and webhooks, but fails to articulate why timeouts and event-based mechanisms should be used together for long tasks."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'HARD', 'SPECIFIC', 240, 'Design a chat system that generates BOMs, and how it handles updates versus new BOMs.', '{"required_evidence": ["Designs system architecture: conversational interface, LLM parser/extractor with strict JSON Schema output, catalog/ERP integration(part number validation, inventory checks), and relational/document storage for BOM records.", "Details state management and intent detection: classifying whether a user prompt requests a brand-new Bill of Materials(BOM) or modifies an existing one by maintaining active session context or referencing a bom_id.", "Explains differential update mechanics: computing diffs(add/remove/modify part line items, adjust quantities), enforcing versioning(immutable semantic versions or change logs), and recalculating hierarchical totals/dependencies."], "supporting_evidence": ["Mentions optimistic locking or etags on BOM records to prevent concurrent modification conflicts during chat updates.", "Discusses validation workflows: ensuring BOM components adhere to manufacturing rules, obsolescence status, and minimum order quantities."], "negative_evidence": ["Overwrites existing BOM records completely on every update without version history, diff calculation, or change auditing.", "Generates unstructured plain text BOMs without validated schema enforcement against product master catalogs."], "partial_credit": ["Outlines an LLM chat prompt that outputs parts lists, but lacks system design depth on versioning, diff logic, ERP integration, or concurrent edit safety."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'HARD', 'SPECIFIC', 240, 'Design an assistant for a betting or transactional app.', '{"required_evidence": ["Details strict separation of concerns: conversational understanding/intent extraction must never execute financial or betting transactions without an intermediate deterministic validation and execution service.", "Implements transactional guarantees: idempotency keys, atomic database operations, two-phase commit or transactional outbox pattern, and balance/limit checks before bet placement.", "Incorporates regulatory and responsible gambling guardrails: explicit two-step user confirmation, wager limit enforcement, self-exclusion checks, geofencing validation, and audit logging."], "supporting_evidence": ["Mentions handling real-time betting odds volatility (slippage checks and odds acceptance thresholds prior to trade execution).", "Discusses PCI-DSS / gambling commission compliance, secure audit trails, and strict data masking of sensitive payment details."], "negative_evidence": ["Allows the LLM to directly alter user account balances or place bets via unconstrained autonomous function execution without verification.", "Ignores idempotency, allowing network retries or repeated prompts to double-bill or place duplicate bets."], "partial_credit": ["Covers intent recognition and basic API calls for placing bets, but ignores transactional integrity, idempotency, and regulatory/responsible gaming guardrails."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'What are guardrails, why implement them at both input (gateway) and output (model) stages, and how do they handle PII, toxicity, tone, off-topic output, compliance and untrusted input?', '{"required_evidence": ["Defines guardrails as programmatic safety filters, classifiers, and heuristics that enforce security, privacy, and organizational policy constraints on LLM systems.", "Justifies two-stage defense-in-depth: input guardrails reject jailbreaks, prompt injections, and untrusted inputs before incurring inference cost; output guardrails catch hallucinations, toxic completions, PII leakage, and off-brand tone generated by the model.", "Explains mechanisms across domains: regex/NER models for PII detection/anonymization, classification models for toxicity/tone, and semantic embedding distance/vector thresholds for off-topic filtering."], "supporting_evidence": ["Discusses latency optimization: running lightweight regex/heuristic checks synchronously while executing heavier classifier models in parallel or asynchronously.", "Details fallbacks and containment: rewriting sanitized inputs, masking PII with reversible pseudo-tokens, and returning safe templated responses upon violations.", "Mentions specific implementation details or heuristics such as: Presidio.", "Mentions specific implementation details or heuristics such as: Llama-Guard."], "negative_evidence": ["Claims guardrails are only needed in the system prompt itself (''system prompt instructions are 100% secure'').", "Assumes input filtering alone is sufficient, ignoring that models can hallucinate toxic or non-compliant text from benign inputs."], "partial_credit": ["Explains that guardrails check for bad words and PII at input and output, but lacks technical depth on specific classifier tools, injection mitigation, or latency architecture."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you detect and mask PII (for example Presidio), and stop a system from revealing PII on request?', '{"required_evidence": ["Explains PII detection mechanisms: combining rule-based pattern matching(regex for SSNs, credit cards, emails) with NLP Named Entity Recognition(NER) models to detect names, addresses, and organizations.", "Details reversible and irreversible masking: replacing sensitive spans with entity placeholders via token mapping or cryptographic hashing, storing mapping tables in secure ephemeral caches if detokenization is required post-response.", "Addresses output-level protection and prompt extraction resistance: output guardrails scanning completions before rendering, and prompt boundaries/system instructions forbidding disclosure of training or retrieval PII."], "supporting_evidence": ["Discusses custom recognizers and context-aware word lists in Presidio to reduce false positives/negatives in domain-specific settings.", "Mentions differential privacy techniques or synthetic data generation during model fine-tuning and retrieval indexing.", "Mentions specific implementation details or heuristics such as: Microsoft Presidio with spaCy/transformers.", "Mentions specific implementation details or heuristics such as: <PERSON_1>, <SSN>."], "negative_evidence": ["Suggests relying solely on LLM prompt instructions like ''please do not mention any private info'' without automated programmatic interception.", "Proposes permanently storing unmasked user PII in cleartext prompt logs for debugging."], "partial_credit": ["Mentions using regex or Presidio to replace sensitive words with asterisks, but misses reversible tokenization, output filtering, and adversarial extraction prevention."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you prevent sensitive data reaching external models while keeping responses contextual?', '{"required_evidence": ["Details pseudonymization / tokenization proxies: intercepting outgoing prompts, replacing sensitive entities with synthetic surrogate tokens, and detokenizing the model''s response before returning it to the user.", "Explains contextual preservation: ensuring the surrogate tokens maintain syntactic and semantic role so the external LLM can reason over the relationships without seeing confidential values.", "Discusses enterprise architectures: deploying localized lightweight models for sensitive tasks vs. sanitized data to public LLMs, or utilizing zero-data-retention enterprise VPC agreements."], "supporting_evidence": ["Mentions format-preserving encryption (FPE) and in-memory secure vault mapping with short TTLs.", "Discusses scrubbing embeddings or sanitizing knowledge-base chunks before indexing in external vector databases.", "Examples, frameworks, or thresholds mentioned: names, account numbers, IP addresses, e.g., [USER_ALPHA], [ACCOUNT_42].", "Examples, frameworks, or thresholds mentioned: e.g., replacing a company name with a generic company placeholder."], "negative_evidence": ["Assumes standard public commercial LLM endpoints are automatically secure and private without data transformation or enterprise contractual guarantees.", "Recommends stripping out all entities entirely without placeholders, causing the model to lose grammatical structure and contextual reasoning ability."], "partial_credit": ["Describes replacing names with dummy names, but lacks technical depth on reversible token mapping, privacy proxies, or context preservation strategies."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'When an async guardrail flags a response already shown, what rollback and containment strategy would you use?', '{"required_evidence": ["Details client-side UI remediation: sending immediate WebSocket/SSE event to retract, redact, or replace the flagged message with a standardized compliance/safety disclaimer.", "Details backend containment: marking the message and session as compromised in persistent storage, preventing downstream LLM turns from referencing the toxic response in conversation context.", "Outlines incident response and auditing: logging the violation event with trace ID, evaluating potential exposure impact, notifying security operations, and triggering user warnings or temporary account session suspensions if intentional abuse occurred."], "supporting_evidence": ["Discusses compensatory actions for transactional side-effects if the model triggered a tool action before the async flag returned (e.g., initiating saga rollbacks or transaction voids).", "Mentions analyzing the latency gap between token streaming and async classifier completion to tune chunk buffering and avoid future race conditions."], "negative_evidence": ["Ignores the response already displayed to the user and takes no action because ''it is too late once rendered''.", "Allows contaminated outputs to persist in the chat history buffer, leading subsequent conversation turns into toxic or jailbroken states."], "partial_credit": ["Suggests deleting or editing the message on the screen, but misses context window eviction, downstream tool containment, and incident logging."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'In a high-assurance environment, what evidence would you require before re-enabling a blocked model or version?', '{"required_evidence": ["Requires automated regression and safety benchmark results: 100% pass rate on test suites replicating the specific failure/vulnerability that caused the block, plus no degradation on standard safety benchmarks.", "Requires adversarial red-teaming and boundary testing evidence: documented penetration testing demonstrating resilience against known jailbreaks, prompt injections, and edge cases.", "Outlines governance and audit artifacts: formal root cause analysis, architectural/prompt fix documentation, sign-off from compliance/security review boards, and a controlled staged rollout plan ."], "supporting_evidence": ["Mentions continuous shadow deployment (running the candidate model in dark mode alongside the active fallback model to compare outputs on live traffic without user impact).", "Specifies drift analysis and confidence distribution comparisons across golden datasets.", "Examples, frameworks, or thresholds mentioned: RCA, canary deployment with kill-switch."], "negative_evidence": ["Re-enables the model based solely on informal developer reassurance or subjective manual spot-checking of two or three queries.", "Deploys the blocked model directly to 100% production traffic without canary phases or rollback triggers."], "partial_credit": ["Mentions testing the model on the bug that broke it and getting manager approval, but lacks structured regression benchmarks, red-teaming, shadow traffic, or formal governance sign-offs."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 240, 'How do you design safe, trustworthy and responsible AI in high-stakes domains?', '{"required_evidence": ["Details deterministic guardrails and grounding: strict RAG architectures with verbatim source attribution/citations, eliminating ungrounded generation, and employing multi-layer validation .", "Implements human-in-the-loop workflows: automated recommendations must be reviewed and approved by certified domain experts before execution in life- or capital-critical actions.", "Ensures explainability, auditability, and governance: comprehensive logging of model versions, prompts, retrieval sources, confidence scores, and compliance with domain regulations ."], "supporting_evidence": ["Discusses bias testing, demographic parity metrics, and fairness audits across diverse population cohorts.", "Mentions fail-safe defaults: defaulting to safe deterministic fallbacks or human escalation whenever model uncertainty exceeds tight statistical thresholds.", "Examples, frameworks, or thresholds mentioned: input/output safety classifiers.", "Examples, frameworks, or thresholds mentioned: HITL."], "negative_evidence": ["Grants autonomous end-to-end decision-making authority to generative AI in medical diagnosis, legal sentencing, or high-stakes financial execution without human oversight.", "Treats the LLM as an unchallengeable black box without provenance tracking, explainability spans, or audit logs."], "partial_credit": ["Mentions being careful, testing for bias, and keeping humans in the loop, but lacks rigorous technical controls, citation grounding, audit architectures, or regulatory compliance frameworks."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'How do you design authentication and authorization for multi-platform access, including temporary-password flows?', '{"required_evidence": ["Details multi-platform authentication architecture: centralized Identity Provider utilizing OAuth 2.0 and OpenID Connect issuing JWT access and refresh tokens, supporting web, mobile, and desktop clients.", "Explains authorization models: Role-Based Access Control and Attribute-Based Access Control enforced at API gateways and service layers with cryptographically verified token claims.", "Details temporary-password / password-reset flow: generating cryptographically random, high-entropy, short-lived tokens, delivered via secure channels, enforcing single-use invalidation and mandatory password change upon initial login."], "supporting_evidence": ["Mentions PKCE (Proof Key for Code Exchange) flow for mobile and single-page apps (SPAs) to mitigate authorization code interception.", "Discusses rate limiting, MFA step-up authentication, and revoking all existing active sessions when a password is reset.", "Examples, frameworks, or thresholds mentioned: IdP, OIDC.", "Examples, frameworks, or thresholds mentioned: RBAC, ABAC."], "negative_evidence": ["Sends temporary passwords in plaintext without expiration or stores them unhashed in the database.", "Uses session cookies without proper CORS/SameSite configuration across distinct mobile and web domains, or allows temporary passwords to persist indefinitely."], "partial_credit": ["Explains JWT authentication and sending a reset link with a token, but omits PKCE, cryptographic single-use token hashing, or forced password change logic."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'How do you implement rate limiting, CSRF protection, logging and input sanitization?', '{"required_evidence": ["Rate limiting: describes token bucket or sliding window algorithms implemented at API gateways or distributed caches keyed by IP, authenticated user ID, or API key.", "CSRF protection: explains anti-CSRF tokens and configuring SameSite=Strict or Lax cookie flags for state-changing HTTP requests.", "Input sanitization & logging: sanitizes/validates incoming payloads using strict schemas to prevent XSS and SQL injection; implements structured JSON logging while redacting sensitive fields and avoiding log injection."], "supporting_evidence": ["Discusses HTTP 429 Too Many Requests response headers (Retry-After, X-RateLimit-Remaining).", "Mentions why stateless API architectures using Bearer authorization headers are inherently immune to classic cross-site cookie CSRF attacks.", "Examples, frameworks, or thresholds mentioned: Redis.", "Examples, frameworks, or thresholds mentioned: synchronizer token pattern or double-submit cookie pattern."], "negative_evidence": ["Believes rate limiting can be implemented reliably in local process memory across multiple horizontally scaled web server instances without a shared cache.", "Logs full incoming HTTP request headers and bodies including plaintext passwords and authorization tokens."], "partial_credit": ["Defines what each of the four concepts does at a high level, but lacks implementation details (e.g., Redis algorithms, SameSite cookies, schema validation)."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'Why are traceability and auditability critical in regulated systems such as drug development?', '{"required_evidence": ["Regulatory compliance and accountability: adherence to strict legal and regulatory mandates requiring verifiable electronic records, digital signatures, and accountability for every clinical decision.", "Reproducibility and data provenance: ensuring every computational result, model prediction, or clinical trial finding can be deterministically traced back to exact source data, pre-processing code, model weights, hyperparameter versions, and execution environments.", "Patient safety and defect investigation: enabling rapid forensic root-cause analysis when adverse events, anomalies, or clinical trial failures occur to determine whether faults stemmed from data corruption, model hallucination, or protocol violations."], "supporting_evidence": ["Mentions immutable audit logs using cryptographic hashing or write-once-read-many (WORM) storage.", "Discusses ML experiment tracking tools (MLflow, DVC, Pachyderm) for end-to-end data and model versioning in clinical bioinformatics pipelines.", "Examples, frameworks, or thresholds mentioned: e.g., FDA 21 CFR Part 11, GxP, EMA guidelines."], "negative_evidence": ["Argues that fast innovation in drug discovery justifies using black-box untraceable models without versioning or audit trails.", "Believes model weights and training datasets do not need to be archived once a model is deployed to production."], "partial_credit": ["Explains that traceability is needed for FDA approval and catching bugs, but lacks depth on 21 CFR Part 11, data provenance, reproducible computational pipelines, or immutable audit logs."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'EASY', 'SPECIFIC', 180, 'How do you ensure WCAG accessibility compliance?', '{"required_evidence": ["Four core WCAG principles : Perceivable, Operable, Understandable, and Robust.", "Semantic HTML and ARIA attributes: utilizing native semantic elements, providing descriptive alt text for images, and implementing proper WAI-ARIA roles/states where custom components are necessary.", "Keyboard navigation and visual design: ensuring full keyboard operability and meeting color contrast ratios ."], "supporting_evidence": ["Automated and manual testing strategy: integrating automated linting/testing tools (axe-core, Lighthouse, Pa11y) alongside screen reader testing (NVDA, VoiceOver, JAWS).", "Addressing dynamic AI/chat interfaces: announcing real-time streaming updates to assistive technology using aria-live regions (polite vs. assertive).", "Examples, frameworks, or thresholds mentioned: POUR.", "Examples, frameworks, or thresholds mentioned: <button>, <nav>, <main>."], "negative_evidence": ["Replaces standard interactive elements entirely with non-semantic <div> and <span> elements without keyboard event listeners or ARIA attributes.", "Assumes accessibility only applies to blind users or can be fully solved using automated overlay widgets."], "partial_credit": ["Mentions adding alt text to images and checking color contrast, but overlooks keyboard navigation, semantic HTML, ARIA live regions, or the POUR framework."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you monitor and maintain an AI system (logging, alerting, OpenTelemetry and its limits)?', '{"required_evidence": ["Multi-tier monitoring metrics: operational metrics alongside AI quality metrics .", "Alerting strategies: proactive thresholds and anomaly detection for error spikes, latency degradation, budget/token burn rate anomalies, and safety guardrail tripwire spikes.", "OpenTelemetry implementation and limitations: standardizing distributed tracing GenAI semantic conventions, while addressing its limits ."], "supporting_evidence": ["Discusses tail-based sampling in OpenTelemetry to collect 100% of error/slow traces while sampling regular successful interactions.", "Mentions integrating evaluation engines (Ragas, TruLens, DeepEval) into asynchronous telemetry pipelines.", "Examples, frameworks, or thresholds mentioned: latency/TTFT, throughput, HTTP 429/5xx errors, GPU memory/utilization, token usage, perplexity, hallucination rates, user sentiment/thumbs-up/down, retrieval relevance.", "Examples, frameworks, or thresholds mentioned: high data ingestion costs, payload truncation of large prompts/embeddings, lack of native deep evaluation metrics."], "negative_evidence": ["Believes traditional CPU/memory infrastructure monitoring is sufficient to detect generative AI failures and hallucinations.", "Ingests full megabyte-sized prompt and context payloads into standard APM traces without payload size caps, blowing up telemetry storage budgets."], "partial_credit": ["Describes logging latency and errors and setting up Slack alerts, but overlooks AI-specific metrics (TTFT, token burn, guardrail triggers) and OpenTelemetry trade-offs."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Concurrency & Parallelism', 'MEDIUM', 'SPECIFIC', 180, 'How do you handle rate limits, timeouts and reliability?', '{"required_evidence": ["Rate limit handling: parsing rate-limit response headers, implementing client-side rate limiting, and leveraging message queues to smooth traffic spikes.", "Timeout architecture: configuring granular timeouts across all tiers, ensuring client timeouts exceed downstream timeouts to prevent premature client abandonment.", "Reliability patterns: employing circuit breakers, retries with exponential backoff and randomized jitter, and graceful fallback responses."], "supporting_evidence": ["Mentions distributed rate limiting using Redis sliding window counters across multiple worker processes.", "Discusses dead-letter queues (DLQ) for asynchronous requests that exhaust retry budgets.", "Examples, frameworks, or thresholds mentioned: Retry-After, X-RateLimit-Reset, leaky bucket/token bucket.", "Examples, frameworks, or thresholds mentioned: connect, read, write timeouts."], "negative_evidence": ["Uses infinite or unconfigured timeouts, leading to thread and connection pool exhaustion when an upstream service stalls.", "Retries requests synchronously without delay or jitter, overwhelming struggling services with thundering herds."], "partial_credit": ["Mentions setting timeouts and retrying on failure, but misses jitter, circuit breakers, header-driven rate limit throttling, or queuing mechanisms."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 180, 'How do you detect anomalies in real-time logs and trigger automated responses?', '{"required_evidence": ["Real-time log ingestion and processing pipeline: streaming logs, Kinesis, or Vector into stream processing engines .", "Anomaly detection techniques: applying statistical thresholds, pattern clustering, or machine learning anomaly detection models to detect sudden spikes in novel log patterns or error frequencies.", "Automated response orchestration: triggering automated workflows via webhooks/event buses to auto-remediate ."], "supporting_evidence": ["Discusses alert deduplication, flapping prevention (hysteresis), and grouping correlated anomalies to prevent alert fatigue.", "Mentions feeding anomaly summaries into generative AI incident copilots for automated initial triage documentation.", "Examples, frameworks, or thresholds mentioned: e.g., Apache Flink, Elasticsearch, ClickHouse, Datadog.", "Examples, frameworks, or thresholds mentioned: e.g., Z-score, rolling standard deviations on error rates, e.g., LogCluster, Drain."], "negative_evidence": ["Suggests running periodic cron jobs that parse multi-gigabyte raw text files with regex every 15 minutes, failing real-time SLAs.", "Triggers drastic automated responses (e.g., database drops or instant broad IP bans) based on single un-debounced log anomalies."], "partial_credit": ["Describes sending logs to ELK and triggering an email alert when errors exceed a fixed count, but misses stream processing architectures, statistical/ML anomaly detection, and automated remediation loops."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How do you identify root causes in an existing defective system before proposing a fix?', '{"required_evidence": ["Systematic triage and failure reproduction: gathering symptoms, establishing minimal reproducible test cases in isolated staging environments, and verifying expected vs. actual behavior.", "Evidence-based investigation: tracing code execution paths, examining git blame/recent release diffs, analyzing database query plans and state changes, and correlating timeline events.", "Root Cause Analysis methodology: applying structured techniques like the ''5 Whys'', fishbone diagrams, or fault tree analysis to determine systemic/architectural causes rather than merely treating superficial symptoms."], "supporting_evidence": ["Discusses bisecting git commits (git bisect) to automatically isolate the exact commit introducing a defect.", "Emphasizes writing a regression test that fails on the bug and passes on the fix before deploying code changes.", "Examples, frameworks, or thresholds mentioned: logs, metrics, user reports.", "Examples, frameworks, or thresholds mentioned: RCA."], "negative_evidence": ["Proposes guessing fixes and deploying speculative code changes directly to production without reproducing or understanding the underlying defect.", "Blames individual developers rather than identifying procedural, testing, or architectural deficiencies (violating blameless RCA culture)."], "partial_credit": ["Mentions checking logs, reproducing the bug, and testing the fix, but lacks structured RCA methodology, commit bisection, or systemic failure analysis."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 180, 'How do you use Cursor and AI coding tools, integrate AI into the SDLC, and what does "AI-native development" mean?', '{"required_evidence": ["Effective utilization of AI coding tools: leveraging codebase-wide indexing, iterative multi-file refactoring, test generation, and automated documentation.", "Integration into SDLC: incorporating AI into automated PR reviews, automated changelog and release notes generation, synthetic test suite generation, and CI/CD linting/security triage.", "Defining ''AI-native development'': shifting from manual character-by-character coding to architectural supervision, intent specification, prompt/context curation, and rigorous automated verification ."], "supporting_evidence": ["Discusses security and IP risks (preventing internal code leakage to public model training data and scanning AI code for insecure dependencies/hallucinated packages).", "Mentions using agentic coding workflows (e.g., autonomous issue-solving agents running in isolated container environments).", "Examples, frameworks, or thresholds mentioned: .cursor/rules, @codebase, context embedding.", "Examples, frameworks, or thresholds mentioned: test-driven development where AI writes code and humans verify contracts and invariants."], "negative_evidence": ["Assumes AI coding tools write flawless code that can be deployed straight to production without unit testing or human code review.", "Believes AI-native development simply means using ChatGPT in a separate browser tab to copy-paste snippets."], "partial_credit": ["Describes using Cursor for autocomplete and generating unit tests, but lacks a coherent definition of AI-native development or SDLC CI/CD pipeline integration."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'What are the key decisions behind a reusable platform versus isolated AI solutions?', '{"required_evidence": ["Strategic architectural trade-offs: isolated solutions offer rapid time-to-market, custom tailoring, and zero cross-team dependencies for initial MVPs, whereas a reusable platform amortizes infrastructure costs, eliminates duplicate tooling, and standardizes governance/security.", "Core platform capabilities: centralizing foundational services including model gateway/routing, prompt management, centralized guardrails, unified observability/tracing, fine-tuning infrastructure, and tool registries.", "Tenancy, extensibility, and organizational friction: designing multi-tenant isolation, cost allocation/chargeback by team, avoiding lowest-common-denominator abstractions that stifle specialized product innovation, and defining clear platform APIs."], "supporting_evidence": ["References Conway''s Law and team topologies (platform team providing self-service APIs to stream-aligned product teams).", "Discusses the build-vs-buy analysis for LLMOps platforms (e.g., using open platform primitives vs. vendor lock-in)."], "negative_evidence": ["Recommends building a monolithic, rigid enterprise platform before validating any individual AI use case with real end-users.", "Suggests allowing every individual engineering team in an enterprise to independently negotiate separate LLM vendor contracts and build custom guardrail stacks from scratch."], "partial_credit": ["Notes that a platform saves money and avoids rewriting code while isolated apps are faster to build, but fails to articulate core platform components, multi-tenancy, or governance."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How would you write SystemVerilog assertions for a 4-phase handshake with variable delays?', '{"required_evidence": ["Defines 4-phase handshake protocol: sequence where Request asserts high, Acknowledge asserts high, Request deasserts, and Acknowledge deasserts .", "SystemVerilog Assertions syntax and sequences: utilizing property, sequence, and non-consecutive / variable delay implications clocked on the design clock.", "Formal checking and corner cases: asserting that req remains stable until ack is asserted, asserting that ack drops only after req drops, and enforcing maximum latency timeouts using assert property with else $error."], "supporting_evidence": ["Mentions concurrent assertions (assert property) vs. immediate assertions, and distinguishing between overlapping (|->) and non-overlapping (|=>) implications.", "Discusses cover properties (cover property) to verify that the handshake transactions are actually stimulated in simulation testbenches.", "Examples, frameworks, or thresholds mentioned: req -> ack, ack -> req low, req low -> ack low, ack low.", "Examples, frameworks, or thresholds mentioned: SVA, |->, ##[min:max] or ##[1:$] with maximum timeout bounds."], "negative_evidence": ["Writes standard procedural if/else simulation checks instead of declarative SystemVerilog Assertions (SVA).", "Uses unbounded delays (##[1:$]) in assertions without an upper bound or timeout, causing formal verification engines to hang or fail to detect deadlock."], "partial_credit": ["Understands the 4-phase handshake sequence (req/ack toggles), but cannot write valid SVA sequence/property syntax or specify delay ranges."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How do gate-level simulation, FPGA emulation and post-silicon validation differ from pre-silicon verification?', '{"required_evidence": ["Pre-silicon verification vs. Gate-level simulation : pre-silicon RTL simulation focuses on functional correctness at high abstraction, whereas GLS runs on post-synthesis netlists with actual gate delays and SDF timing annotations to verify timing closure, clock-domain crossing, and scan chains.", "FPGA emulation: maps synthesized RTL onto physical FPGA hardware running orders of magnitude faster than software RTL simulators, enabling boot-up of real operating systems and complex software stacks before tape-out.", "Post-silicon validation: tests actual manufactured physical silicon chips in laboratory environments across voltage/temperature corners using logic analyzers, oscilloscopes, and automated test equipment to catch physical defects and board-level integration issues."], "supporting_evidence": ["Compares execution speed spectrum: RTL simulation (1-10 Hz) -> Gate-Level Simulation (<1 Hz) -> FPGA Emulation (100 kHz - 10 MHz) -> Silicon (GHz).", "Discusses observability trade-offs: full signal visibility in RTL simulation vs. limited visibility and scan chains in FPGA emulation and physical silicon.", "Examples, frameworks, or thresholds mentioned: GLS, UVM/SystemVerilog, CDC.", "Examples, frameworks, or thresholds mentioned: e.g., Palladium, Zebu, kHz to MHz."], "negative_evidence": ["Claims pre-silicon simulation and post-silicon validation test the exact same physical hardware.", "Assumes FPGA emulation replaces the need for gate-level timing verification."], "partial_credit": ["Identifies that pre-silicon is software simulation and post-silicon is physical chip testing, but fails to clearly distinguish Gate-Level Simulation (GLS) or FPGA emulation."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'Why use system-wide tracers like Perfetto, and how do they compare with Android Profiler?', '{"required_evidence": ["System-wide scope vs. App-level scope: Android Profiler primarily inspects a single application process /Android Studio, whereas Perfetto captures system-wide kernel events, scheduling, CPU frequencies, memory allocations, and interactions across multiple processes and surface flinger.", "Performance overhead and production tracing: Perfetto is built into the Android platform, allowing it to record long-running production traces and system-wide boot traces, whereas Android Profiler incurs higher instrumentation overhead.", "Deep analysis capabilities: Perfetto exports trace files viewable in the Perfetto Web UI with SQL querying over system trace events, allowing correlation of app jank with background kernel threads or GPU bottlenecks."], "supporting_evidence": ["Mentions custom atrace tags and TrackEvent API in native/Java code for custom span markers inside Perfetto.", "Discusses identifying thread priority inversions, binder IPC transaction delays, and thermal throttling using Perfetto.", "Examples, frameworks, or thresholds mentioned: CPU, memory, network, energy.", "Examples, frameworks, or thresholds mentioned: written in C++ with ring buffers and low overhead."], "negative_evidence": ["Believes Perfetto is just a UI wrapper around Android Studio''s CPU profiler.", "Assumes Android Profiler can trace kernel context switches and multi-process IPC interactions across the entire OS."], "partial_credit": ["Notes that Android Profiler is an Android Studio tool for app debugging while Perfetto gives lower-level system traces, but lacks technical depth on ftrace/kernel instrumentation, SQL querying, or overhead differences."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'HARD', 'SPECIFIC', 240, 'Explain the Transformer architecture: encoder, decoder, attention. What is the most important component, and what properties beyond attention made it effective?', '{"required_evidence": ["Architecture fundamentals: explains Encoder and Decoder .", "Scaled Dot-Product Attention: details Attention = softmax) V, explaining how multi-head attention allows the model to jointly attend to information from different representation subspaces and positions.", "Critical properties beyond attention: residual connections, Layer Normalization, positional encodings, and Feed-Forward Networks ."], "supporting_evidence": ["Argues whether attention or residual stream / normalization is the most critical component, noting that attention provides dynamic routing while residual connections and LayerNorm make optimization of deep networks mathematically feasible.", "Discusses computational parallelization: unlike recurrent neural networks (RNNs/LSTMs), transformers compute all sequence positions simultaneously during training, unlocking massive GPU scaling.", "Examples, frameworks, or thresholds mentioned: processes input with bidirectional self-attention to generate contextual representations, uses masked causal self-attention and cross-attention over encoder outputs for auto-regressive generation.", "Examples, frameworks, or thresholds mentioned: Q, K, V, QK^T / sqrt(d_k."], "negative_evidence": ["Claims Transformers process tokens sequentially step-by-step during training like RNNs or LSTMs.", "Forgets that self-attention alone is permutation-invariant and cannot determine word order without positional encodings."], "partial_credit": ["Explains encoder, decoder, and attention query-key-value formulas, but fails to identify properties beyond attention (residual connections, LayerNorm, parallelizability, positional encodings) that made it effective."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'How does few-shot prompting work for classification, and how do you choose examples and context length?', '{"required_evidence": ["Explains few-shot mechanism: conditioning autoregressive completions on input-label demonstration pairs within the context window, aligning the model''s output distribution with target label taxonomy and syntax.", "Details example selection strategies: ensuring balanced class distribution to prevent majority-class prediction bias; selecting semantically relevant demonstrations via k-NN vector search on query embeddings ; and including diverse boundary edge cases.", "Balances context length and exemplar ordering: managing recency bias and monitoring diminishing returns where adding excessive examples inflates token costs and latency without F1 improvements."], "supporting_evidence": ["Mentions formatting consistency across exemplars using structured delimiters (XML/JSON/Markdown).", "Discusses calibration techniques to counteract LLM prior label frequency and positional biases.", "Examples, frameworks, or thresholds mentioned: dynamic few-shot.", "Examples, frameworks, or thresholds mentioned: where the last example disproportionately steers predictions."], "negative_evidence": ["Recommends selecting examples randomly with unbalanced class distributions without considering model prediction bias.", "Claims few-shot prompting permanently modifies model parameter weights."], "partial_credit": ["Explains providing input-output examples in the prompt to show the model how to classify, but lacks criteria for example selection, class balance, or context length trade-offs."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'NLP', 'MEDIUM', 'SPECIFIC', 180, 'Why is BERT suited to sentiment classification, and why fine-tune a small model like BERT instead of using a large LLM?', '{"required_evidence": ["Explains BERT''s bidirectional encoder architecture enables it to capture contextual representations from both left and right simultaneously, making it ideal for sequence classification via the [CLS] token.", "Highlights cost and latency advantages: a fine-tuned BERT model executes inference in single-digit milliseconds on commodity CPU/GPU hardware at near-zero incremental cost compared to expensive generative LLM API calls.", "Discusses deterministic output and calibration: fine-tuned classification heads output direct softmax probabilities over discrete classes, eliminating prompt formatting drift, hallucinations, and parsing failures."], "supporting_evidence": ["Mentions privacy, security, and edge/on-prem deployment: small models run entirely in air-gapped VPCs without transmitting proprietary customer text to third-party endpoints.", "Notes that task-specific fine-tuning on domain data often achieves higher accuracy and F1 score than zero-shot/few-shot prompting on generic LLMs.", "Examples, frameworks, or thresholds mentioned: ~110M params."], "negative_evidence": ["Assumes generative decoder LLMs (like frontier model) are always the optimal production choice for high-volume text classification tasks.", "Claims BERT generates sentiment predictions autoregressively token by token."], "partial_credit": ["Mentions that BERT is smaller, cheaper, and faster than a large LLM, but fails to explain BERT''s bidirectional nature or dedicated classification head benefits."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'How do you choose an LLM (criteria, POC comparison, Claude versus Llama or Mistral)? How do you compare open- and closed-source models, and balance cost and performance?', '{"required_evidence": ["Evaluation criteria & POC comparison: defines structured evaluation frameworks tested against a standardized domain benchmark dataset before selecting a model.", "Compares closed vs open-source models: Closed models offer state-of-the-art reasoning, zero infrastructure management, and large context windows, but present vendor lock-in, recurring API costs, and compliance risks; Open models allow on-prem hosting, custom fine-tuning, complete data sovereignty, and zero per-token API fees, but require GPU infrastructure management and MLOps overhead.", "Balancing cost and performance: implements model routing/cascading architectures ; evaluates total cost of ownership comparing high-volume cloud tokens against dedicated GPU reservations."], "supporting_evidence": ["Analyzes Claude''s strengths in long-context coding and adherence to system prompts vs Mistral''s high-throughput efficiency and European sovereign compliance.", "Mentions using LLM gateways with caching (semantic caching) to further optimize cost.", "Examples, frameworks, or thresholds mentioned: task-specific accuracy, context window size, latency P95, cost per 1k tokens, reasoning capability.", "Examples, frameworks, or thresholds mentioned: e.g., frontier model, frontier model, e.g., Llama 3, Mistral."], "negative_evidence": ["Selects models purely on public leaderboard rankings (e.g. LMSYS Chatbot Arena) without benchmarking against company-specific business data.", "Assumes open-source models are completely free without accounting for GPU cloud compute, engineering, and maintenance costs."], "partial_credit": ["Compares Claude and Llama on general features, but lacks a systematic POC evaluation methodology, TCO analysis, or model cascading strategy."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'NLP', 'MEDIUM', 'SPECIFIC', 180, 'What are the trade-offs of word-level, subword-level and character-level tokenization? How do you implement tokenization in practice (libraries)?', '{"required_evidence": ["Compares trade-offs: word-level causes massive vocabulary sizes and severe out-of-vocabulary issues; character-level eliminates OOV and minimizes vocabulary but results in very long token sequences, blowing up self-attention compute ); subword-level strikes the optimal balance between sequence length and vocabulary size by decomposing rare words into known subwords.", "Identifies practical tokenization libraries: Hugging Face Tokenizers, transformers AutoTokenizer, Google''s SentencePiece, or OpenAI''s tiktoken.", "Describes practical implementation steps: loading pre-trained tokenizers, handling padding, truncation, attention masks, special tokens, and decoding token IDs back to strings."], "supporting_evidence": ["Mentions Byte-level BPE (BBPE) operating directly on UTF-8 bytes to completely eliminate out-of-vocabulary (<unk>) tokens across multiple languages.", "Discusses the performance difference between pure Python tokenizers and Rust-accelerated fast tokenizers during high-throughput batching.", "Examples, frameworks, or thresholds mentioned: OOV, O(N^2, BPE, WordPiece, Unigram, ~30k-100k.", "Examples, frameworks, or thresholds mentioned: Rust-based, fast."], "negative_evidence": ["Claims character-level tokenization produces shorter sequence lengths than word-level tokenization.", "Suggests basic whitespace string splitting (str.split) is an adequate production tokenization strategy for modern LLMs."], "partial_credit": ["Explains vocabulary size and OOV trade-offs between word and character tokenization, but omits subword algorithms (BPE/WordPiece) or library implementation details."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'What architectural or training changes improved recent LLMs over earlier versions?', '{"required_evidence": ["Identifies architectural enhancements: Rotary Position Embeddings replacing absolute encodings for better length extrapolation; Grouped-Query Attention and Multi-Query Attention reducing KV cache memory bandwidth; and SwiGLU / GeGLU activations replacing standard ReLU/GELU.", "Identifies attention and compute optimizations: FlashAttention and Mixture-of-Experts architectures activating sparse subsets of parameters per token to achieve massive capacity at low inference FLOPs.", "Describes training dataset and recipe evolutions: adherence to Chinchilla compute-optimal scaling laws, curated synthetic data generation and filtering, multi-stage curriculum pre-training for long context, and Direct Preference Optimization ."], "supporting_evidence": ["Mentions RMSNorm replacing standard LayerNorm to improve throughput and numerical stability.", "Discusses native support for extended context windows (up to 1M+ tokens) through YaRN or RoPE base frequency scaling.", "Examples, frameworks, or thresholds mentioned: RoPE, GQA, MQA.", "Examples, frameworks, or thresholds mentioned: IO-aware tiling minimizing HBM read/writes, MoE."], "negative_evidence": ["Claims modern LLM improvements are solely driven by increasing parameter counts without architectural or memory optimizations.", "Believes modern LLMs abandoned attention in favor of standard RNN recurrence."], "partial_credit": ["Mentions Mixture of Experts and larger datasets, but cannot explain specific architectural changes like RoPE, GQA, or FlashAttention."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'What are the challenges of scaling AI for compliance use cases (evaluation, guardrails, context)?', '{"required_evidence": ["Explains evaluation challenges: compliance requires near 100% deterministic accuracy and zero hallucinations, demanding rigorous golden datasets, domain-expert audits, and provable test coverage.", "Explains guardrail challenges: strict real-time guardrails introduce significant latency and cost overhead at scale, requiring multi-layered filtering that must not cause false-positive refusals on legitimate regulatory queries.", "Explains context and auditability challenges: regulatory frameworks mandate verifiable audit trails, exact document citations, explainability of decisions, and handling evolving compliance standards across massive, fragmented document corpuses."], "supporting_evidence": ["Discusses latency-throughput trade-offs of running cascading guardrail models at high QPS.", "Mentions compliance frameworks (e.g., HIPAA, GDPR, FINRA, EU AI Act) requiring immutability, data lineage, and right-to-explanation."], "negative_evidence": ["Assumes standard consumer LLMs can be deployed for strict compliance tasks without extensive guardrails, determinism checks, or audit logging."], "partial_credit": ["Mentions that compliance requires accurate answers and lots of rules, but lacks technical depth on guardrail latency overhead, auditability, or evaluation rigor."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'NLP', 'MEDIUM', 'SPECIFIC', 180, 'How do you use BERT, spaCy and NLTK in NLP workflows?', '{"required_evidence": ["Delineates distinct library roles: NLTK for traditional educational text processing and rule-based tasks ; spaCy for production-grade, fast CPU NLP pipelines ; and BERT for deep contextual representations, semantic similarity, and fine-tuned classification.", "Designs staged pipeline architectures: leveraging spaCy/NLTK in early stages for deterministic cleaning, regex matching, and sentence segmentation, then feeding structured spans or ambiguous text to BERT for high-accuracy contextual understanding.", "Evaluates compute and throughput trade-offs: spaCy processes thousands of documents per second on CPU with minimal memory, whereas BERT requires GPU inference and higher latency, making hybrid pipelines optimal."], "supporting_evidence": ["Mentions spacy-transformers for wrapping Hugging Face transformer backends into modular spaCy pipeline components.", "Discusses rule-based pattern matchers (spaCy Matcher/PhraseMatcher) combined with transformer embeddings for hybrid entity recognition.", "Examples, frameworks, or thresholds mentioned: stemming, tokenizing, stopword filtering, tokenization, POS tagging, dependency parsing, NER."], "negative_evidence": ["Recommends fine-tuning BERT for basic tasks like stopword removal, sentence splitting, or simple regex pattern extraction.", "Claims NLTK is the preferred industry standard for high-concurrency production microservices over spaCy."], "partial_credit": ["Identifies that NLTK is academic, spaCy is fast/production-oriented, and BERT is deep learning, but does not provide practical staged pipeline design or compute trade-offs."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'NLP', 'MEDIUM', 'SPECIFIC', 180, 'How do traditional NLP approaches compare with LLMs for entity recognition, categorization and matching?', '{"required_evidence": ["Evaluates traditional NLP : sub-millisecond CPU latency, deterministic outputs, zero API costs, and robust consistency on strict known entities, but brittle against linguistic variation, typos, and out-of-vocabulary terms.", "Evaluates LLMs : deep contextual comprehension, zero-shot entity extraction across novel unseen classes, resilience to noisy text, but introduces high latency, token cost, non-determinism, and risk of hallucinations.", "Proposes practical hybrid designs: running fast traditional NLP as a primary filter for high-confidence standard entities, and routing complex, ambiguous, or novel entity candidates to an LLM."], "supporting_evidence": ["Discusses evaluation methodology: strict span-level Precision/Recall/F1 metrics for traditional NER vs generative fuzzy evaluation for LLMs.", "Mentions entity linking and normalization against structured knowledge graphs or relational databases.", "Examples, frameworks, or thresholds mentioned: spaCy NER, CRF, regex, TF-IDF, fuzzy matching.", "Examples, frameworks, or thresholds mentioned: zero-shot / few-shot prompting, structured extraction."], "negative_evidence": ["Suggests replacing all deterministic lookups and regexes with LLM prompts regardless of cost and latency budgets.", "Claims traditional statistical models exhibit superior zero-shot generalization on unseen entity categories compared to LLMs."], "partial_credit": ["Compares the speed of traditional NLP with the flexibility of LLMs, but lacks architectural depth regarding hybrid routing or precision/recall trade-offs."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'Explain zero-shot, one-shot, few-shot, chain-of-thought, role, context, system prompting and prompt chaining, with use cases.', '{"required_evidence": ["Defines exemplar-based prompting: Zero-shot ; One-shot/Few-shot .", "Defines reasoning and contextual prompting: Chain-of-Thought ; Role prompting ; Context prompting .", "Explains System Prompting vs Prompt Chaining: System prompt defines persistent persona, behavioral rules, safety boundaries, and tool schemas; Prompt Chaining decomposes complex workflows into sequential LLM calls where output of step N feeds step N+1 ."], "supporting_evidence": ["Discusses Self-Consistency CoT (sampling multiple reasoning paths and taking majority vote) to improve reasoning reliability.", "Analyzes token budget and latency trade-offs of large few-shot prompts versus fine-tuning.", "Examples, frameworks, or thresholds mentioned: instruction only, no demonstrations; e.g., standard QA, providing 1 or several input-output exemplar pairs to anchor format and domain patterns; e.g., few-shot JSON entity extraction.", "Examples, frameworks, or thresholds mentioned: instructing model to articulate intermediate reasoning steps before the final answer; e.g., multi-step arithmetic/logic, assigning persona/domain perspective; e.g., ''Act as a senior cybersecurity auditor'', injecting background reference material; e.g., RAG document QA."], "negative_evidence": ["Confuses few-shot prompting (in-context demonstrations) with model fine-tuning (updating model weights).", "Claims Prompt Chaining executes all steps simultaneously in a single unmonitored LLM forward pass."], "partial_credit": ["Defines 3 or 4 prompting techniques correctly, but misses prompt chaining, chain-of-thought, or role prompting, or fails to provide concrete use cases."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you debug and refine a prompt that gives suboptimal results?', '{"required_evidence": ["Establishes a systematic evaluation baseline: curating a golden test set with diverse inputs and edge cases, tracking quantitative metrics rather than relying on manual one-off vibe checks.", "Diagnoses failure root causes: isolating whether errors stem from ambiguous instructions, missing domain context, context window truncation, formatting errors, or model hallucination.", "Implements iterative prompt refinement techniques: adding structured delimiters, providing dynamic few-shot exemplars, incorporating chain-of-thought reasoning, hardening negative constraints, and running ablation tests on prompt components."], "supporting_evidence": ["Uses prompt evaluation and tracing tools like PromptFoo, LangSmith, Phoenix, or Braintrust to run automated regression test suites.", "Mentions parameter tuning (adjusting temperature, top_p) or testing across different foundation models as part of root-cause analysis.", "Examples, frameworks, or thresholds mentioned: accuracy, F1, exact match, LLM-as-a-judge rubrics.", "Examples, frameworks, or thresholds mentioned: Markdown/XML."], "negative_evidence": ["Advocates debugging by endlessly tweaking words in the UI playground without a reproducible test suite or metrics.", "Assumes fine-tuning or training a new model is the first step whenever a prompt produces a suboptimal response."], "partial_credit": ["Suggests making the prompt clearer and adding examples, but lacks an engineering approach based on golden test sets, metrics, and regression testing."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'How do you adapt prompts across Claude, ChatGPT and Mistral?', '{"required_evidence": ["Analyzes model-specific formatting preferences: Claude excels with XML tags and pre-filling the assistant response; OpenAI is optimized for Markdown headers, system instructions, and native structured outputs ; Mistral prefers explicit instruction delimiters and concise direct prompting.", "Handles system prompt behavior and alignment differences: Claude has strong safety steerability and adheres strictly to nuanced negative constraints; ChatGPT is conversational and sometimes requires explicit instructions to suppress conversational fluff; Mistral requires precise prompt templates to avoid drifting into multilingual outputs.", "Implements model abstraction layers: utilizing prompt templating engines that dynamically compile base prompt variables into model-specific chat templates and schemas."], "supporting_evidence": ["Mentions tokenization differences and handling varying maximum context windows and context recall characteristics across providers.", "Discusses temperature and top_p differences across vendor inference engines.", "Examples, frameworks, or thresholds mentioned: <instructions>, <context>, <rules>, ChatGPT, response_format: json_object / strict schemas, [INST] ... [/INST].", "Examples, frameworks, or thresholds mentioned: e.g. Jinja2, LangChain prompts."], "negative_evidence": ["Claims prompt text works identically with identical performance across all model families without format adaptation.", "Hardcodes vendor-specific tokens like <|im_start|> directly into prompt text across all providers."], "partial_credit": ["Identifies that different models need different formats (e.g., Claude uses XML), but provides vague or incomplete details on practical adaptation strategies."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'What does temperature do? How do you tune it and other inference parameters, and isolate its effect from other variables? What temperature would you use for a given task?', '{"required_evidence": ["Explains temperature mathematically: scales the raw output logits before the softmax operation; T -> 0 makes the probability distribution sharper, while higher T flattens the distribution, increasing the diversity and randomness of sampled tokens.", "Details other inference sampling parameters and isolation: top_p and top_k ; isolating temperature requires fixing the random seed, fixing top_p, and keeping prompt text, model version, and system parameters strictly constant.", "Provides task-specific temperature guidelines: T=0.0 - 0.2 for deterministic tasks ; T=0.5 - 0.7 for balanced tasks ; T=0.8 - 1.0+ for creative tasks ."], "supporting_evidence": ["Mentions frequency and presence penalties used alongside temperature to prevent repetitive token loops.", "Explains that even at T=0, GPU non-determinism (floating point addition ordering in mixture-of-experts/parallel kernels) can occasionally yield slight variations across runs.", "Examples, frameworks, or thresholds mentioned: z_i / T, approaching greedy argmax decoding, deterministic.", "Examples, frameworks, or thresholds mentioned: nucleus sampling: truncating vocabulary to smallest cumulative probability mass p, restricting sampling to top k tokens, e.g. 1.0."], "negative_evidence": ["Claims temperature changes model weights or modifies training data.", "Suggests high temperatures (T > 0.8) for strict JSON schema extraction or SQL generation."], "partial_credit": ["Understands that temperature controls randomness and gives reasonable values for creative vs factual tasks, but cannot explain the logit-scaling math or how to isolate variables."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 240, 'How would you design an SQL generation pipeline: schema and metadata passed, sensitive data handling, validation and execution?', '{"required_evidence": ["Describes schema injection: providing targeted DDL, column descriptions, foreign key relationships, and representative sample values rather than raw entire database dumps.", "Explains sensitive data handling: pruning PII columns, masking sensitive schemas, and never sending actual sensitive table rows/PII in prompt context.", "Details validation and execution guards: SQL syntax parsing, enforcing read-only permissions, query cost/timeout limits, and iterative error recovery ."], "supporting_evidence": ["Discusses dynamic schema pruning using vector retrieval over database catalog metadata for massive schemas with hundreds of tables.", "Mentions explain plan analysis to reject queries with expensive full table scans.", "Examples, frameworks, or thresholds mentioned: or few-shot examples.", "Examples, frameworks, or thresholds mentioned: e.g., SQLGlot, SELECT only, dedicated read replica, non-privileged DB user, feeding database errors back to the LLM to fix syntax."], "negative_evidence": ["Connects the LLM directly to a production master database with write/drop permissions.", "Dumps entire database tables into the context window to answer questions."], "partial_credit": ["Outlines passing the schema and generating a query, but fails to address read-only enforcement, sensitive data redaction, or SQLGlot validation."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'HARD', 'SPECIFIC', 240, 'Prompt design for code review: what prompt strategies, input structure (why diffs matter), reasoning techniques, and output schema make reviews actionable?', '{"required_evidence": ["Input structure and diffs: supplying unified git diffs rather than entire files to focus context on modified lines, save token budget, and preserve precise before/after line numbers, supplemented with file paths and PR descriptions.", "Prompt strategies and persona: assigning a senior code reviewer role with explicit review criteria and strict instructions to avoid trivial nitpicks or formatting complaints handled by linters.", "Reasoning techniques: instructing the LLM to employ chain-of-thought analysis before proposing comments.", "Actionable output schema: requiring structured JSON/Markdown schemas specifying file path, target line number, severity category, clear explanation of the issue, and concrete replacement code diffs."], "supporting_evidence": ["Discusses providing surrounding AST or symbol definition context for changed functions so the model understands external method contracts.", "Mentions CI/CD integration: posting comments directly to GitHub/GitLab PR review APIs via webhooks.", "Examples, frameworks, or thresholds mentioned: git diff -U3.", "Examples, frameworks, or thresholds mentioned: correctness, security vulnerabilities, edge-case bugs, performance bottlenecks."], "negative_evidence": ["Prompts the LLM to dump generic praise or review entire codebases from scratch without git diffs.", "Generates unstructured, chatty text without specific file names, line numbers, or code suggestions."], "partial_credit": ["Explains using git diffs and asking for security/bug issues in JSON, but misses reasoning techniques, severity classification, or concrete replacement code snippets."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'What are PEFT, LoRA and QLoRA? Which layers are tuned, why choose them over full fine-tuning, and how do you structure the training data?', '{"required_evidence": ["Defines PEFT and LoRA: Parameter-Efficient Fine-Tuning freezes base model weights and trains a tiny fraction of parameters; LoRA decomposes weight update matrix delta_W into two low-rank matrices A and B, scaling by alpha / r.", "Explains QLoRA: quantizes the frozen base model to 4-bit NormalFloat precision, incorporates Double Quantization, and uses Paged Optimizers to prevent memory spikes, enabling fine-tuning on consumer-grade GPUs.", "Identifies target layers and data structure: typically applied to attention projection layers and increasingly MLP feed-forward layers; training data is structured as instruction-response pairs tokenized with appropriate EOS/BOS tokens and prompt masks."], "supporting_evidence": ["Discusses zero inference latency overhead: adapter weights can be merged back into the base model weights at deployment time (W_new = W_0 + (alpha/r)*B*A).", "Explains multi-tenant deployment: serving a single frozen base model in VRAM and dynamically swapping lightweight LoRA adapter weights per request.", "Examples, frameworks, or thresholds mentioned: <1%, Low-Rank Adaptation, delta_W = B * A, where rank r << d.", "Examples, frameworks, or thresholds mentioned: NF4, DQ."], "negative_evidence": ["Claims LoRA modifies all original model weights in place during forward/backward passes.", "Assumes QLoRA requires higher GPU VRAM than full 16-bit fine-tuning."], "partial_credit": ["Explains that LoRA trains small adapters instead of the whole model and QLoRA quantizes the model to 4-bit, but lacks mathematical detail on low-rank decomposition or specific layers tuned."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 180, 'Walk through the steps to fine-tune a small language model (or LLaMA 2) for a task, including SFT and pseudo-code for a LoRA pipeline (dataset loading, tokenization, mapping).', '{"required_evidence": ["Outlines the end-to-end workflow: data preparation and curation, base model and tokenizer selection, quantization setup, PEFT/LoRA configuration, and training Face SFTTrainer or PyTorch loop.", "Details pseudo-code / code components: 1. Loading tokenizer and dataset . 2. Quantization config ). 3. Loading model with AutoModelForCausalLM.from_pretrained. 4. Defining LoraConfig and wrapping with get_peft_model. 5. Training execution with TrainingArguments and SFTTrainer passing dataset, max_seq_length, and formatting function.", "Discusses validation, loss monitoring, and adapter artifact saving )."], "supporting_evidence": ["Explains masking the prompt tokens so the cross-entropy loss is computed exclusively on generated response tokens (DataCollatorForCompletionOnlyLM).", "Mentions merging weights using model.merge_and_unload() for optimized production export to GGUF or vLLM.", "Examples, frameworks, or thresholds mentioned: instruction-response pairs, e.g., Llama-2-7b-hf, BitsAndBytes 4-bit config, LoraConfig.", "Examples, frameworks, or thresholds mentioned: load_dataset, BitsAndBytesConfig(load_in_4bit=True, bnb_4bit_quant_type=''nf4'', r=8, lora_alpha=16, target_modules=[''q_proj'', ''v_proj''], lora_dropout=0.05, task_type=''CAUSAL_LM''."], "negative_evidence": ["Omits tokenizer padding/EOS token configuration leading to infinite generation loops.", "Computes gradient loss across the entire prompt instruction rather than response tokens."], "partial_credit": ["Lists the conceptual steps (load model, prepare data, train), but lacks pseudo-code, LoRA configuration specifics, or quantization details."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 180, 'What does upweighting fraud transactions during synthetic data generation do to the dataset?', '{"required_evidence": ["Alters class distribution: significantly inflates the prevalence of fraud transactions relative to normal transactions compared to the severe real-world class imbalance .", "Impacts model learning: exposes the downstream classifier to a richer variety of fraud patterns, preventing the model from collapsing into trivial majority-class prediction .", "Risks and unintended consequences: introduces class prior shift / probability distortion, causing downstream models to output over-calibrated, inflated fraud probability scores in production unless re-calibrated or down-weighted during loss calculation."], "supporting_evidence": ["Discusses synthetic data generation techniques: using conditional tabular GANs (CTGAN), diffusion models, or LLMs conditioned on fraud labels to generate realistic synthetic feature correlations.", "Explains probability threshold re-calibration and cost-sensitive learning to compensate for altered priors.", "Examples, frameworks, or thresholds mentioned: e.g. converting 0.1% fraud into 20-50% in the synthetic sample.", "Examples, frameworks, or thresholds mentioned: predicting all transactions as legitimate."], "negative_evidence": ["Assumes upweighting synthetic fraud data has zero negative effect on production false-positive rates.", "Claims upweighting reduces the absolute number of fraud edge cases generated."], "partial_credit": ["Mentions that upweighting helps the model see more fraud examples, but fails to discuss the risk of class prior distortion or increased false positives."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'Describe a generation pipeline: prompt templating, context passing, and where the LLM sits.', '{"required_evidence": ["Prompt templating: ingests user input and parameters into parameterized templates, injecting system instructions, role definitions, formatting rules, and dynamic few-shot examples.", "Context passing : injects retrieved external data into designated context placeholders within the assembled prompt, ensuring token limits are not exceeded.", "Where the LLM sits and downstream handling: the LLM acts as the central inference engine receiving the assembled prompt and returning generated tokens; the raw output is intercepted by post-processing layers before returning to the client."], "supporting_evidence": ["Details token streaming architecture: yielding tokens asynchronously via Server-Sent Events (SSE) or WebSockets while running parallel safety guardrail buffers.", "Mentions caching layers (e.g. exact match or semantic cache) positioned before the LLM invocation to save compute and cost.", "Examples, frameworks, or thresholds mentioned: e.g. Jinja2, LangChain PromptTemplate.", "Examples, frameworks, or thresholds mentioned: enrichment / retrieval, e.g., vector search chunks, SQL query results, user session state, short-term conversational history."], "negative_evidence": ["Places the LLM before context retrieval, expecting the LLM to fetch database records internally without external pipeline tools.", "Assumes raw LLM text is returned directly to end users without validation or parsing in production systems."], "partial_credit": ["Describes filling a template with user input and sending it to an LLM, but misses context retrieval integration, token limit handling, or post-processing validation."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you detect token-limit problems that fail silently?', '{"required_evidence": ["Explains checking provider response metadata and finish reasons .", "Explains implementing pre-call token counting using exact tokenizers rather than rough character heuristics.", "Describes monitoring output completeness ."], "supporting_evidence": ["Describes setting up automated alert thresholds for unexpected max_tokens exhaustion in observability tools (e.g., Langfuse, Helicone).", "Discusses handling hidden context truncation in embedding models where inputs exceeding token limits are silently sliced.", "Examples, frameworks, or thresholds mentioned: e.g., finish_reason == ''length'' instead of ''stop''.", "Examples, frameworks, or thresholds mentioned: e.g., tiktoken for OpenAI, Anthropic token counting API."], "negative_evidence": ["Assumes that hitting a token limit will always raise an HTTP 4xx/5xx error exception in the client SDK.", "Relies on character-to-token division approximations (like characters / 4) for safety-critical token boundaries."], "partial_credit": ["Mentions checking if the generated text is cut off or inspecting finish_reason, but does not mention pre-call token calculation or schema validation failures."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 180, 'How do you control token usage and cost (prompt caching, summarization, smaller and open-source models, monitoring)?', '{"required_evidence": ["Explains prompt caching mechanisms by structuring static system instructions, tool definitions, and few-shot examples as an unchanging prefix.", "Describes model routing / cascading .", "Details cost governance strategies: hard per-user/organization token quotas, automated budget alerts, and real-time usage tracking via gateway proxies."], "supporting_evidence": ["Discusses semantic caching (e.g., GPTCache, Redis) for near-identical user queries using vector similarity thresholds.", "Evaluates self-hosting smaller open-source models (e.g., Llama 3 8B on vLLM) for predictable fixed-cost workloads at high request volumes.", "Examples, frameworks, or thresholds mentioned: e.g., Anthropic/OpenAI prompt caching.", "Examples, frameworks, or thresholds mentioned: using cheap, fast models like frontier model-mini or Haiku for classification/simple tasks, escalating only complex reasoning to frontier model or Sonnet."], "negative_evidence": ["Suggests using top-tier frontier models for every subtask without routing or caching considerations.", "Claims prompt caching happens automatically across arbitrary, dynamically shifting prompts without prefix structuring."], "partial_credit": ["Mentions using cheaper models or shorter prompts without detailing prefix caching architecture or rate/budget governance."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 180, 'How do you scale an LLM application from a few users to millions? Which techniques reduce latency, and how do vLLM and Triton, or self-hosting versus managed services like Bedrock, trade off?', '{"required_evidence": ["Explains serving optimizations: continuous batching, PagedAttention, and tensor parallelism across GPUs.", "Compares self-hosting vs managed APIs .", "Discusses system-level scaling patterns: load-balanced API gateways, semantic caching, token streaming, asynchronous job queues for long-running generation, and multi-region failover."], "supporting_evidence": ["Explains speculative decoding, quantization (AWQ, FP8), and prefix caching at the serving engine level to accelerate inference.", "Details Triton Inference Server''s dynamic batching, model ensembles, and multi-framework support (PyTorch, TensorRT-LLM).", "Examples, frameworks, or thresholds mentioned: iteration-level batching, vLLM memory management reducing KV cache fragmentation.", "Examples, frameworks, or thresholds mentioned: vLLM/Triton: maximum throughput, low token latency, custom kernel optimization, but high operational complexity and fixed GPU reservation costs, AWS Bedrock: serverless scaling, zero hardware maintenance, pay-per-token, but potential quota limits and higher cost at high scale."], "negative_evidence": ["Recommends deploying vanilla HuggingFace PyTorch models in standard single-worker Flask apps for production millions-of-users scale.", "Believes managed APIs like Bedrock have zero latency or will never run into TPM/RPM rate limits under millions of users."], "partial_credit": ["Mentions using caching, load balancers, and Bedrock/vLLM, but lacks technical explanation of continuous batching, PagedAttention, or concrete GPU infrastructure trade-offs."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How do you support multi-tenant context and personalization?', '{"required_evidence": ["Explains data isolation across tenants: vector database namespace isolation or metadata filtering and relational schema isolation .", "Describes dynamic personalization retrieval: fetching user profile preferences, past session history, and role-based permissions, then injecting them into the prompt template without cross-tenant leakage.", "Details RBAC/ABAC enforcement at both retrieval and application gateway layers, ensuring users only access contextual data authorized for their role within the tenant."], "supporting_evidence": ["Mentions tenant-specific fine-tuned LoRA adapters or system prompt customization loaded dynamically at inference time.", "Discusses tenant-isolated prompt caching and rate-limiting partitions to prevent a ''noisy neighbor'' tenant from exhausting shared resources.", "Examples, frameworks, or thresholds mentioned: e.g., tenant_id mandatory filter in hybrid search, tenant per schema or row-level security."], "negative_evidence": ["Relies on the LLM prompt instructions alone (''You belong to Tenant A, do not show Tenant B data'') to maintain tenant isolation.", "Stores multi-tenant documents in a single vector index without metadata filtering or partition keys."], "partial_credit": ["Discusses adding tenant_id to database queries, but does not address vector database partition strategies, personalization injection, or isolation enforcement."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How do you design for failures from external services or LLMs?', '{"required_evidence": ["Explains resilience patterns: exponential backoff with jitter for transient errors and Circuit Breaker pattern to fail fast when downstream services become unresponsive.", "Details multi-provider fallback and model routing .", "Describes graceful degradation strategies ."], "supporting_evidence": ["Mentions idempotent request handling and distributed tracing (OpenTelemetry) to track upstream root causes.", "Discusses dead-letter queues (DLQ) for asynchronous LLM tasks and automated retry pipelines.", "Examples, frameworks, or thresholds mentioned: HTTP 429 / 503.", "Examples, frameworks, or thresholds mentioned: e.g., routing OpenAI outages to Anthropic Claude or AWS Bedrock with prompt/schema translation."], "negative_evidence": ["Recommends simple immediate retries without backoff or jitter, which can cause stampeding herd problems.", "Has no fallback plan for provider outages, assuming 100% cloud provider availability."], "partial_credit": ["Mentions try/except blocks and retries, but does not discuss circuit breakers, fallback providers, or graceful degradation."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'SPECIFIC', 180, 'How do you stream tokens between backend and frontend (WebSockets, buffering, throttling)?', '{"required_evidence": ["Compares Server-Sent Events and WebSockets, explaining that SSE is typically preferred for unidirectional token streaming due to simplicity, HTTP/2 multiplexing, and built-in reconnection.", "Explains backend token streaming: consuming async generator streams from the LLM provider SDK and flushing SSE events formatted as data: {...} .", "Discusses client-side and server-side buffering and throttling ."], "supporting_evidence": ["Discusses managing backpressure, connection drops, client-side abort controllers (fetch AbortSignal), and state cleanup on disconnection.", "Explains handling Markdown/syntax-highlighting stream reconstruction on the frontend without UI jitter.", "Examples, frameworks, or thresholds mentioned: SSE.", "Examples, frameworks, or thresholds mentioned: e.g., async for chunk in response."], "negative_evidence": ["Recommends standard polling (HTTP long polling) for token streaming or suggests re-rendering the entire chat UI on every single token arrival without batching."], "partial_credit": ["Explains basic SSE or WebSockets, but omits discussion of frontend rendering performance, chunk buffering, or stream cancellation."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'How do you pass user-specific data (such as a user ID) through the system without exposing it to the LLM?', '{"required_evidence": ["Explains state decoupling: maintaining user_id and sensitive user metadata strictly in the backend execution context rather than in the LLM prompt.", "Describes tokenization / pseudonymization: replacing identifiers with opaque session tokens or placeholders if context requires referring to the user.", "Explains tool execution scoping: the LLM is given tools that take business parameters ), while the backend tool runner automatically injects the verified user_id from the authenticated session context."], "supporting_evidence": ["Discusses preventing IDOR (Insecure Direct Object Reference) vulnerabilities where an LLM is manipulated into providing an arbitrary user_id to an API.", "Mentions auditing and zero-retention data agreements with LLM providers.", "Examples, frameworks, or thresholds mentioned: session token, JWT, or database record.", "Examples, frameworks, or thresholds mentioned: e.g., <USER_SESSION_REF>."], "negative_evidence": ["Suggests putting the real user_id, SSN, or sensitive user identifier directly in the prompt text and telling the LLM ''do not reveal this''."], "partial_credit": ["Mentions masking the user ID or using an internal session ID, but fails to explain how backend tool execution binds authenticated identity securely."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'How do you validate and enforce safety on LLM-generated SQL?', '{"required_evidence": ["Explains AST parsing to programmatically ensure the query contains only SELECT statements and blocks DDL/DML .", "Details database-level security enforcement: executing queries against a read-only database user/replica with strict connection timeouts, query cost limits, and statement row limits .", "Describes defense against SQL injection / prompt injection: parameterizing dynamic values extracted by the LLM and disallowing multi-statement queries ."], "supporting_evidence": ["Mentions data masking and column-level access control (row-level security / column masking) to restrict access to sensitive fields.", "Discusses running EXPLAIN on the generated query to check for catastrophic Cartesian joins before execution.", "Examples, frameworks, or thresholds mentioned: Abstract Syntax Tree, using tools like SQLGlot or pg_query, DROP, DELETE, UPDATE, INSERT, ALTER.", "Examples, frameworks, or thresholds mentioned: LIMIT."], "negative_evidence": ["Relies solely on prompt instructions (''You are a safe SQL generator, never generate DROP TABLE'') as the safety mechanism.", "Uses simple regex or string contains checks (e.g., if ''DROP'' in query) which are easily bypassed with comments or lowercase variations."], "partial_credit": ["Mentions using a read-only database user, but misses AST parsing, AST validation, or parameterization."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'How do you build a workflow with permission checks, approvals and automated ticket creation?', '{"required_evidence": ["Explains workflow orchestration: utilizing state engines to model state transitions, approval pauses, and retries.", "Describes permission and RBAC enforcement: validating the requester''s identity, role, and authorization before advancing the workflow or triggering actions.", "Details human-in-the-loop approval mechanics: emitting webhook/Slack/email approval requests, securely waiting for an authorized signature/action, and idempotently calling external ticketing APIs ."], "supporting_evidence": ["Explains audit logging and cryptographic nonces/tokens for one-time approval links.", "Discusses automated timeout and escalation policies if an approval request is not reviewed within an SLA.", "Examples, frameworks, or thresholds mentioned: e.g., Temporal, AWS Step Functions, LangGraph.", "Examples, frameworks, or thresholds mentioned: HITL, Jira/ServiceNow."], "negative_evidence": ["Allows an autonomous agent to execute sensitive ticket actions or system modifications without deterministic permission verification."], "partial_credit": ["Describes calling Jira APIs and checking a user role, but lacks a stateful orchestration pattern (e.g., Temporal/Step Functions) or secure HITL pause-and-resume mechanisms."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 180, 'How do you use Bedrock with Claude (or SageMaker) to invoke models from an application?', '{"required_evidence": ["Explains authentication and IAM: configuring AWS IAM roles with bedrock:InvokeModel / bedrock:InvokeModelWithResponseStream permissions and assuming roles SDK .", "Details invoking Claude Converse API or invoke_model: passing model ID, formatting messages payload, and parsing the response body.", "Compares Bedrock vs SageMaker: Bedrock is a serverless, managed model-as-a-service API with pay-per-token pricing; SageMaker requires provisioning dedicated endpoint instances with hourly compute costs."], "supporting_evidence": ["Explains streaming responses in Bedrock using InvokeModelWithResponseStream and handling event chunk streams.", "Discusses Bedrock Guardrails integration and cross-region inference profiles.", "Examples, frameworks, or thresholds mentioned: boto3.", "Examples, frameworks, or thresholds mentioned: e.g., anthropic.claude-3-5-sonnet-...."], "negative_evidence": ["Hardcodes AWS access keys and secret keys in application code instead of using IAM roles.", "Confuses Bedrock (serverless model APIs) with SageMaker (dedicated infrastructure hosting)."], "partial_credit": ["Mentions boto3.client(''bedrock-runtime'') and invoking a model, but does not explain IAM configuration or compare Bedrock with SageMaker."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'Which LLM would you use as the judge, and how do you avoid self-preference bias?', '{"required_evidence": ["Recommends using frontier reasoning models that possess significantly higher reasoning capabilities than the models being evaluated.", "Explains self-preference bias: models systematically score outputs generated by their own family or architecture higher due to stylistic and token distribution familiarity.", "Details mitigations: cross-model evaluation, ensemble of multiple judges from different model families, anonymizing style/formatting markers, and running pairwise position-swapping."], "supporting_evidence": ["Discusses fine-tuning specialized open-weight judge models (e.g., Prometheus 2) explicitly aligned with human feedback and rubrics.", "Explains measuring judge calibration against human expert annotations (Spearman/Pearson correlation).", "Examples, frameworks, or thresholds mentioned: e.g., frontier model, frontier model.", "Examples, frameworks, or thresholds mentioned: using Claude to judge GPT or vice-versa."], "negative_evidence": ["Uses the identical model being evaluated as the sole judge and ignores self-preference bias entirely."], "partial_credit": ["Mentions using frontier model as judge, but does not provide concrete techniques to detect and mitigate self-preference bias."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'What data-quality issues should you check before applying a judge to a dataset (bias, duplicates, PII, inaccuracies)?', '{"required_evidence": ["Identifies critical data defects: duplicate/near-duplicate samples, PII/confidential data leakage .", "Explains ground-truth inaccuracies: faulty reference answers, ambiguous ground truth, and factual errors in the test set that cause the judge to penalize correct answers.", "Details class and representation imbalance: systemic bias in question complexity, domain distribution, or demographic skew that prevents fair evaluation."], "supporting_evidence": ["Mentions automated deduplication techniques (MinHash, embeddings cosine similarity) and PII masking tools (Presidio).", "Discusses data contamination checks to ensure test set queries were not present in the model''s pre-training corpus.", "Examples, frameworks, or thresholds mentioned: skewing metric distributions, violating compliance when passed to judge APIs."], "negative_evidence": ["Assumes raw uncleaned logs can be directly fed into an evaluation pipeline without validation or deduplication."], "partial_credit": ["Lists PII and duplicates, but lacks explanation of how inaccuracies in ground-truth labels undermine the reliability of the judge."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you use DeepEval and CI/CD (for example GitHub Actions) with a golden dataset?', '{"required_evidence": ["Explains test suite construction with DeepEval: defining test cases using the golden dataset asserting specific metrics with quantitative pass thresholds.", "Details CI/CD workflow integration : triggering evaluation runs on pull requests, caching dependencies, securely accessing API keys Secrets, and executing pytest/deepeval CLI.", "Explains gatekeeping and regression prevention: failing the CI build if evaluation scores drop below defined thresholds, blocking PR merges, and publishing evaluation summary reports to PR comments."], "supporting_evidence": ["Discusses managing evaluation cost and runtimes in CI: running a fast smoke-test subset on PRs and running the comprehensive golden dataset on nightly builds.", "Mentions tracking evaluation results over time on Confident AI / DeepEval dashboard.", "Examples, frameworks, or thresholds mentioned: LLMTestCase, e.g., AnswerRelevancyMetric, FaithfulnessMetric, HallucinationMetric.", "Examples, frameworks, or thresholds mentioned: e.g., GitHub Actions."], "negative_evidence": ["Suggests running an exhaustive 10,000-sample LLM evaluation on every single git commit without cost or concurrency limits.", "Treats LLM testing purely as deterministic string assertion unit tests."], "partial_credit": ["Mentions running DeepEval in GitHub Actions, but fails to explain metric thresholds, pull request gating, or golden dataset integration."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'If a live application starts hallucinating, what do you check?', '{"required_evidence": ["Traces the retrieval pipeline first: checks if retrieved context was empty, irrelevant, truncated, or contained contradictory/noisy information .", "Inspects prompt assembly and context limits: verifies whether system prompt instructions were diluted, corrupted, or truncated due to context window overflow or model updates.", "Examines model inference parameters and upstream changes: verifies temperature/top-p settings, recent prompt revisions, provider model version drift ."], "supporting_evidence": ["Describes inspecting production tracing tools (Langfuse, LangSmith) to review the exact raw prompt sent to the API and the raw response.", "Mentions checking embedding model drift or index corruption in the vector database.", "Examples, frameworks, or thresholds mentioned: retrieval failure vs generation failure.", "Examples, frameworks, or thresholds mentioned: e.g., silent model deprecation/point-release shifts."], "negative_evidence": ["Blames the user query immediately without inspecting retrieval quality, raw prompts, or model parameters.", "Immediately jumps to fine-tuning the base model without diagnosing retrieval or prompt failures."], "partial_credit": ["Suggests checking the prompt and temperature, but misses retrieval context analysis, token truncation, and model drift."]}', 1),
    ('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you evaluate chatbot quality, combining human and LLM scoring?', '{"required_evidence": ["Explains hybrid evaluation architecture: judges for high-volume, automated continuous evaluation across predefined rubrics, while sampling a subset for human expert review.", "Describes calibration: using human scores as the gold standard to calibrate the LLM judge''s prompts, few-shot examples, and score thresholds via correlation analysis.", "Details combining implicit/explicit user signals: tracking user thumbs-up/down, session abandonment, copy-paste events, and escalation to human agents alongside automated scoring."], "supporting_evidence": ["Discusses active learning: routing conversations where the LLM judge has low confidence or where metrics diverge directly to human review queues.", "Mentions inter-annotator agreement metrics (Fleiss'' Kappa) among human evaluators.", "Examples, frameworks, or thresholds mentioned: helpfulness, tone, policy compliance."], "negative_evidence": ["Relies solely on human scoring (unscalable) or purely on LLM scoring without ever validating against human preferences."], "partial_credit": ["Mentions getting user thumbs up/down and having an LLM grade responses, but does not explain calibration or active sampling."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you monitor, trace and observe LLM applications in production (latency, token usage, errors)?', '{"required_evidence": ["Explains distributed tracing and observability tools: deploying LLM-specific telemetry frameworks to trace full call chains .", "Details key production metrics: latency, token economics, error rates .", "Describes alerting and quality monitoring: setting up alerts on error spikes, cost surges, latency anomalies, and automated drift/guardrail violation rates."], "supporting_evidence": ["Mentions exporting traces to Prometheus and Grafana or Datadog for unified enterprise infrastructure dashboards.", "Discusses privacy-preserving logging: masking PII and customer sensitive payloads before storing traces.", "Examples, frameworks, or thresholds mentioned: OpenTelemetry, Langfuse, LangSmith, Arize Phoenix, Helicone, spans, prompts, intermediate tool calls, raw completions.", "Examples, frameworks, or thresholds mentioned: Time-To-First-Token [TTFT], end-to-end latency, prompt tokens, completion tokens, cached tokens, cost per request, HTTP 429 rate limits, 5xx server errors, schema parse failures."], "negative_evidence": ["Relies solely on basic print() statements or generic web server HTTP access logs that do not capture tokens, intermediate prompts, or tool execution spans."], "partial_credit": ["Lists monitoring latency and tokens with LangSmith or Datadog, but fails to explain TTFT, span-level tracing, or cost/guardrail alerting."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'What security and compliance checks belong on prompts and responses?', '{"required_evidence": ["Explains prompt security checks: prompt injection detection, jailbreak identification, PII/PCI detection, and input length/token limits to prevent denial-of-service.", "Explains response security checks: confidential data leakage detection, toxicity and harmful content screening, and hallucinated PII scrubbing.", "Details compliance and audit logging: immutable audit logging of prompts and responses, retention policy enforcement, and enterprise policy verification."], "supporting_evidence": ["Mentions compliance standards like SOC 2, HIPAA, GDPR, and ISO 27001 in GenAI architectures.", "Explains zero-data-retention (ZDR) agreements with third-party foundation model providers.", "Examples, frameworks, or thresholds mentioned: SSN, credit card, passwords.", "Examples, frameworks, or thresholds mentioned: source code, internal URLs, secrets."], "negative_evidence": ["Logs raw user PII and confidential enterprise outputs into unencrypted, unrotated log files.", "Believes security checks are only needed on inputs, ignoring data leakage in generated outputs."], "partial_credit": ["Lists PII detection and toxic content filtering, but lacks compliance logging, prompt injection checks, or data retention considerations."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'EASY', 'SPECIFIC', 180, 'How do you define token lifetimes and validate them?', '{"required_evidence": ["Explains access token vs. refresh token lifecycles: short-lived access tokens to minimize exposure if compromised, paired with longer-lived refresh tokens stored securely .", "Details validation mechanics: checking the exp claim against current server Unix epoch timestamp, allowing a small clock skew .", "Explains refresh token rotation and revocation: issuing a new refresh token upon each refresh and invalidating entire token families if a previously used refresh token is presented ."], "supporting_evidence": ["Discusses storing refresh tokens in secure, HttpOnly, SameSite cookies to mitigate XSS and CSRF attacks.", "Mentions sliding sessions vs absolute session timeouts for sensitive enterprise systems.", "Examples, frameworks, or thresholds mentioned: e.g., 5 to 15 minutes, e.g., 7 to 30 days, e.g., HTTP-only cookie.", "Examples, frameworks, or thresholds mentioned: expiration time, e.g., 30-60 seconds."], "negative_evidence": ["Sets access token expiration to years or indefinite lifespan to ''avoid annoying the user''.", "Fails to validate the exp claim on incoming requests, accepting expired tokens indefinitely."], "partial_credit": ["Explains that tokens have an expiration timestamp and need to be refreshed, but fails to distinguish access vs refresh token lifecycles or rotation security."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'Security & Compliance', 'MEDIUM', 'SPECIFIC', 180, 'How would you test token authentication: expired, invalid and cross-user access?', '{"required_evidence": ["Details mocking or generating expired JWTs and asserting HTTP 401 Unauthorized.", "Tests invalid and tampered tokens and asserts rejection with 401 Unauthorized.", "Explains test cases for cross-user authorization by sending User A''s valid token against User B''s resource IDs, verifying HTTP 403 Forbidden or 404 Not Found."], "supporting_evidence": ["Mentions testing refresh token rotation, replay attacks, and token revocation lists (blocklists in Redis).", "Discusses automating these test scenarios across CI/CD pipelines using test fixtures in frameworks like Pytest or Supertest.", "Examples, frameworks, or thresholds mentioned: e.g., setting past exp timestamps or using time-freezing libraries like freezegun.", "Examples, frameworks, or thresholds mentioned: e.g., invalid signatures, altered payloads, malformed structures, or wrong algorithm headers."], "negative_evidence": ["Confuses authentication (401 Unauthorized) with authorization (403 Forbidden), or assumes a valid token grants universal access to any resource without ID checks.", "Suggests manually testing expired tokens by waiting for hours in real time rather than manipulating the exp claim or mocking system time."], "partial_credit": ["Explains how to test expired and invalid tokens using Postman or unit tests, but fails to address cross-user access or IDOR testing."]}', 1),
    ('TECHNICAL', 'Software Engineering', 'Software Architecture & Design', 'MEDIUM', 'SPECIFIC', 180, 'What are the challenges of building scalable AI assistants and backends on AWS (latency, concurrency, integration)?', '{"required_evidence": ["Analyzes latency bottlenecks: compounds of network round-trips, Time-To-First-Token, sequential agent reasoning steps, and vector search delays, mitigating with SSE streaming, semantic caching, and model quantization.", "Explains concurrency and throughput challenges: hitting provider rate limits, API Gateway connection timeouts, and GPU VRAM capacity, mitigating via queuing, multi-model/multi-region routing, and backpressure.", "Details integration and orchestration complexities: managing conversational state across stateless serverless layers, handling long-running tool timeouts, and error handling across heterogeneous AWS microservices."], "supporting_evidence": ["Discusses AWS Step Functions or LangGraph integration on ECS for managing complex agent state machines with retry policies.", "Mentions cost control under high concurrency: avoiding runaway cloud bills from unbounded LLM agent loops or token explosions.", "Examples, frameworks, or thresholds mentioned: TTFT, Redis.", "Examples, frameworks, or thresholds mentioned: TPM/RPM, SQS."], "negative_evidence": ["Treats AI backends identically to traditional CRUD web applications without accounting for non-deterministic execution times, token generation latency, or TPM/RPM rate limits.", "Suggests handling massive concurrency by simply launching unconstrained synchronous AWS Lambda functions hitting LLM APIs, ignoring downstream 429 throttling and connection pool exhaustion."], "partial_credit": ["Identifies general cloud scaling issues like CPU load and database connections, but provides few AI-specific insights regarding token limits, TTFT, or agentic loop timeouts."]}', 1),
    ('TECHNICAL', 'DevOps and Cloud', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 180, 'How do you productionize an ML/LLM system (infrastructure, API deployment, monitoring)?', '{"required_evidence": ["Outlines infrastructure architecture: provisioning scalable compute, secure VPC networking, and persistent storage/vector databases with IAM security.", "Covers API deployment engineering: containerizing high-throughput inference engines, implementing asynchronous API wrappers, token streaming, and canary/blue-green rollout strategies.", "Details monitoring and observability across operational metrics and AI quality metrics ."], "supporting_evidence": ["Mentions implementing automated CI/CD evaluation gates where candidate models or prompts are tested against golden datasets before production promotion.", "Discusses semantic caching layers to drastically reduce repeat query costs and improve latency.", "Examples, frameworks, or thresholds mentioned: EKS with GPU node groups or managed endpoints like SageMaker/Bedrock.", "Examples, frameworks, or thresholds mentioned: e.g., vLLM, Triton, FastAPI, SSE."], "negative_evidence": ["Suggests deploying a simple Flask or Jupyter notebook directly on a raw VM with no containerization, no streaming, and no observability as a production deployment.", "Ignores LLM-specific monitoring, assuming traditional HTTP status code monitoring alone is sufficient for AI systems."], "partial_credit": ["Covers standard DevOps practices (Docker, CI/CD, basic CPU monitoring) but misses LLM-specific operational aspects like vLLM/GPU serving, TTFT, token metrics, or hallucination tracking."]}', 1);
